function makeV2MoleculeSet(lang){
  const out={};
  for(const id in MOLS_EN){
    const base=MOLS_EN[id];
    const curated=lang==='fr'?V2_MOLECULE_NAMES_FR:lang==='zh'?V2_MOLECULE_NAMES_ZH:lang==='it'?V2_MOLECULE_NAMES_IT:null;
    const fact=lang==='it'&&V2_MOLECULE_FACTS_IT[id]?V2_MOLECULE_FACTS_IT[id]:v2Text(base.fa,lang);
    out[id]=Object.assign({},base,{n:(curated&&curated[id])||v2Text(base.n,lang),w:v2Text(base.w,lang),fa:fact});
  }
  return out;
}
function makeV2ElementInfo(lang){
  const out={};
  for(const id in ELINFO_EN){
    const base=ELINFO_EN[id],curated=(ELEMENT_NAMES_I18N[lang]||{})[id];
    const name=(lang==='fr'||lang==='it')&&curated?curated.charAt(0).toLocaleUpperCase(lang==='fr'?'fr-FR':'it-IT')+curated.slice(1):curated;
    const fact=lang==='it'&&V2_ELEMENT_FACTS_IT[id]?V2_ELEMENT_FACTS_IT[id]:v2Text(base.fa,lang);
    out[id]=Object.assign({},base,{n:name||v2Text(base.n,lang),fa:fact});
  }
  return out;
}
