for(const [id,base] of Object.entries(R113_NEW_MOLS)){for(const [lang,set] of Object.entries({en:MOLS_EN,tr:MOLS_TR,de:MOLS_DE,es:MOLS_ES,pt:MOLS_PT,ja:MOLS_JA,fr:MOLS_FR,zh:MOLS_ZH,it:MOLS_IT,ko:MOLS_KO,ru:MOLS_RU})){set[id]=Object.assign({},base,{n:(R113_NEW_MOL_NAMES[lang]&&R113_NEW_MOL_NAMES[lang][id])||base.n,fa:(R113_NEW_MOL_FACT[lang]&&R113_NEW_MOL_FACT[lang][id])||''});}}
const R113_BIO_COPY={"en":{"bioAssemblyTitle":"🧬 Bio Assembly","bioAssemblyDesc":"Simplified DNA-inspired model: collect the A–T pair, C–G pair and sugar–phosphate backbone fragment. The assembly field then opens; finish the real target molecule. Real DNA is much more complex and is not built atom by atom this way."},"tr":{"bioAssemblyTitle":"🧬 Bio Assembly","bioAssemblyDesc":"DNA’dan esinlenen sadeleştirilmiş model: A–T çiftini, C–G çiftini ve şeker–fosfat omurga parçasını topla. Montaj alanı açılınca gerçek hedef molekülü tamamla. Gerçek DNA çok daha karmaşıktır ve atom atom bu şekilde kurulmaz."},"de":{"bioAssemblyTitle":"🧬 Bio Assembly","bioAssemblyDesc":"Vereinfachtes DNA-inspiriertes Modell: Sammle A–T-Paar, C–G-Paar und Zucker-Phosphat-Rückgratfragment. Danach öffnet sich das Montagefeld; vollende das echte Zielmolekül. Reale DNA ist viel komplexer."},"es":{"bioAssemblyTitle":"🧬 Bio Assembly","bioAssemblyDesc":"Modelo simplificado inspirado en el ADN: recoge el par A–T, el par C–G y el fragmento de esqueleto azúcar–fosfato. Después se abre el campo de montaje; completa la molécula real."},"pt":{"bioAssemblyTitle":"🧬 Bio Assembly","bioAssemblyDesc":"Modelo simplificado inspirado no DNA: colete o par A–T, o par C–G e o fragmento da espinha dorsal açúcar–fosfato. Depois o campo de montagem abre; complete a molécula real."},"ja":{"bioAssemblyTitle":"🧬 バイオ組立","bioAssemblyDesc":"DNAに着想を得た簡略化モデルです。A–Tペア、C–Gペア、糖–リン酸骨格フラグメントを集めると組立フィールドが開き、実在する目標分子を完成できます。実際のDNAははるかに複雑です。"},"fr":{"bioAssemblyTitle":"🧬 Bio Assembly","bioAssemblyDesc":"Modèle simplifié inspiré de l’ADN : collecte la paire A–T, la paire C–G et le fragment de squelette sucre–phosphate. Le champ d’assemblage s’ouvre ensuite ; termine la molécule réelle."},"zh":{"bioAssemblyTitle":"🧬 生物组装","bioAssemblyDesc":"受DNA启发的简化模型：收集A–T碱基对、C–G碱基对和糖–磷酸骨架片段。随后组装区域开启，再完成真实目标分子。真实DNA远比这个模型复杂。"},"it":{"bioAssemblyTitle":"🧬 Bio Assembly","bioAssemblyDesc":"Modello semplificato ispirato al DNA: raccogli la coppia A–T, la coppia C–G e il frammento dello scheletro zucchero–fosfato. Poi si apre il campo di assemblaggio; completa la molecola reale."}};

/* R104 startup hotfix: apply mechanic copy only AFTER I18N is initialized. */

function mxFinalizeMoleculeWinData(set){
  if(!set)return;
  const languages={en:MOLS_EN,tr:MOLS_TR,de:MOLS_DE,es:MOLS_ES,pt:MOLS_PT,ja:MOLS_JA,fr:MOLS_FR,zh:MOLS_ZH,it:MOLS_IT,ko:MOLS_KO,ru:MOLS_RU};
  const language=Object.keys(languages).find(k=>languages[k]===set)||'en';
  const labels={"tr": "Rezonans Modeli", "en": "Resonance Model", "de": "Resonanzmodell", "es": "Modelo de resonancia", "pt": "Modelo de ressonância", "ja": "共鳴モデル", "fr": "Modèle de résonance", "zh": "共振模型", "it": "Modello di risonanza", "ru": "Резонансная модель"},description={"tr": "Bu, Moleculox için tasarlanmış bir araştırma desenidir. Formül atom içeriğini, kesik çizgiler bulmaca bağlantılarını gösterir; gerçek bir molekülün kimyasal bağ şeması değildir.", "en": "This is a research pattern designed for Moleculox. The formula lists its atoms; dashed lines show puzzle connections, not a real molecule’s chemical bonds.", "de": "Dies ist ein Forschungsmuster für Moleculox. Die Formel nennt die Atome; gestrichelte Linien zeigen Puzzleverbindungen, keine chemischen Bindungen eines echten Moleküls.", "es": "Este es un patrón de investigación de Moleculox. La fórmula enumera sus átomos; las líneas discontinuas indican conexiones del puzle, no enlaces químicos de una molécula real.", "pt": "Este é um padrão de pesquisa do Moleculox. A fórmula lista os átomos; as linhas tracejadas mostram conexões do quebra-cabeça, não ligações químicas de uma molécula real.", "ja": "Moleculox用の研究パターンです。式は原子の種類と数、破線はパズルの接続を示します。実在分子の化学結合図ではありません。", "fr": "C’est un motif de recherche conçu pour Moleculox. La formule indique les atomes ; les pointillés représentent les connexions du puzzle, pas les liaisons chimiques d’une molécule réelle.", "zh": "这是为Moleculox设计的研究图案。化学式列出原子组成，虚线表示谜题连接，并非真实分子的化学键。", "it": "È uno schema di ricerca creato per Moleculox. La formula elenca gli atomi; le linee tratteggiate indicano collegamenti del rompicapo, non i legami chimici di una molecola reale.", "ru": "Это исследовательская схема, разработанная для Moleculox. Формула показывает состав атомов; пунктирные линии обозначают связи головоломки, а не химические связи реальной молекулы."};
  for(const[id,t]of Object.entries(window.MX_R180_TARGETS||{})){
    const original=set[t.source]||MOLS_EN[t.source];if(!original)continue;
    set[id]={...original,n:labels[language]+' '+t.level,shortName:labels[language]+' '+t.level,s:t.s.map(a=>a.slice()),researchPattern:true,xb:[],fa:description[language]};
    for(let i=0;i<set[id].s.length;i++)for(let j=i+1;j<set[id].s.length;j++)if(Math.abs(set[id].s[i][1]-set[id].s[j][1])+Math.abs(set[id].s[i][2]-set[id].s[j][2])===1)set[id].xb.push([i,j]);
  }

  for(const id in set){
    const m=set[id];if(!m||!Array.isArray(m.s)||!m.s.length)continue;
    const mx=Math.min(...m.s.map(a=>a[1])),my=Math.min(...m.s.map(a=>a[2]));
    m.key=m.s.map(a=>a[0]+','+(a[1]-mx)+','+(a[2]-my)).sort().join('|');

    let graph=Array.isArray(m.xb)&&m.xb.length?m.xb.map(p=>p.slice()):[];
    if(!graph.length)for(let i=0;i<m.s.length;i++)for(let j=i+1;j<m.s.length;j++)if(Math.abs(m.s[i][1]-m.s[j][1])+Math.abs(m.s[i][2]-m.s[j][2])===1&&!(m.s.length!==2&&m.s[i][0]==='H'&&m.s[j][0]==='H'))graph.push([i,j]);
    if(!m.researchPattern&&id==='N2F4'){graph=graph.filter(([i,j])=>!(m.s[i][0]==='F'&&m.s[j][0]==='F'));m.xb=graph;}
    const degrees=m.s.map(()=>0);for(const[i,j]of graph)if(m.s[i]&&m.s[j]){degrees[i]++;degrees[j]++;}
    if(m.researchPattern||m.s.some((a,i)=>(a[0]==='H'||a[0]==='F')&&degrees[i]>1)){
      m.researchPattern=true;m.fa=description[language];
      if(!m.shortName){m.chemicalReferenceName=m.n;m.n=labels[language]+' · '+m.f;m.shortName=labels[language];}
    }
    if(id==='H2')m.xb=[[0,1]];
    if(id==='C2Cl4')m.shortName=({tr:'Perkloroetilen',en:'Perchloroethylene',de:'Perchlorethen',es:'Percloroetileno',pt:'Percloroetileno',ja:'パークロロエチレン',fr:'Perchloroéthylène',zh:'四氯乙烯',it:'Percloroetilene',ru:'Перхлорэтилен'})[language];
    m.bs=new Set();
    const pairs=(Array.isArray(m.xb)&&m.xb.length)?m.xb:null;
    if(pairs){
      for(const pair of pairs){
        const i=pair&&pair[0],j=pair&&pair[1];
        if(!Number.isInteger(i)||!Number.isInteger(j)||!m.s[i]||!m.s[j]||i===j)continue;
        const dx=m.s[j][1]-m.s[i][1],dy=m.s[j][2]-m.s[i][2];
        if(m.s.length!==2&&m.s[i][0]==='H'&&m.s[j][0]==='H')continue;
        m.bs.add(m.s[i][0]+','+m.s[j][0]+','+dx+','+dy);
        m.bs.add(m.s[j][0]+','+m.s[i][0]+','+(-dx)+','+(-dy));
      }
    }else for(let i=0;i<m.s.length;i++)for(let j=i+1;j<m.s.length;j++){
      const dx=m.s[j][1]-m.s[i][1],dy=m.s[j][2]-m.s[i][2];
      if(Math.abs(dx)+Math.abs(dy)!==1)continue;
      if(m.s.length!==2&&m.s[i][0]==='H'&&m.s[j][0]==='H')continue;
      m.bs.add(m.s[i][0]+','+m.s[j][0]+','+dx+','+dy);
      m.bs.add(m.s[j][0]+','+m.s[i][0]+','+(-dx)+','+(-dy));
    }
  }
  // Keep legacy ID lookup for migration without adding unobtainable collection cards.
  for(const target of Object.values(window.MX_R180_TARGETS||{})){if(set[target.source])Object.defineProperty(set,target.source,{enumerable:false,configurable:true,writable:true,value:set[target.source]});}

}
Object.values({en:MOLS_EN,tr:MOLS_TR,de:MOLS_DE,es:MOLS_ES,pt:MOLS_PT,ja:MOLS_JA,fr:MOLS_FR,zh:MOLS_ZH,it:MOLS_IT,ko:MOLS_KO,ru:MOLS_RU}).forEach(mxFinalizeMoleculeWinData);
