for(const [id,base] of Object.entries(ELINFO_EN)){ELINFO_KO[id]=Object.assign({},ELINFO_KO[id]||base,{n:(ELEMENT_NAMES_I18N.ko[id]||v2Text(base.n,'ko')),fa:v2Text(base.fa,'ko')});}
for(const [id,base] of Object.entries(MOLS_EN)){MOLS_RU[id]=Object.assign({},MOLS_RU[id]||base,{n:v2Text(base.n,'ru'),w:v2Text(base.w,'ru'),fa:v2Text(base.fa,'ru')});}
for(const [id,base] of Object.entries(ELINFO_EN)){ELINFO_RU[id]=Object.assign({},ELINFO_RU[id]||base,{n:v2Text(base.n,'ru'),fa:v2Text(base.fa,'ru')});}

