function v2DeepCopy(value,lang){
  if(typeof value==='string')return v2Text(value,lang);
  if(Array.isArray(value))return value.map(item=>v2DeepCopy(item,lang));
  if(value&&typeof value==='object')return Object.fromEntries(Object.entries(value).map(([key,item])=>[key,v2DeepCopy(item,lang)]));
  return value;
}
