function r143SequentialChapterIndex(id){
  const match=/^R134_L(\d+)_/.exec(id),level=match?Number(match[1]):302;
  return level<=400?0:level<=415?1:level<=430?2:level<=445?3:level<=479?4:5;
}
function r135ElementPalette(structure){
  const out=[];
  for(const atom of (structure||[])){const col=EL[atom[0]]&&EL[atom[0]].c;if(col&&!out.includes(col))out.push(col);}
  return out.length?out.slice(0,4):['#7be8ff'];
}
for(const [id,ov] of Object.entries(R134_SEQUENTIAL_MOLS)){
  for(const [lang,set] of [['en',MOLS_EN],['tr',MOLS_TR],['de',MOLS_DE],['es',MOLS_ES],['pt',MOLS_PT],['ja',MOLS_JA],['fr',MOLS_FR],['zh',MOLS_ZH],['it',MOLS_IT],['ko',MOLS_KO]]){
    const chapterLabel=R143_SEQ_CHAPTER_LABELS[lang][r143SequentialChapterIndex(id)];
    set[id]={n:chapterLabel+' '+ov.f,f:ov.f,s:ov.s.map(a=>a.slice()),xb:ov.xb.map(p=>p.slice()),w:ov.w,fx:ov.fx,c:r135ElementPalette(ov.s),fa:R143_SEQ_FACT[lang]};
  }
}
