function nobelPermanentTitle(){return ml('NOBEL ÖDÜLLÜ BİLİM İNSANI','NOBEL LAUREATE','NOBELPREISTRÄGER','PREMIO NOBEL','LAUREADO NOBEL','ノーベル賞受賞者','LAURÉAT DU NOBEL','诺贝尔奖得主','PREMIO NOBEL');}
function postNobelCareerAt(cur){
  cur=Math.max(0,Math.floor(Number(cur)||0));let found=null;
  for(const row of POST_NOBEL_CAREER)if(cur>=row.level)found=row;else break;
  return found;
}
function nextPostNobelCareer(cur){cur=Math.max(0,Math.floor(Number(cur)||0));return POST_NOBEL_CAREER.find(row=>row.level>cur)||null;}
function postNobelCareerNextHtml(cur){
  if(Math.max(0,Number(cur)||0)<NOBEL_LEVEL_INDEX+1)return '';
  const next=nextPostNobelCareer(cur);
  if(!next){const top=postNobelCareerAt(cur);return '<div class="labPurpose postNobelNext"><span>'+(top?top.icon:'👑')+'</span><div><b>'+ml('EN YÜKSEK ARAŞTIRMA RÜTBESİ','HIGHEST RESEARCH RANK','HÖCHSTER FORSCHUNGSRANG','RANGO MÁXIMO DE INVESTIGACIÓN','RANK MÁXIMO DE PESQUISA','最高研究ランク','RANG DE RECHERCHE MAXIMAL','最高科研等级','MASSIMO GRADO DI RICERCA')+'</b><small>'+(top?top.title():nobelPermanentTitle())+' · '+ml('Nobel onurun kalıcı.','Your Nobel honour remains permanent.')+'</small></div></div>';}
  return '<div class="labPurpose postNobelNext"><span>'+next.icon+'</span><div><b>'+ml('SONRAKİ RÜTBE','NEXT RANK','NÄCHSTER RANG','SIGUIENTE RANGO','PRÓXIMO RANK','次のランク','PROCHAIN RANG','下一等级','PROSSIMO GRADO')+' · L'+next.level+' · '+next.title()+'</b><small>+'+next.coins+' 🪙 · +'+next.rp+' RP · 🏆 '+nobelPermanentTitle()+'</small></div></div>';
}
function careerRankDisplay(cur){
  cur=Math.max(0,Math.floor(Number(cur)||0));
  if(cur>=NOBEL_LEVEL_INDEX+1){const post=postNobelCareerAt(cur);return post?{icon:post.icon,title:post.title(),nobel:true,level:post.level}:{icon:'🏆',title:nobelPermanentTitle(),nobel:true,level:301};}
  const tier=tierOf(cur);return {icon:DIPLOMAS[tier].icon,title:t('rank'+tier).replace(/^\S+\s/,''),nobel:false,level:cur};
}
function claimPostNobelCareer(oldCur,newCur){
  oldCur=Math.max(0,Math.floor(Number(oldCur)||0));newCur=Math.max(oldCur,Math.floor(Number(newCur)||0));
  save.researchAchievements=save.researchAchievements&&typeof save.researchAchievements==='object'?save.researchAchievements:{};
  let coins=0,rp=0,last=null,claimed=[];
  for(const row of POST_NOBEL_CAREER){
    if(!(oldCur<row.level&&newCur>=row.level))continue;
    const key='career_'+row.level;
    if(Math.max(0,Math.floor(Number(save.researchAchievements[key])||0))>0)continue;
    save.researchAchievements[key]=row.rp;addResearchPoints(row.rp);addCoins(row.coins);
    coins+=row.coins;rp+=row.rp;last=row;claimed.push(row.level);
  }
  return last?{last,coins,rp,claimed}:null;
}
