function semanticVoiceBank(character,event){
  // Russian's verified recording has two shifted semantic boundaries; only
  // those two cues differ from the canonical localized numbering.
  const override=LANG==='ru'&&(event==='clear3'||event==='lastMove')&&VOICE_EVENT_OVERRIDES.ru[event];
  const parity=(LANG==='en'?VOICE_PARITY_BANK_EN:VOICE_PARITY_BANK_LOCALIZED)[event];
  return override||parity||(VOICE_BANK[character]&&VOICE_BANK[character][event])||null;
}
function completionVoiceEvent(stars){
  const n=Math.max(0,Math.min(3,Math.floor(Number(stars)||0)));
  return 'clear'+n;
}
function playCharacterVoice(character,event,opts={}){
  if(!voiceEnabled())return false;
  const bank=semanticVoiceBank(character,event);if(!bank||!bank.length)return false;
  const pack=activeVoicePack(),files=bank.filter(name=>pack.sprite&&pack.sprite[name]);if(!files.length)return false;
  const nowMs=performance.now(),cooldown=Math.max(900,Number(opts.cooldown)||1800);
  if(!opts.force&&nowMs-lastVoiceAt<cooldown)return false;
  lastVoiceAt=nowMs;
  const item={character,event,name:shuffledVoiceName(character,event,files),duck:opts.duck==null?.32:clampAudio(opts.duck),expiresAt:nowMs+Math.max(3500,Number(opts.maxDelay)||7000)};
  // Never cut off a spoken line. Keep only a short, fresh queue so old menu
  // greetings cannot play much later inside a level.
  if(voiceQueue.length>=3)voiceQueue.shift();voiceQueue.push(item);drainVoiceQueue();return true;
}
function maybeVoice(character,event,chance=.35,opts={}){if(Math.random()>chance)return;playCharacterVoice(character,event,opts);}

// R19/R21 — menu voice belongs to the visible main menu, never to the studio/boot logo.
// The first gesture still unlocks and preloads audio, but it cannot enqueue speech.
let menuVoiceTimer=0,menuVoiceToken=0,menuVoiceLastAt=-1e9;
function isMenuVoiceEvent(event){return event==='menuFirst'||event==='menuReturn'||event==='menuHome'||event==='menu';}
function cancelPendingMenuVoice(){
  clearTimeout(menuVoiceTimer);menuVoiceTimer=0;menuVoiceToken++;
  for(let i=voiceQueue.length-1;i>=0;i--)if(isMenuVoiceEvent(voiceQueue[i]&&voiceQueue[i].event))voiceQueue.splice(i,1);
}
function menuProfileEstablished(){
  if(!save)return false;
  const progressed=Number(save.cur)>0||
    (save.disc&&Object.keys(save.disc).length)||(save.stars&&Object.keys(save.stars).length);
  // Fresh automatic guests carry tutorialDone=true only to prevent an unwanted
  // boot tutorial. That flag alone must not make their first greeting say
  // "Welcome back".
  return !!(save.menuVoiceSeen||progressed||(!save.autoGuest&&save.tutorialDone));
}
function scheduleMainMenuVoice(kind='entry',delay=620){
  cancelPendingMenuVoice();
  const token=menuVoiceToken;
  menuVoiceTimer=setTimeout(function attemptMenuVoice(){
    if(token!==menuVoiceToken)return;
    const menu=scr&&scr.splash;
    if(!menu||!menu.classList.contains('on')||document.hidden){return;}
    // Wait until the screen transition and responsive layout have fully settled.
    if(screenTransitionLock||document.body.classList.contains('mxUiTransitioning')){
      menuVoiceTimer=setTimeout(attemptMenuVoice,180);return;
    }
    const nowMs=performance.now();
    if(nowMs-menuVoiceLastAt<2600)return;
    // This is the single point that arms speech after the visible main menu.
    speechPlaybackArmed=true;
    const event=kind==='home'?'menuHome':(menuProfileEstablished()?'menuReturn':'menuFirst');
    if(playCharacterVoice('drE',event,{force:true,duck:.26,cooldown:0,maxDelay:2600})){
      menuVoiceLastAt=nowMs;
      if(save&&!save.menuVoiceSeen){save.menuVoiceSeen=true;persist();}
    }
  },Math.max(420,Number(delay)||620));
}

/* ---------- reliable HTML5 background music (iOS/Android/Web) ---------- */
const MUS={int:0};
let nearWinPulseTimer=0,nearWinPulseActive=false,nearWinPulseToken=0;
function playNearWinPulse(){
  if(!nearWinPulseActive||externalMusicMode||save.muM||save.muMu||!ac())return;
  const token=nearWinPulseToken,t=now()+.012;
  // A restrained laboratory-energy heartbeat layered under the music.
  // It does not alter playback speed or reveal the exact solution.
  osc(musicG,82,t,.24,'sine',.014,{atk:.035,f2:74,f2t:.20,lp:260});
  osc(musicG,164,t+.035,.18,'triangle',.006,{atk:.025,f2:148,f2t:.14,lp:520});
  setTimeout(()=>{
    if(!nearWinPulseActive||token!==nearWinPulseToken||externalMusicMode||save.muM||save.muMu||!ac())return;
    const t2=now()+.006;
    osc(musicG,92,t2,.18,'sine',.010,{atk:.025,f2:80,f2t:.15,lp:280});
  },265);
}
function startNearWinLayer(){
  if(nearWinPulseActive)return;
  nearWinPulseActive=true;nearWinPulseToken++;
  playNearWinPulse();
  clearInterval(nearWinPulseTimer);
  nearWinPulseTimer=setInterval(playNearWinPulse,1450);
}
function stopNearWinLayer(){
  if(!nearWinPulseActive&&!nearWinPulseTimer)return;
  nearWinPulseActive=false;nearWinPulseToken++;
  clearInterval(nearWinPulseTimer);nearWinPulseTimer=0;
}
function setIntensity(n){
  n=Math.max(0,Math.min(2,Number(n)||0));
  if(MUS.int===n)return;
  MUS.int=n;
  if(n===2)startNearWinLayer();else stopNearWinLayer();
}
const MP={mode:'menu',idx:0,started:false,src:null,err:0,blocked:false};
function randomTrackIdx(avoid){
  if(TRACKS.length<=1)return 0;
  let ni=Math.floor(Math.random()*TRACKS.length);
  if(ni===avoid)ni=(ni+1)%TRACKS.length;
  return ni;
}
function trackUrl(i){return TRACKS[Math.max(0,Math.min(TRACKS.length-1,Number(i)||0))];}
function isCurrentTrack(i){
  const wanted=trackUrl(i).split('/').pop();
  try{return !!musicAudio.src&&decodeURIComponent(new URL(musicAudio.src,location.href).pathname).endsWith('/'+wanted);}catch(e){return false;}
}
function setMusicTrack(i){
  i=Math.max(0,Math.min(TRACKS.length-1,Number(i)||0));
  MP.idx=i;musicTrimIndex=i;
  if(!isCurrentTrack(i)){
    musicAudio.src=trackUrl(i);
    musicAudio.load();
  }
  musicAudio.loop=MP.mode==='menu';
}
function playTrack(i,restart,attempt){
  if(externalMusicMode){try{musicAudio.pause();}catch(e){} return Promise.resolve(false);}
  configureAudioSession();
  attempt=Number(attempt)||0;
  setMusicTrack(i);
  MP.started=true;
  musicAudio.muted=false;
  if(restart){try{musicAudio.currentTime=0;}catch(e){}}
  applyVol();
  if(!musicAudio.paused){MP.src=musicAudio;MP.blocked=false;return Promise.resolve(true);}
  try{
    const p=musicAudio.play();
    if(p&&p.then)return p.then(()=>{MP.src=musicAudio;MP.blocked=false;MP.err=0;return true;}).catch((err)=>{
      MP.src=null;MP.blocked=true;
      console.warn('[audio] music play blocked/failed',trackUrl(i),err&&err.name||err);
      if(attempt<1&&err&&err.name==='NotSupportedError')return playTrack((i+1)%TRACKS.length,true,attempt+1);
      return false;
    });
    MP.src=musicAudio;MP.blocked=false;MP.err=0;return Promise.resolve(true);
  }catch(err){
    MP.src=null;MP.blocked=true;console.warn('[audio] music play exception',err&&err.name||err);
    return Promise.resolve(false);
  }
}
musicAudio.addEventListener('playing',()=>{MP.src=musicAudio;MP.blocked=false;applyVol();});
musicAudio.addEventListener('pause',()=>{if(!musicAudio.ended)MP.src=null;});
musicAudio.addEventListener('error',()=>{
  MP.err=MP.idx+1;MP.src=null;
});
musicAudio.addEventListener('ended',()=>{
  MP.src=null;
  if(MP.mode==='game'&&bootDone){
    let ni=Math.floor(Math.random()*TRACKS.length);
    if(TRACKS.length>1&&ni===MP.idx)ni=(ni+1)%TRACKS.length;
    playTrack(ni,true);
  }
});
function setTheme(){
  const changed=MP.mode!=='game';
  MP.mode='game';musicAudio.loop=false;
  if(MP.started&&bootDone){
    let ni=changed?(TRACKS.length>1?randomTrackIdx(MENU_TRACK_INDEX):0):MP.idx;
    playTrack(ni,changed);
  }
}
let bootDone=false;
function musicStart(){
  if(MP.started)return;
  MP.started=true;
  if(!MP.mode)MP.mode='menu';
  if(MP.mode==='menu')MP.idx=MENU_TRACK_INDEX;
  if(bootDone)playTrack(MP.mode==='menu'?MENU_TRACK_INDEX:MP.idx,false);
}
function musKick(){
  if(!MP.started||!bootDone)return;
  applyVol();
  if(musicAudio.paused)playTrack(MP.idx,false);
}
function fadeMusicDuck(to,durationMs){duckMusic(to,durationMs);}
function duck(v,when,ramp){duckMusic(v,Math.max(120,Number(ramp)||650));}
