function lx(v){if(v&&typeof v==='object'){const exact=v[LANG];if(exact!==undefined&&exact!==null)return exact;if((LANG==='fr'||LANG==='zh'||LANG==='it'||LANG==='ko'||LANG==='ru')&&v.en!==undefined)return v2Text(v.en,LANG);return v.en||v.tr||'';}return String(v||'');}
