function moleculeScienceSummaryHtml(id,compact=false){
  const m=MOLS[id],x=richMoleculeInfo(id);if(!m)return '';
  const L=moleculeScienceLabels();
  if(!x)return compact?('<b>'+m.n+'</b> ('+m.f+')<br>'+m.fa):('<div class="mxScienceFallback"><b>'+m.n+' · '+m.f+'</b><small>'+m.fa+'</small></div>');
  if(compact)return '<b>'+m.n+'</b> ('+m.f+')<br><span class="mxScienceBrief">'+x.about+'</span><br><span class="mxScienceFact">💡 '+x.fact+'</span>';
  return '<div class="mxScienceLearnCard"><div class="mxScienceLearnHead"><span>📘</span><b>'+m.n+' · '+m.f+'</b></div><div><strong>'+L.about+'</strong><small>'+x.about+'</small></div><div><strong>'+L.use+'</strong><small>'+x.use+'</small></div><div><strong>'+L.fact+'</strong><small>'+x.fact+'</small></div><button class="btn ghost mxScienceOpen" id="mScienceOpen">'+L.more+'</button></div>';
}
function expansionMoleculeFirstLevel(id){
  for(let i=301;i<LEVELS.length;i++)if(LEVELS[i]&&LEVELS[i].m===id)return i;
  return -1;
}
