  $('#labScientistTitle').textContent=career.title.toLocaleUpperCase(localeCode());
  $('#labScientistTitle').title=career.nobel?(career.title+' · 🏆 '+nobelPermanentTitle()):career.title;
  $('#labScientistName').textContent=(save.playerName||curProfile||playerFallbackLabel()).slice(0,18);
  const placed=$('#labPlacedItems');
  placed.innerHTML=ownedLabItems().map((it,i)=>'<div class="labPlaced item-'+it.id+' slot'+i+'">'+labItemVisualHtml(it.id,false)+'</div>').join('')+
    ((save.cur>=NOBEL_LEVEL_INDEX+1||(currentMonthlyLaureate()&&isNobelMe(currentMonthlyLaureate())))?'<div class="labPlaced item-nobel_case nobelCase">'+labItemVisualHtml('nobel_case',false)+'</div>':'');
  const levelsDone=Object.values(save.stars||{}).filter(v=>Number(v)>0).length;
