    +(owned?'<button class="btn '+(active?'green':'blue')+'" data-duelframe="'+f.id+'" '+(active?'disabled':'')+'>'+(active?(ml("KULLANILIYOR","ACTIVE","AKTIV","ACTIVO","ATIVO","使用中")):(ml("KULLAN","USE","VERWENDEN","USAR","USAR","使用")))+'</button>':'<button class="btn ghost" disabled>🔒</button>')
