function nobelChampionLabel(upper=false){const v=ml('Nobel Şampiyonu','Nobel Champion','Nobel-Champion','Campeón Nobel','Campeão Nobel','ノーベルチャンピオン');return upper?v.toLocaleUpperCase(localeCode()):v;}
