function cloudErrorCode(err){
  return String(err&&err.code||err&&err.reason||err&&err.message||'cloud/unknown').trim();
}
function isIndeterminateCloudTimeout(err){
  const code=cloudErrorCode(err);
  const msg=String(err&&err.message||'');
  return code==='cloud/timeout'||code==='cloud/save-timeout'||msg.includes('cloud/save-timeout');
}
function isRetryableCloudError(err){
  const code=cloudErrorCode(err).toLowerCase();
  return isIndeterminateCloudTimeout(err)||
    code==='cloud/account-context-changed'||
    code==='unavailable'||code==='firestore/unavailable'||
    code==='aborted'||code==='firestore/aborted'||
    code==='deadline-exceeded'||code==='firestore/deadline-exceeded'||
    code==='failed-precondition'||code==='firestore/failed-precondition'||
    code==='resource-exhausted'||code==='firestore/resource-exhausted'||
    code==='auth/network-request-failed'||
    code==='network-request-failed'||
    code==='cloud/profile-list-unavailable'||
    code==='cloud/load-timeout'||code==='cloud/list-timeout';
}
function preserveHealthyStatusAfterTimeout(){
  // A Promise.race timeout only means WKWebView stopped waiting; Firestore may
  // still finish the write. Keep the retryable checkpoint, but never replace a
  // previously confirmed cloud save with a false red error.
  if(navigator.onLine===false){setSyncStatus('offline');return;}
  setSyncStatus(readLastCloudSync()?'saved':'syncing');
}
function setSyncStatus(s){
  syncStatus=s;
  // R36 truth fix: status presentation is NOT proof of a progress write.
  // Only markCloudSaveConfirmed() may advance "Last successful sync".
  const el=document.getElementById('syncDot');
  if(el){
    el.className='syncDot sync-'+s;
    const c=typeof accountCopy==='function'?accountCopy():null;
    el.title=c?(s==='saved'?c.syncSaved:s==='syncing'?c.syncWorking:s==='offline'?c.syncOffline:s==='error'?c.syncError:ml('Bulut senkronizasyon durumu','Cloud sync status','Cloud-Synchronisierungsstatus','Estado de sincronización en la nube','Status da sincronização na nuvem','クラウド同期ステータス')):ml('Bulut senkronizasyon durumu','Cloud sync status','Cloud-Synchronisierungsstatus','Estado de sincronización en la nube','Status da sincronização na nuvem','クラウド同期ステータス');
  }
  const live=document.getElementById('cloudLiveState');
  if(live&&typeof updateCloudStatusHeader==='function')updateCloudStatusHeader();
}
let leaderboardRepairPromise=null;
let leaderboardRepairTimer=null;
let leaderboardRepairLastAt=0;
function hasPermanentCloudAccount(){
  const a=window.MXCloud&&window.MXCloud.account;
  return !!(a&&a.signedIn&&!a.isAnonymous);
}

// V8.1.6: real silent checkpoint after every completed campaign level.
// The newest pending snapshot is persisted locally, coalesced, and retried after reconnect/reload.
const LEVEL_CHECKPOINT_STORAGE='moleculox_qa_pending_level_checkpoint_r131';
let levelCloudCheckpointRunning=false;
let levelCloudCheckpointPending=null;
let levelCloudCheckpointRetryTimer=null;
function rememberLevelCloudCheckpoint(job){
  try{localStorage.setItem(LEVEL_CHECKPOINT_STORAGE,JSON.stringify(job));}catch(e){}
}
function forgetLevelCloudCheckpoint(){
  try{localStorage.removeItem(LEVEL_CHECKPOINT_STORAGE);}catch(e){}
}
function restoreLevelCloudCheckpoint(){
  if(levelCloudCheckpointPending)return;
  try{
    const raw=localStorage.getItem(LEVEL_CHECKPOINT_STORAGE);
    const job=raw&&JSON.parse(raw);
    if(job&&job.snapshot&&job.profileId)levelCloudCheckpointPending=job;
  }catch(e){forgetLevelCloudCheckpoint();}
}
function queueLevelCloudCheckpoint(reason){
  if(window.MX_QA_TEST_GAME)return;
  try{
    // R29: persist the newest completed-level snapshot even when Firebase Auth
    // is still restoring. WKWebView may suspend the page before a network write
    // finishes; the checkpoint is retried on the next foreground/launch.
    if(!window.MXCloud||!save||!save.profileId)return;
    levelCloudCheckpointPending={
      reason:String(reason||'level-complete'),
      profileId:save.profileId,
      accountUid:currentPermanentAccountUid(),
      cloudUid:currentCloudAuthUid(),
      queuedAt:Date.now(),
      snapshot:JSON.parse(JSON.stringify(save))
    };
    if(levelCloudCheckpointPending.accountUid)writeAccountProgressVault(levelCloudCheckpointPending.snapshot,save.profileId,levelCloudCheckpointPending.accountUid);
    rememberLevelCloudCheckpoint(levelCloudCheckpointPending);
    runLevelCloudCheckpoint();
  }catch(e){console.warn('[sync] checkpoint queue failed',e);}
}
async function runLevelCloudCheckpoint(){
  restoreLevelCloudCheckpoint();
  if(levelCloudCheckpointRunning||!levelCloudCheckpointPending)return;
  if(!window.MXCloud||!window.MXCloud.saveProgressNow){
    clearTimeout(levelCloudCheckpointRetryTimer);
    levelCloudCheckpointRetryTimer=setTimeout(runLevelCloudCheckpoint,1500);
    return;
  }
  if(navigator.onLine===false){
    setSyncStatus('offline');
    clearTimeout(levelCloudCheckpointRetryTimer);
    levelCloudCheckpointRetryTimer=setTimeout(runLevelCloudCheckpoint,5000);
    return;
  }
  const job=levelCloudCheckpointPending;
  const expectedCloudUid=String(job.cloudUid||job.accountUid||'');
  const activeCloudUid=currentCloudAuthUid();
  const activeUid=currentPermanentAccountUid();
  // Never replay a queued save into a different Firebase account. R36 also
  // protects anonymous->member and member->member transitions, not only the
  // permanent-account cases covered by R31.
  if(expectedCloudUid&&activeCloudUid&&expectedCloudUid!==activeCloudUid){
    clearTimeout(levelCloudCheckpointRetryTimer);
    levelCloudCheckpointRetryTimer=setTimeout(runLevelCloudCheckpoint,2500);
    return;
  }
  if(expectedCloudUid&&!activeCloudUid){
    clearTimeout(levelCloudCheckpointRetryTimer);
    levelCloudCheckpointRetryTimer=setTimeout(runLevelCloudCheckpoint,1800);
    return;
  }
  if(job.accountUid&&activeUid&&job.accountUid!==activeUid){
    clearTimeout(levelCloudCheckpointRetryTimer);
    levelCloudCheckpointRetryTimer=setTimeout(runLevelCloudCheckpoint,2500);
    return;
  }
  const jobContext=captureCloudOperationContext(job.profileId);
  levelCloudCheckpointPending=null;
  levelCloudCheckpointRunning=true;
  setSyncStatus('syncing');
  try{
    const merged=await window.MXCloud.saveProgressNow(job.snapshot,job.profileId);
    if(saveResultWasSkipped(merged)){
      if(merged.committed){
        if(!levelCloudCheckpointPending)forgetLevelCloudCheckpoint();
      }else{
        if(!levelCloudCheckpointPending)levelCloudCheckpointPending=job;
        rememberLevelCloudCheckpoint(levelCloudCheckpointPending);
      }
      if(cloudOperationContextIsCurrent(jobContext))preserveHealthyStatusAfterTimeout();
      return;
    }
    if(!merged||typeof merged!=='object')throw Object.assign(new Error('cloud/save-empty-result'),{code:'cloud/save-empty-result'});
    if(!levelCloudCheckpointPending)forgetLevelCloudCheckpoint();
    if(cloudOperationContextIsCurrent(jobContext)){
      markCloudSaveConfirmed(job.profileId,expectedCloudUid||jobContext.uid);
      setSyncStatus('saved');
    }
  }catch(e){
    console.warn('[sync] level checkpoint failed:',job.reason,e&&e.code||e);
    recordCloudDiagnostic('level-checkpoint',e,{reason:String(job.reason||'')});
    if(!levelCloudCheckpointPending)levelCloudCheckpointPending=job;
    rememberLevelCloudCheckpoint(levelCloudCheckpointPending);
    if(!cloudOperationContextIsCurrent(jobContext))return;
    if(isRetryableCloudError(e))preserveHealthyStatusAfterTimeout();
    else setSyncStatus(navigator.onLine===false?'offline':'error');
  }finally{
    levelCloudCheckpointRunning=false;
    if(levelCloudCheckpointPending){
      clearTimeout(levelCloudCheckpointRetryTimer);
      levelCloudCheckpointRetryTimer=setTimeout(runLevelCloudCheckpoint,navigator.onLine===false?5000:1400);
    }
  }
}
window.addEventListener('online',()=>runLevelCloudCheckpoint(),{passive:true});
