function applyMergedCloudProfile(data){
  if(!data||typeof data!=="object")return;
  save=hasPermanentCloudAccount()?cloudAuthoritativeProfile(save,data):mergeCloudData(save,data);save.autoGuest=false;
  if(save&&save.profileId)writeAccountProgressVault(save,save.profileId);
  if(curProfile)profiles[curProfile]=save;
  persistAll();updateCoins();updateBadge();
  document.body.classList.toggle('nodpad',!save.dpad);
  if(scr.splash.classList.contains('on'))refreshSplash();
}
async function repairCurrentLeaderboard(reason,force){
  if(!window.MXCloud||!save.profileId)return {ok:false,reason:'cloud-unavailable'};
  if(leaderboardRepairPromise)return leaderboardRepairPromise;
  const repairProfileId=save.profileId;
  const repairContext=captureCloudOperationContext(repairProfileId);
  const now=Date.now();
  if(!force&&now-leaderboardRepairLastAt<12000)return {ok:true,throttled:true};
  leaderboardRepairLastAt=now;
  leaderboardRepairPromise=(async()=>{
    await window.MXCloud.ready;
    if(!hasPermanentCloudAccount())return {ok:false,reason:'account-required'};
    setSyncStatus('syncing');

    // Core progress save and leaderboard publication are deliberately split.
    // A leaderboard error is optional; a progress-write error is not.
    if(window.MXCloud.saveProgressNow){
      try{
        const merged=await window.MXCloud.saveProgressNow(save,repairProfileId);
        if(saveResultWasSkipped(merged)||!cloudOperationContextIsCurrent(repairContext))return {ok:false,reason:'cloud/account-context-changed',stale:true};
        if(!merged||typeof merged!=='object')throw Object.assign(new Error('cloud/save-failed'),{code:'cloud/save-failed'});
        applyMergedCloudProfile(merged);
        markCloudSaveConfirmed(repairProfileId,repairContext.uid);
      }catch(e){
        console.warn('[sync] core save before leaderboard failed:',reason,e&&e.code||e);
        recordCloudDiagnostic('core-save-'+String(reason||'leaderboard-repair'),e);
        if(cloudOperationContextIsCurrent(repairContext)){
          if(navigator.onLine===false)setSyncStatus('offline');
          else if(isRetryableCloudError(e))preserveHealthyStatusAfterTimeout();
          else setSyncStatus('error');
        }
        return {ok:false,reason:cloudErrorCode(e),coreSaveFailed:true,retryable:isRetryableCloudError(e)};
      }
    }

    try{
      const fn=window.MXCloud.repairLeaderboard||window.MXCloud.syncLeaderboard;
      if(!fn){
        if(cloudOperationContextIsCurrent(repairContext))setSyncStatus('saved');
        return {ok:false,reason:'leaderboard-unavailable',progressSaved:true};
      }
      const result=window.MXCloud.repairLeaderboard?
        await fn(save,repairProfileId):await fn(save,repairProfileId,true);
      if(cloudOperationContextIsCurrent(repairContext))setSyncStatus(navigator.onLine===false?'offline':'saved');
      return result||{ok:false,reason:'unknown',progressSaved:true};
    }catch(e){
      console.warn('[sync] leaderboard publication failed:',reason,e&&e.code||e);
      // Ranking is optional. The core save above is already confirmed.
      if(cloudOperationContextIsCurrent(repairContext))setSyncStatus(navigator.onLine===false?'offline':'saved');
      return {ok:false,reason:e&&e.code||'error',progressSaved:true};
    }
  })();
  try{return await leaderboardRepairPromise;}finally{leaderboardRepairPromise=null;}
}
function scheduleLeaderboardRepair(reason,delay,force){
  clearTimeout(leaderboardRepairTimer);
  leaderboardRepairTimer=setTimeout(async()=>{
    const res=await repairCurrentLeaderboard(reason,!!force);
    if((!res||!res.ok)&&navigator.onLine!==false){
      // One bounded retry covers delayed Firebase auth/network restoration.
      leaderboardRepairTimer=setTimeout(()=>repairCurrentLeaderboard(reason+'-retry',true),6000);
    }
  },Math.max(0,Number(delay)||0));
}

async function syncFromCloud(){
  if(!window.MXCloud||!save.profileId)return;
  const syncProfileId=save.profileId;
  const syncContext=captureCloudOperationContext(syncProfileId);
  setSyncStatus('syncing');
  try{
    await window.MXCloud.ready;
    if(!window.MXCloud.uid){if(cloudOperationContextIsCurrent(syncContext))setSyncStatus('offline');return;}
    const cloud=await window.MXCloud.loadProfile(syncProfileId);
    if(!cloudOperationContextIsCurrent(syncContext))return;
    if(cloud)applyMergedCloudProfile(cloud);
    // A successful account restore must always push the merged local maximum
    // back to both the profile document and the public leaderboard.
    if(hasPermanentCloudAccount())await repairCurrentLeaderboard('startup-merge',true);
    else if(cloudOperationContextIsCurrent(syncContext))setSyncStatus(window.MXCloud.authFailed?'offline':'saved');
  }catch(e){
    console.warn('[sync] cloud restore failed:',e);
    if(!cloudOperationContextIsCurrent(syncContext))return;
    recordCloudDiagnostic('cloud-restore',e);
    setSyncStatus(navigator.onLine===false?'offline':(readLastCloudSync(syncProfileId,syncContext.uid)?'saved':'idle'));
  }
}

let onlineCountTimer=null;
async function refreshOnlinePlayerCount(){
  const wrap=$('#onlinePlayerCount'),text=$('#onlinePlayerCountText');
  if(!wrap||!text)return;
  if(navigator.onLine===false){wrap.classList.add('offline');text.textContent=ml("ÇEVRİMDIŞI","OFFLINE","OFFLINE","SIN CONEXIÓN","OFFLINE","オフライン");return;}
  try{
    if(!window.MXCloud||!window.MXCloud.getOnlinePlayerCount){wrap.classList.add('offline');text.textContent=ml('ÇEVRİMİÇİ: —','ONLINE: —','ONLINE: —','EN LÍNEA: —','ONLINE: —','オンライン：—');return;}
    await window.MXCloud.ready;
    if(window.MXCloud.startPresence)await window.MXCloud.startPresence();
    const count=await window.MXCloud.getOnlinePlayerCount();
    if(Number.isFinite(count)){wrap.classList.remove('offline');text.textContent=ml(count+' OYUNCU ONLINE',count+' PLAYERS ONLINE',count+' SPIELER ONLINE',count+' JUGADORES EN LÍNEA',count+' JOGADORES ONLINE',count+' 人オンライン');}
    else{wrap.classList.add('offline');text.textContent=ml('ÇEVRİMİÇİ: —','ONLINE: —','ONLINE: —','EN LÍNEA: —','ONLINE: —','オンライン：—');}
  }catch(e){wrap.classList.add('offline');text.textContent=ml('ÇEVRİMİÇİ: —','ONLINE: —','ONLINE: —','EN LÍNEA: —','ONLINE: —','オンライン：—');}
}
function startOnlineCountLoop(){
  clearInterval(onlineCountTimer);
  refreshOnlinePlayerCount();
  onlineCountTimer=setInterval(()=>{if(!document.hidden&&scr.splash.classList.contains('on'))refreshOnlinePlayerCount();},45000);
}
window.addEventListener('online',refreshOnlinePlayerCount);
window.addEventListener('online',()=>setTimeout(()=>maybeResumeOnlineDuelSession(),420),{passive:true});
window.addEventListener('offline',refreshOnlinePlayerCount);

let tutorialLaunchArmed=false;
function enterGame(){
  if(typeof wakeMainLoop==='function')wakeMainLoop();
  save=ensureResearchState(save);
  applyVol(); // re-sync gain/volume to this profile's real saved settings (bootPlay played music before this profile was loaded)
  document.body.classList.toggle('nodpad',!save.dpad);
  setLang(preferredProfileLanguage(save.lang));
  setBgForTier(tierOf(save.cur),false);
  persist();
  if(checkAchievementsSilent())persist();
  updateCoins();updateBadge();
  // V8.5.35: the basic tutorial must never auto-open during boot/profile restore.
  // It begins only after the player explicitly chooses NEW GAME and submits a name.
  if(!save.tutorialDone&&tutorialLaunchArmed&&String(save.playerName||'').trim()){
    tutorialLaunchArmed=false;
    startTutorial();
    return;
  }
  tutorialLaunchArmed=false;
  show('splash');
  startOnlineCountLoop();
  maybePlaySplashIntro();
  // R212: make the new wink visible shortly after the main menu settles.
  setTimeout(()=>{if(scr.splash&&scr.splash.classList.contains('on'))wink();},1250);
  scheduleMainMenuVoice('entry',760);
  setTimeout(()=>{if(!onlineDuelMode&&!quickMatchSearch)showGuestAccountToast();},900);
  setTimeout(()=>maybeResumeOnlineDuelSession(),520);
  // R16: entering a player never performs a global account reconciliation.
  // Only this exact profileId is saved/loaded; stale async work cannot jump to
  // another (usually highest-progress) player while New Game/tutorial is open.
  const enterEpoch=profileContextEpoch;
  if(!accountState.isAnonymous)setTimeout(()=>syncActiveProfileSafely(enterEpoch),160);
  else syncFromCloud();
}
function maybePlaySplashIntro(){
  // R145: one short, non-blocking Moleculox logo flourish per session.
  // The boot screen remains the only gated cinematic; this never adds another tap.
  if(splashIntroPlayed||!scr.splash)return;
  splashIntroPlayed=true;
  scr.splash.classList.remove('mxLogoArrival');
  void scr.splash.offsetWidth;
  scr.splash.classList.add('mxLogoArrival');
  setTimeout(()=>scr.splash&&scr.splash.classList.remove('mxLogoArrival'),1050);
}
function forceMainMenuVisible(){
  // V6.17: independent, animation-free screen switch for iPhone/itch.
  // This prevents a failed profile/audio/tutorial step from leaving only the background visible.
  try{
    screenTransitionLock=false;
    document.body.classList.remove('mxUiTransitioning');
    for(const key in scr){
      if(!scr[key])continue;
      scr[key].classList.remove('mxLeaving','mxEntering');
      scr[key].classList.toggle('on',key==='splash');
    }
    refreshSplash();
    startOnlineCountLoop();
    startSplashConversation(true,260);
    requestAnimationFrame(()=>{applyStableViewport(true);syncStandaloneEinsteinMode();});
  }catch(err){
    console.error('forceMainMenuVisible failed',err);
    const splash=document.getElementById('splash');
    const boot=document.getElementById('bootScr');
    if(boot)boot.classList.remove('on');
    if(splash){splash.classList.add('on');splash.style.display='block';splash.style.visibility='visible';splash.style.opacity='1';}
  }
}
function bootPlay(){
  if(bootPlayBusy)return;
  bootPlayBusy=true;
  const firstBoot=!bootDone;
  bootDone=true;
  const enterMainMenu=()=>{
    // The menu is revealed only after the deferred 302–801 data has joined the live LEVELS array.
    // In normal play this finishes during the studio/boot cinematic, so there is no visible wait.
    forceMainMenuVisible();
    stopStartupAudio();
    unlock();
    MP.mode='menu';MP.idx=MENU_TRACK_INDEX;musicAudio.loop=true;
    playTrack(MENU_TRACK_INDEX,true);
    const continueBoot=()=>{
    try{
      const names=Object.keys(profiles||{});
      let target=(lastProfile&&profiles[lastProfile])?lastProfile:(names.length===1?names[0]:null);
      if(target){
        curProfile=target;
        save=ensureResearchState(Object.assign(defaultSave(),profiles[target]));
        if(!save.profileId){save.profileId=genProfileId();profiles[target]=save;}
        enterGame();
      }else if(names.length>1){
        buildProfileSelect();
        show('profile');
      }else{
        createAutoGuestProfile();
        enterGame();
      }
    }catch(err){
      console.error('bootPlay failed, falling back to auto guest profile',err);
      try{createAutoGuestProfile();}catch(_e){}
      enterGame();
    }finally{
      bootPlayBusy=false;
      // A destination screen must always exist after PLAY.
      setTimeout(()=>{
        const visible=Object.values(scr).some(el=>el&&el.classList.contains('on'));
        if(!visible||scr.boot.classList.contains('on'))forceMainMenuVisible();
      },180);
    }
  };
    if(firstBoot)setTimeout(continueBoot,80);else continueBoot();
  };
  ensureFullCampaignReady().then(ok=>{
    if(!ok)console.error('[Moleculox R287] Full 801-level campaign was not ready at menu entry.');
    enterMainMenu();
  }).catch(err=>{
    console.error('[Moleculox R287] Campaign expansion load failed:',err);
    enterMainMenu(); // fail-open: never strand the player on the boot screen
  });
}

function updateCoins(bump){
  ensureCoinLedger(save);
  // Commit a crash-recovered full-solution refund before deleting its durable
  // escrow marker, so an immediate second app close can never lose the refund.
  const recoveredEscrowKey=hintEscrowStorageKeyForSave(save);
  if(window.__MX_HINT_ESCROW_RECOVERED_KEY===recoveredEscrowKey&&curProfile){
    profiles[curProfile]=save;lastProfile=curProfile;
    if(persistAll()){
      try{localStorage.removeItem(recoveredEscrowKey);}catch(_){}
      window.__MX_HINT_ESCROW_RECOVERED_KEY='';
    }
  }
  if(!save.maxCoins||save.coins>save.maxCoins)save.maxCoins=save.coins;
  const mainCoin=$('#coinChip span:last-child');if(mainCoin)mainCoin.textContent=save.coins;
  const labCoin=$('#labCoinChip span:last-child');if(labCoin)labCoin.textContent=save.coins;
  const splashCoin=$('#splashCoinChip span:last-child');if(splashCoin)splashCoin.textContent=save.coins;
  if(bump){const c=$('#coinChip');if(c){c.classList.remove('bump');void c.offsetWidth;c.classList.add('bump');}SFX.coin();}
}
function updateBadge(){
  const n=Object.keys(save.disc).length,b=$('#molBadge');
  b.textContent=n;b.style.display=n?'flex':'none';
  const achievementIds=new Set(ACHV.map(a=>a.id));
  const an=Object.keys(save.achv||{}).filter(id=>achievementIds.has(id)&&save.achv[id]).length,ab=$('#achvBadge');
  ab.textContent=an;ab.style.display=an?'flex':'none';
}

/* ================= MOLECULE MINI-DRAW ================= */
function drawMol(cv,mol,gray,animT){
  if(!cv||!mol||!Array.isArray(mol.s)||!mol.s.length)return;
  const dpr=effectiveDpr();
  const cw=Math.max(1,Math.round(cv.clientWidth||parseInt(cv.style.width)||88)),ch=Math.max(1,Math.round(cv.clientHeight||64));
  const rw=Math.max(1,Math.round(cw*dpr)),rh=Math.max(1,Math.round(ch*dpr));
  const c=cv.getContext('2d');
  // Resizing a canvas reallocates its backing store. The GOAL molecule is
  // animated often, so only resize when CSS size or performance DPR changed.
  if(cv.width!==rw||cv.height!==rh){cv.width=rw;cv.height=rh;}
  c.setTransform(dpr,0,0,dpr,0,0);c.clearRect(0,0,cw,ch);
  const xs=mol.s.map(a=>a[1]),ys=mol.s.map(a=>a[2]);
  const sw=Math.max(...xs)+1,sh=Math.max(...ys)+1;
  /* R198 GOAL rule: keep the R197 fixed card and typography, but make the
     molecule itself easier to read. Ordinary targets share one larger visual
     atom scale on a given device. Only targets whose geometry needs more room
     are reduced proportionally by goalFitT; the GOAL frame never changes size.
     Collection previews keep the historical auto-fit behaviour. */
  const isGoalPreview=cv.id==='goalCv';
  const standardGoalT=Math.min(26,cw*0.30,ch*0.40);
  const goalFitT=Math.min(cw/(sw+0.55),ch/(sh+0.55));
  const t=isGoalPreview?Math.min(standardGoalT,goalFitT):Math.min(cw/(sw+0.4),ch/(sh+0.4),30);
  const ox=(cw-sw*t)/2,oy=(ch-sh*t)/2;
  const glowPulse=animT?(0.75+0.25*Math.sin(animT/700)):1;
  const P=(a,i)=>{
    if(!animT)return [ox+(a[1]+0.5)*t,oy+(a[2]+0.5)*t];
    const wob=Math.sin(animT/850+(i!=null?i*1.8:0))*0.045;
    return [ox+(a[1]+0.5)*t,oy+(a[2]+0.5+wob)*t];
  };
  const strokeMiniBond=(a,b)=>{c.beginPath();c.moveTo(a[0],a[1]);c.lineTo(b[0],b[1]);c.stroke();};
  c.lineWidth=Math.max(3,t*0.18);c.lineCap='round';if(mol.researchPattern)c.setLineDash([Math.max(2,t*.12),Math.max(2,t*.10)]);
  c.strokeStyle=gray?'rgba(160,160,180,.6)':'rgba(190,230,255,.95)';
  c.shadowColor=gray?'transparent':'rgba(79,216,255,.9)';c.shadowBlur=gray?0:6*glowPulse;
  if(Array.isArray(mol.xb)&&mol.xb.length){
    for(const pair of mol.xb){const i=pair&&pair[0],j=pair&&pair[1];if(!Number.isInteger(i)||!Number.isInteger(j)||!mol.s[i]||!mol.s[j]||i===j)continue;if(mol.s.length!==2&&mol.s[i][0]==='H'&&mol.s[j][0]==='H')continue;const[a,b]=[P(mol.s[i],i),P(mol.s[j],j)];strokeMiniBond(a,b);}
  }else for(let i=0;i<mol.s.length;i++)for(let j=i+1;j<mol.s.length;j++){
    const dx=mol.s[j][1]-mol.s[i][1],dy=mol.s[j][2]-mol.s[i][2];
    if(Math.abs(dx)+Math.abs(dy)===1){if(mol.s.length!==2&&mol.s[i][0]==='H'&&mol.s[j][0]==='H')continue;const[a,b]=[P(mol.s[i],i),P(mol.s[j],j)];strokeMiniBond(a,b);}
  }
  c.shadowBlur=0;c.setLineDash([]);
  for(let i=0;i<mol.s.length;i++){
    const at=mol.s[i];
    const[x,y]=P(at,i),r=t*0.42,e=EL[at[0]];
    if(animT&&!gray){c.save();c.globalAlpha=0.3*glowPulse;c.shadowColor=e.c;c.shadowBlur=r*1.1;c.beginPath();c.arc(x,y,r*0.92,0,7);c.fillStyle=e.c;c.fill();c.restore();}
    const g=c.createRadialGradient(x-r*0.35,y-r*0.4,r*0.15,x,y,r);
    if(gray){g.addColorStop(0,'#9aa');g.addColorStop(1,'#556');}
    else{g.addColorStop(0,e.hi);g.addColorStop(1,e.c);}
    c.fillStyle=g;c.beginPath();c.arc(x,y,r,0,7);c.fill();
    c.fillStyle=gray?'#dde':e.t;c.font='900 '+Math.max(8,t*0.4)+'px -apple-system,system-ui,sans-serif';
    c.textAlign='center';c.textBaseline='middle';c.fillText(at[0],x,y+0.5);
  }
}

/* ================= LEVEL / COLLECTION SCREENS ================= */
function sparkleBurst(x,y,cols){
  cols=cols||['#ffd66e','#fff2c2','#ffc94d'];
  for(let i=0;i<7;i++)P({k:'glit',x:x+(Math.random()-0.5)*26,y:y+(Math.random()-0.5)*18,vx:(Math.random()-0.5)*1.4,vy:-0.8-Math.random()*1.3,c:rnd(cols),r:1.5+Math.random()*2.2,life:0.9});
}
function popStars(sp,stars){
  for(let i=0;i<3;i++){
    if(!sp[i])continue;
    if(i<stars){
      sp[i].classList.add('pop');
      setTimeout(()=>{
        SFX.star(i);
        const r=sp[i].getBoundingClientRect();
        sparkleBurst(r.left+r.width/2,r.top+r.height/2);
      },260+i*330);
    }else sp[i].classList.add('off');
  }
}
function starStr(n){let s='';for(let i=0;i<3;i++)s+=i<n?'<span>★</span>':'<span class="off">★</span>';return s;}
function campaignLevelStableKey(level,index){
  const exp=(level&&typeof level.exp==='string')?level.exp.trim():'';
  return exp||('campaign-'+(Number(index)+1)+'-'+String((level&&level.m)||'unknown'));
}
function campaignMechanicMiniTags(level){
  if(!level)return '';
  const rows=[];
  const hasFlag=n=>Array.isArray(level.a)&&level.a.some(a=>!!(a&&a[n]));
  const add=(icon,label)=>{if(rows.length<4)rows.push({icon,label});};
  // Show the distinguishing modifier first. Previous cards hid endgame
  // pressure doors, moving walls, modules and rotation, making different
  // certified boards look mechanically identical in the level grid.
  if(Array.isArray(level.mw)&&level.mw.length)add('🚧',ml('Hareketli Duvar','Moving Wall','Bewegliche Wand','Pared móvil','Parede móvel','移動壁','Mur mobile','移动墙','Muro mobile'));
  if(Array.isArray(level.pd)&&level.pd.length)add('🔘',ml('Basınç Kapısı','Pressure Door','Drucktür','Puerta de presión','Porta de pressão','圧力ドア','Porte à pression','压力门','Porta a pressione'));
  if(Array.isArray(level.fragile)&&level.fragile.length)add('💎',ml('Kırılgan','Fragile','Zerbrechlich','Frágil','Frágil','壊れやすい','Fragile','易碎','Fragile'));
  if(Array.isArray(level.rt)&&level.rt.length===2)add('🕳️',ml('Yarık','Rift','Riss','Fisura','Fenda','リフト','Faille','裂隙','Fenditura'));
  if(Array.isArray(level.pt)&&level.pt.length===2)add('🌀',ml('Portal','Portal','Portal','Portal','Portal','ポータル','Portail','传送门','Portale'));
  if(Array.isArray(level.bw)&&level.bw.length)add('🔨',ml('Çekiç','Hammer','Hammer','Martillo','Martelo','ハンマー','Marteau','锤子','Martello'));
  if(hasFlag(6))add('◎',ml('Kararsız','Unstable','Instabil','Inestable','Instável','不安定','Instable','不稳定','Instabile'));
  if(hasFlag(3))add('❄️',ml('Donmuş','Frozen','Gefroren','Congelado','Congelado','凍結','Gelé','冻结','Congelato'));
  if(hasFlag(4))add('🔥',ml('Ateş','Fire','Feuer','Fuego','Fogo','炎','Feu','火焰','Fuoco'));
  if(hasFlag(7))add('⚡',ml('Elektrik','Lightning','Blitz','Rayo','Raio','電気','Éclair','闪电','Fulmine'));
  if(hasFlag(5))add('🍯',ml('Yapışkan','Sticky','Klebrig','Pegajoso','Pegajoso','粘着','Collant','黏性','Appiccicoso'));
  if(Array.isArray(level.linked)&&level.linked.length)add('🔗',ml('Bağlı Atomlar','Linked Atoms','Verbundene Atome','Átomos enlazados','Átomos ligados','連結原子','Atomes liés','联动原子','Atomi collegati'));
  if(Array.isArray(level.pm)&&level.pm.length)add('🧩',ml('Hazır Modül','Prebuilt Module','Fertiges Modul','Módulo listo','Módulo pronto','既成モジュール','Module préassemblé','预制模块','Modulo pronto'));
  if(Array.isArray(level.fu)&&level.fu.length)add('🧬',ml('Füzyon','Fusion','Fusion','Fusión','Fusão','融合','Fusion','融合','Fusione'));
  if(Array.isArray(level.rp)&&level.rp.length)add('🔄',ml('Döndürme','Rotation','Rotation','Rotación','Rotação','回転','Rotation','旋转','Rotazione'));
  if(Array.isArray(level.ow)&&level.ow.length)add('↪️',ml('Tek Yön','One Way','Einbahn','Una dirección','Mão única','一方通行','Sens unique','单向','Senso unico'));
  if(!rows.length)return '';
  return '<div class="campaignMechanicStrip">'+rows.map(x=>'<span title="'+x.label+'">'+x.icon+'</span>').join('')+'</div>';
}
function campaignUnlockedThrough(){
  const progress=Math.max(0,Math.min(LEVELS.length-1,Math.floor(Number(save&&save.cur)||0)));
  // SAFE QA selection is deliberately independent from campaign progress.
  // New Game may reset to Level 1 without relocking the other 500 test cards.
  return window.MX_QA_ALL_LEVELS_OPEN?Math.max(0,LEVELS.length-1):progress;
}
function resolveCampaignLevelIndex(index,expectedKey=''){
  const raw=Math.max(0,Math.min(LEVELS.length-1,Number(index)||0));
  // Prefer the exact identity captured by the level card. This keeps a tap
  // attached to the same experiment even if an older cached level array was
  // briefly mixed with a newer game.js during an update.
  if(expectedKey){
    const exact=LEVELS.findIndex((L,idx)=>campaignLevelStableKey(L,idx)===expectedKey);
    if(exact>=0)return exact;
  }
  const levelNumber=raw+1;
  // Grand Master cards also carry explicit gm-NNN ids. Resolve by number as
  // a second safety net for Continue/Next flows that only pass an index.
  if(levelNumber>=286&&levelNumber<=300){
    const key='gm-'+levelNumber+'-';
    const exact=LEVELS.findIndex(L=>String((L&&L.exp)||'').startsWith(key));
    if(exact>=0)return exact;
  }
  return raw;
}
function buildLevels(){
  updateBonusStatus();applyBonusCosmetics();
  const g=$('#lvGrid');g.innerHTML='';
  const unlockedThrough=campaignUnlockedThrough();
  LEVELS.forEach((L,i)=>{
    const b=document.createElement('button');
    const locked=i>unlockedThrough;
    b.className='lvBtn'+(locked?' lock':'')+(i===save.cur&&!locked?' cur':'')+(!locked&&L.b?' feature-'+L.b:'');
    const featureTag=(!locked&&L.b)?('<div class="campaignFeatureTag '+L.b+'" title="'+campaignFeatureName(L.b)+'">'+campaignFeatureIcon(L.b)+'</div>'):'';
    const mechanicTags=!locked?campaignMechanicMiniTags(L):'';
    const molecule=MOLS[L.m];
    const formula=(!locked&&molecule)?'<div class="lvFormula'+chemicalFormulaClass(molecule.f)+'">'+molecule.f+'</div>':'';
    b.setAttribute('aria-label',locked?ml('Kilitli bölüm '+(i+1),'Locked level '+(i+1),'Gesperrtes Level '+(i+1),'Nivel bloqueado '+(i+1),'Fase bloqueada '+(i+1),'ロック中 レベル'+(i+1)):ml('Bölüm '+(i+1)+' · '+(molecule?molecule.f:''),'Level '+(i+1)+' · '+(molecule?molecule.f:''),'Level '+(i+1)+' · '+(molecule?molecule.f:''),'Nivel '+(i+1)+' · '+(molecule?molecule.f:''),'Fase '+(i+1)+' · '+(molecule?molecule.f:''),'レベル'+(i+1)+' · '+(molecule?molecule.f:'')));
    b.innerHTML='<div class="lvNum'+(locked?' lockedNum':'')+'">'+(i+1)+'</div>'+formula+
      (locked?'<div class="lockIcon"><i></i></div>':'<div class="st">'+starStr(save.stars[i]||0)+'</div>'+mechanicTags+(SPEEDRUN_LEVELS.includes(i)?'<div class="speedTag">⚡</div>':'')+featureTag);
    if(!locked){
      const stableKey=campaignLevelStableKey(L,i);
      b.dataset.levelNumber=String(i+1);
      b.dataset.levelKey=stableKey;
      let px=0,py=0;
      b.addEventListener('pointerdown',e=>{px=e.clientX;py=e.clientY;},{passive:true});
      b.addEventListener('pointerup',e=>{
        const dist=Math.max(Math.abs(e.clientX-px),Math.abs(e.clientY-py));
        if(dist<10){SFX.click();goToLevelWithStory(i,stableKey);}
      },{passive:true});
    }
    g.appendChild(b);
  });
  requestAnimationFrame(updateLvScrollThumb);
}
function updateLvScrollThumb(){
  const sa=$('#lvScrollArea'),thumb=$('#lvScrollThumb');
  if(!sa||!thumb)return;
  const ratio=sa.clientHeight/sa.scrollHeight;
  if(ratio>=1){thumb.style.opacity='0';return;}
  thumb.style.opacity='1';
  thumb.style.height=(ratio*100)+'%';
  thumb.style.top=((sa.scrollTop/sa.scrollHeight)*100)+'%';
}
function buildHof(){
  const inp=$('#hofNameInput');
  inp.value=save.playerName||'';
  inp.placeholder=t('hofNamePh');
  const tier=tierOf(save.cur),career=careerRankDisplay(save.cur);
  const monthlyRank=currentMonthlyCandidateRank();
  $('#hofRankLine').textContent=monthlyRank===1?(ml("🏆 Ayın Nobel Ödüllüsü","🏆 Monthly Nobel Laureate","🏆 Nobelpreisträger des Monats","🏆 Nobel del Mes","🏆 Nobel do Mês","🏆 今月のノーベル賞受賞者","🏆 Lauréat Nobel du mois","🏆 本月诺贝尔得主","🏆 Premio Nobel del mese")):(career.icon+' '+career.title+(career.nobel&&career.level>301?' · 🏆 Nobel':''));

  ensureResearchState(save);
  const score=save.researchPoints||0;
  const maxCoins=save.maxCoins||0;
  const times=Object.values(save.speedRuns);
  const bestTime=times.length?Math.min(...times):null;

  $('#hofChampGrid').innerHTML=[
    [score,t('hofStatScore'),'🏅'],
    [maxCoins,t('hofStatMaxCoins'),'🪙'],
    [bestTime?bestTime.toFixed(1)+'s':'—',t('hofStatBestTime'),'⚡'],
  ].map(([v,l,ic])=>
    '<div class="hofChamp"><div class="ic">'+ic+'</div><div class="v">'+v+'</div><div class="l">'+l+'</div></div>'
  ).join('');

  const stars3=Object.values(save.stars).filter(v=>v===3).length;
  const levelsDone=Math.max(Object.values(save.stars||{}).filter(v=>Number(v)>0).length,Math.max(0,Math.min(LEVELS.length,Math.floor(Number(save.cur)||0))));
  const molCount=Object.keys(save.disc).length;
  const achvCount=ACHV.filter(a=>save.achv&&save.achv[a.id]).length;

  const stats=[
    [stars3,t('hofStat3Stars')],
    [levelsDone,t('hofStatLevels')],
    [molCount,t('hofStatMols')],
    [achvCount+'/'+ACHV.length,t('hofStatAchv')],
  ];
  $('#hofStatsGrid').innerHTML=stats.map(([v,l])=>
    '<div class="hofStat"><div class="v">'+v+'</div><div class="l">'+l+'</div></div>'
  ).join('');

  const sg=$('#hofSpeedGrid');
  sg.innerHTML='';
  const setTimes=SPEEDRUN_LEVELS.map(idx=>save.speedRuns[idx]).filter(v=>typeof v==='number');
  const fastest=setTimes.length?Math.min(...setTimes):null;
  SPEEDRUN_LEVELS.forEach((idx,ri)=>{
    const lv=LEVELS[idx];
    if(!lv)return;
    const best=save.speedRuns[idx];
    const locked=idx>campaignUnlockedThrough();
    const isBest=best!=null&&best===fastest;
    const row=document.createElement('div');
    row.className='hofSpeedRow'+(locked?' locked':'')+(isBest?' best':'');
    row.style.animationDelay=(ri*70)+'ms';
    const molName=locked?'???':(MOLS[lv.m]?MOLS[lv.m].n:lv.m);
    row.innerHTML='<span class="mol">'+(idx+1)+'. '+molName+'</span><span class="time">'+(isBest?'👑 ':'')+(best?best.toFixed(1)+'s':(locked?'🔒':t('hofNotYet')))+'</span>';
    sg.appendChild(row);
  });
  buildHofTabs();
}
function esc(s){return String(s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));}
function cleanPublicPlayerName(raw,maxLength=18){
  return String(raw||'').replace(/[\u0000-\u001f\u007f<>]/g,'').replace(/\s+/g,' ').trim().slice(0,maxLength);
}
function publicPlayerNameKey(raw){
  return cleanPublicPlayerName(raw,18).normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('en-US')
    .replace(/[@4]/g,'a').replace(/3/g,'e').replace(/[1!|]/g,'i').replace(/0/g,'o').replace(/[5$]/g,'s').replace(/[^a-z0-9]/g,'');
}
function publicPlayerNameAllowed(raw){
  const name=cleanPublicPlayerName(raw,18),key=publicPlayerNameKey(name);
  if(!name)return false;
  if(!key)return true;
  const exact=new Set(['fuck','shit','cunt','nazi','hitler','amk','pic','porn']);
  const severe=['motherfucker','faggot','nigger','nigga','orospu','siktir','yarrak'];
  return !exact.has(key)&&!severe.some(part=>key.includes(part));
}
function validatedPublicPlayerName(raw,maxLength=18){const name=cleanPublicPlayerName(raw,maxLength);return {ok:!!name&&publicPlayerNameAllowed(name),name};}
function publicPlayerNameError(){return ml('Bu oyuncu adı kullanılamaz. Uygun ve saygılı başka bir ad seç.','This player name cannot be used. Choose another respectful name.','Dieser Spielername kann nicht verwendet werden. Wähle einen anderen respektvollen Namen.','Este nombre de jugador no se puede usar. Elige otro nombre respetuoso.','Este nome de jogador não pode ser usado. Escolha outro nome respeitoso.','このプレイヤー名は使用できません。別の適切な名前を選んでください。');}
const MX_BLOCKED_RANKING_KEY='mx_blocked_ranking_users_v1';
function loadBlockedRankingUsers(){try{const rows=JSON.parse(localStorage.getItem(MX_BLOCKED_RANKING_KEY)||'[]');return new Set(Array.isArray(rows)?rows.filter(v=>typeof v==='string').slice(0,500):[]);}catch(e){return new Set();}}
const blockedRankingUsers=loadBlockedRankingUsers();
function rankingUserKey(r){return String(r&&r.id||((r&&r.uid||'')+'_'+(r&&r.profileId||''))).replace(/[^A-Za-z0-9_-]/g,'').slice(0,180);}
function isRankingRowBlocked(r,myUid,myProfileId){if(r&&r.uid===myUid&&r.profileId===myProfileId)return false;const key=rankingUserKey(r);return !!key&&blockedRankingUsers.has(key);}
function blockRankingUser(r){const key=rankingUserKey(r);if(!key)return false;blockedRankingUsers.add(key);try{localStorage.setItem(MX_BLOCKED_RANKING_KEY,JSON.stringify(Array.from(blockedRankingUsers).slice(-500)));}catch(e){}return true;}
function rankingSafetyButton(r,isMe,source){if(isMe||!rankingUserKey(r))return '';const label=ml('Raporla veya engelle','Report or block','Melden oder blockieren','Reportar o bloquear','Denunciar ou bloquear','報告またはブロック');return '<button type="button" class="rankingSafetyBtn" data-board-id="'+escAttr(rankingUserKey(r))+'" data-target-uid="'+escAttr(r&&r.uid||'')+'" data-target-profile="'+escAttr(r&&r.profileId||'')+'" data-target-name="'+escAttr(r&&r.playerName||'')+'" data-source="'+escAttr(source||'ranking')+'" title="'+escAttr(label)+'" aria-label="'+escAttr(label)+'">⋯</button>';}
function refreshRankingAfterSafety(source){if(source==='duel')refreshDuelRankings(duelRankMode);else refreshHofWorldTabs(hofSubMode);}
function openRankingSafetyModal(button){
  const row={id:button.dataset.boardId||'',uid:button.dataset.targetUid||'',profileId:button.dataset.targetProfile||'',playerName:button.dataset.targetName||''},source=button.dataset.source||'ranking';let rankingChanged=false;
  const title=ml('OYUNCU GÜVENLİĞİ','PLAYER SAFETY','SPIELERSCHUTZ','SEGURIDAD DEL JUGADOR','SEGURANÇA DO JOGADOR','プレイヤー保護');
  const report=ml('RAPORLA VE ENGELLE','REPORT & BLOCK','MELDEN & BLOCKIEREN','REPORTAR Y BLOQUEAR','DENUNCIAR E BLOQUEAR','報告してブロック');
  const block=ml('SADECE ENGELLE','BLOCK ONLY','NUR BLOCKIEREN','SOLO BLOQUEAR','SOMENTE BLOQUEAR','ブロックのみ');
  openModal('<h3>🛡️ '+title+'</h3><div class="msub">'+esc(row.playerName||'?')+'</div><div id="rankingSafetyMsg" class="authMessage"></div><div class="mrow"><button class="btn amber" id="mRankReport">'+report+'</button><button class="btn ghost" id="mRankBlock">'+block+'</button><button class="btn" id="mRankCancel">'+t('cancel')+'</button></div>');
  const modalBox=$('#modalBox');if(modalBox)modalBox.classList.add('rankingSafetyModal');
  bindTap('#mRankBlock',()=>{rankingChanged=blockRankingUser(row);SFX.click();closeModal();refreshRankingAfterSafety(source);});
  bindTap('#mRankCancel',()=>{SFX.back();closeModal();if(rankingChanged)refreshRankingAfterSafety(source);});
  bindTap('#mRankReport',async()=>{
    const btn=$('#mRankReport'),msg=$('#rankingSafetyMsg');if(btn)btn.disabled=true;
    if(!window.MXCloud||!window.MXCloud.reportPlayerName||window.MXCloud.account.isAnonymous){if(msg)msg.textContent=ml('Rapor göndermek için hesabını bağla. Oyuncu bu cihazda engellendi.','Link an account to send a report. The player was blocked on this device.','Verknüpfe ein Konto, um eine Meldung zu senden. Der Spieler wurde auf diesem Gerät blockiert.','Vincula una cuenta para enviar el reporte. El jugador fue bloqueado en este dispositivo.','Vincule uma conta para enviar a denúncia. O jogador foi bloqueado neste dispositivo.','報告を送信するにはアカウントを連携してください。この端末ではブロックしました。');rankingChanged=blockRankingUser(row);if(btn)btn.disabled=false;return;}
    const result=await window.MXCloud.reportPlayerName(row.id,'inappropriate_name',{targetUid:row.uid,targetProfileId:row.profileId,targetName:row.playerName,source});
    rankingChanged=blockRankingUser(row);
    if(result&&result.ok){if(msg)msg.textContent=ml('Rapor gönderildi ve oyuncu engellendi.','Report sent and player blocked.','Meldung gesendet und Spieler blockiert.','Reporte enviado y jugador bloqueado.','Denúncia enviada e jogador bloqueado.','報告を送信し、プレイヤーをブロックしました。');setTimeout(()=>{closeModal();refreshRankingAfterSafety(source);},700);}
    else{if(msg)msg.innerHTML=ml('Oyuncu engellendi; rapor gönderilemedi. Destek: <a href="mailto:moleculoxsupport@gmail.com">moleculoxsupport@gmail.com</a>','Player blocked; the report could not be sent. Support: <a href="mailto:moleculoxsupport@gmail.com">moleculoxsupport@gmail.com</a>','Spieler blockiert; Meldung konnte nicht gesendet werden. Support: <a href="mailto:moleculoxsupport@gmail.com">moleculoxsupport@gmail.com</a>','Jugador bloqueado; no se pudo enviar el reporte. Soporte: <a href="mailto:moleculoxsupport@gmail.com">moleculoxsupport@gmail.com</a>','Jogador bloqueado; não foi possível enviar a denúncia. Suporte: <a href="mailto:moleculoxsupport@gmail.com">moleculoxsupport@gmail.com</a>','プレイヤーをブロックしましたが、報告を送信できませんでした。サポート: <a href="mailto:moleculoxsupport@gmail.com">moleculoxsupport@gmail.com</a>');if(btn)btn.disabled=false;}
  });
}
function bindRankingSafetyControls(root=document){root.querySelectorAll('.rankingSafetyBtn').forEach(btn=>bindTap(btn,()=>{SFX.click();openRankingSafetyModal(btn);}));}
function careerScoreOf(r){
  const rp=clampDisplay(r&&r.researchPoints),completed=clampDisplay(r&&r.completedLevels),stars=clampDisplay(r&&r.totalStars);
  return rp+(completed*20)+(stars*5);
}
function rankScoreText(r){
  if(r.periodRP!=null)return clampDisplay(r.periodRP).toLocaleString()+' RP';
  return careerScoreOf(r).toLocaleString()+' CP';
}
function validatedRankTime(ms){
  ms=clampDisplay(ms);
  const missingLimit=6*3600000;
  if(!ms||ms>=missingLimit)return '—';
  const sec=Math.floor(ms/1000),min=Math.floor(sec/60),rest=sec%60;
  return min?min+'m '+String(rest).padStart(2,'0')+'s':rest+'s';
}
function rankDetailText(r){
  const completed=clampDisplay(r.completedLevels),perfect=clampDisplay(r.perfectLevels),stars=clampDisplay(r.totalStars);
  return '🧩 '+completed+'/'+LEVELS.length+' · ⭐ '+stars+' · 💎 '+perfect+' · ⏱ '+validatedRankTime(r.totalValidatedSolveTime);
}
function rowHtml(r,i,myUid,myProfileId){
  const rank=i+1;
  const isMe=r.uid===myUid&&r.profileId===myProfileId;
  const cls='hofWorldRow'+(isMe?' me':'')+(rank===1?' top1':rank===2?' top2':rank===3?' top3':'');
  const medal=rank===1?'🥇':rank===2?'🥈':rank===3?'🥉':rank;
  const nm=esc((r.playerName||'?').slice(0,18));
  const dl=Math.min(i,14)*40;
  return '<div class="'+cls+'" style="animation-delay:'+dl+'ms"><span class="rk">'+medal+'</span><div class="hofRankIdentity"><span class="nm">'+(isMe?t('worldYou')+' · ':'')+nm+'</span><small>'+rankDetailText(r)+'</small></div><span class="sc">'+rankScoreText(r)+'</span>'+rankingSafetyButton(r,isMe,'career')+'</div>';
}
const ONLINE_RANKINGS_ENABLED=true;
let hofTopMode='records',hofSubMode='world',duelRankMode='world';
function buildHofTabs(){
  setHofTopMode(hofTopMode,true);
  if(hofTopMode==='rankings')setHofSubMode(hofSubMode);
  if(hofTopMode==='duel')setDuelRankMode(duelRankMode);
}
function initHofTabs(){
  const records=$('#hofTopRecords'),rankings=$('#hofTopRankings'),duel=$('#hofTopDuel');
  if(records)records.addEventListener('pointerdown',e=>{e.preventDefault();SFX.click();setHofTopMode('records');},{passive:false});
  if(rankings)rankings.addEventListener('pointerdown',e=>{e.preventDefault();SFX.click();setHofTopMode('rankings');},{passive:false});
  if(duel)duel.addEventListener('pointerdown',e=>{e.preventDefault();SFX.click();setHofTopMode('duel');},{passive:false});
  document.querySelectorAll('.duelRankTab').forEach(b=>b.addEventListener('pointerdown',e=>{e.preventDefault();SFX.click();setDuelRankMode(b.dataset.dueltab);},{passive:false}));
  document.querySelectorAll('.hofSubTab').forEach(b=>{
    b.addEventListener('pointerdown',e=>{e.preventDefault();SFX.click();setHofSubMode(b.dataset.tab);},{passive:false});
  });
}
function setHofTopMode(mode,silent){
  if(mode==='rankings'&&!ONLINE_RANKINGS_ENABLED)mode='records';
  if(mode==='duel'&&!$('#hofDuelPane'))mode='records';
  hofTopMode=mode;
  const records=$('#hofTopRecords'),rankings=$('#hofTopRankings'),duel=$('#hofTopDuel');
  const recordsPane=$('#hofRecordsPane'),rankingsPane=$('#hofRankingsPane'),duelPane=$('#hofDuelPane');
  if(records)records.classList.toggle('on',mode==='records');
  if(rankings)rankings.classList.toggle('on',mode==='rankings');
  if(duel){duel.classList.toggle('on',mode==='duel');duel.textContent=ml("⚔️ DÜELLO RANK","⚔️ DUEL RANK","⚔️ DUELL-RANG","⚔️ RANGO DE DUELO","⚔️ RANK DE DUELO","⚔️ デュエルランク");}
  if(recordsPane)recordsPane.style.display=mode==='records'?'':'none';
  if(rankingsPane)rankingsPane.style.display=mode==='rankings'?'':'none';
  if(duelPane)duelPane.style.display=mode==='duel'?'':'none';
  if(mode==='rankings'&&!silent)setHofSubMode(hofSubMode);
  if(mode==='duel')setDuelRankMode(duelRankMode);
}
function setHofSubMode(tab){
  if(!['world','week','month','champs'].includes(tab))tab='world';
  hofSubMode=tab;
  document.querySelectorAll('.hofSubTab').forEach(b=>b.classList.toggle('on',b.dataset.tab===tab));
  const grid=$('#hofWorldGrid'),soon=$('#hofComingSoon'),label=$('#hofPeriodLabel');
  if(tab==='champs'){
    if(grid)grid.style.display='none';if(soon)soon.style.display='flex';
    if(label)label.textContent=t('tabChamps');
    refreshChampionsTab();
    return;
  }
  if(grid)grid.style.display='';if(soon)soon.style.display='none';
  refreshHofWorldTabs(tab);
}
function rankingResetCountdownHtml(tab){
  if(tab!=='week'&&tab!=='month')return '';
  const now=new Date();
  let end;
  if(tab==='month')end=new Date(Date.UTC(now.getUTCFullYear(),now.getUTCMonth()+1,1,0,0,0));
  else{
    const day=now.getUTCDay()||7;
    end=new Date(Date.UTC(now.getUTCFullYear(),now.getUTCMonth(),now.getUTCDate()+(8-day),0,0,0));
  }
  const ms=Math.max(0,end-now),days=Math.floor(ms/86400000),hours=Math.floor(ms%86400000/3600000),mins=Math.floor(ms%3600000/60000);
  const label=tab==='month'
    ?ml('Aylık sıralama sıfırlanıyor','Monthly ranking resets in','Monatsrangliste wird zurückgesetzt in','La clasificación mensual se reinicia en','O ranking mensal reinicia em','月間ランキング更新まで')
    :ml('Haftalık sıralama sıfırlanıyor','Weekly ranking resets in','Wochenrangliste wird zurückgesetzt in','La clasificación semanal se reinicia en','O ranking semanal reinicia em','週間ランキング更新まで');
  const value=ml(days+' gün '+hours+' saat '+mins+' dk',days+'d '+hours+'h '+mins+'m',days+'T '+hours+'Std '+mins+'Min',days+'d '+hours+'h '+mins+'m',days+'d '+hours+'h '+mins+'m',days+'日 '+hours+'時間 '+mins+'分');
  return '<div class="hofResetCountdown">⏳ <b>'+label+':</b> '+value+' <small>(UTC)</small></div>';
}

function rankingGuestAccountNotice(){
  const iosNative=!!(window.Capacitor&&window.Capacitor.getPlatform&&window.Capacitor.getPlatform()==='ios');
  return iosNative
    ?ml('Sıralamaları görebilirsin. Puanını yayımlamak için profil ikonundan Apple hesabını bağla.','You can view rankings. Connect your Apple account from the profile icon to publish your score.','Du kannst die Ranglisten ansehen. Verbinde über das Profilsymbol dein Apple-Konto, um deine Punktzahl zu veröffentlichen.','Puedes ver las clasificaciones. Vincula tu cuenta de Apple desde el icono de perfil para publicar tu puntuación.','Você pode ver os rankings. Vincule sua conta Apple pelo ícone de perfil para publicar sua pontuação.','ランキングは閲覧できます。スコアを公開するにはプロフィールアイコンからAppleアカウントを連携してください。')
    :ml('Sıralamaları görebilirsin. Puanını yayımlamak için profil ikonundan Google veya e-posta hesabını bağla.','You can view rankings. Connect a Google or email account from the profile icon to publish your score.','Du kannst die Ranglisten ansehen. Verbinde über das Profilsymbol ein Google- oder E-Mail-Konto, um deine Punktzahl zu veröffentlichen.','Puedes ver las clasificaciones. Vincula una cuenta de Google o correo desde el icono de perfil para publicar tu puntuación.','Você pode ver os rankings. Vincule uma conta Google ou e-mail pelo ícone do perfil para publicar sua pontuação.','ランキングは閲覧できます。スコアを公開するにはプロフィールアイコンからGoogleまたはメールアカウントを接続してください。');
}
async function refreshHofWorldTabs(tab){
  tab=tab||hofSubMode||'world';
  const grid=$('#hofWorldGrid');const label=$('#hofPeriodLabel');if(!grid)return;
  label.textContent=tab==='week'?t('tabWeek'):tab==='month'?t('tabMonth'):t('hofWorldTitle');
  const guest=!!(window.MXCloud&&window.MXCloud.account&&window.MXCloud.account.isAnonymous);
  const periodFair=tab==='week'||tab==='month';
  const memberInfo=periodFair?
    (ml("Adil dönem puanı yalnızca herkesin aynı gün oynadığı Günün Deneyi’nden gelir. Herkes 20 Temmuz 2026’da 0’dan başlar.","Fair period score comes only from Today’s Experiment, which is the same daily challenge for everyone. Everyone starts from 0 on July 20, 2026.","Die faire Periodenwertung stammt nur aus dem Experiment des Tages, derselben täglichen Herausforderung für alle. Alle starten am 20. Juli 2026 bei 0.","La puntuación justa del periodo solo proviene del Experimento del Día, el mismo reto diario para todos. Todos empiezan desde 0 el 20 de julio de 2026.","A pontuação justa do período vem apenas do Experimento do Dia, o mesmo desafio diário para todos. Todos começam do 0 em 20 de julho de 2026.","公平な期間スコアは全員共通の「今日の実験」だけで獲得します。全員2026年7月20日に0から開始します。")):
    (ml("Kariyer Puanı = RP + (tamamlanan bölüm × 20) + (toplam yıldız × 5). Eski RP, bölüm ve yıldızların korunur.","Career Score = RP + (completed levels × 20) + (total stars × 5). Your previous RP, levels and stars are preserved.","Karrierepunkte = RP + (abgeschlossene Level × 20) + (Sterne gesamt × 5). Deine bisherigen RP, Level und Sterne bleiben erhalten.","Puntuación de Carrera = RP + (niveles completados × 20) + (estrellas totales × 5). Se conservan tus RP, niveles y estrellas.","Pontuação de Carreira = RP + (fases concluídas × 20) + (total de estrelas × 5). Seus RP, fases e estrelas são preservados.","キャリアスコア = RP +（クリアレベル×20）+（合計スター×5）。これまでのRP、レベル、スターは保持されます。"));
  const localCompleted=Math.max(Object.values(save.stars||{}).filter(v=>Number(v)>0).length,Math.max(0,Math.min(LEVELS.length,Math.floor(Number(save.cur)||0))));
  const localPerfect=Object.values(save.stars||{}).filter(v=>Number(v)===3).length;
  const localStars=Object.values(save.stars||{}).reduce((sum,v)=>sum+Math.max(0,Math.min(3,Number(v)||0)),0);
  const localCareer=clampDisplay(save.researchPoints)+(localCompleted*20)+(localStars*5);
  const localSummary='<div class="hofLocalSummary">'+(ml("Bu profil","This profile","Dieses Profil","Este perfil","Este perfil","このプロフィール"))+': <b>'+localCareer.toLocaleString()+' CP</b> · '+clampDisplay(save.researchPoints).toLocaleString()+' RP · 🧩 '+localCompleted+'/'+LEVELS.length+' · ⭐ '+localStars+' · 💎 '+localPerfect+'</div>';
  const refreshAction=guest?'':'<button type="button" id="hofForceRefresh" class="hofRefreshBtn">🔄 '+(ml("SIRALAMAYI YENİLE","REFRESH RANKING","RANGLISTE AKTUALISIEREN","ACTUALIZAR CLASIFICACIÓN","ATUALIZAR RANKING","ランキング更新"))+'</button>';
  const notice='<div class="hofWorldNotice '+(guest?'guest':'member')+'"><div>'+(
    guest?rankingGuestAccountNotice():
      memberInfo)+'</div>'+rankingResetCountdownHtml(tab)+localSummary+refreshAction+'</div>';
  const bindRankingRefresh=()=>{const btn=$('#hofForceRefresh');if(!btn)return;bindTap(btn,async()=>{btn.disabled=true;btn.textContent=ml("⏳ YENİLENİYOR","⏳ REFRESHING","⏳ AKTUALISIERUNG","⏳ ACTUALIZANDO","⏳ ATUALIZANDO","⏳ 更新中");try{await repairCurrentLeaderboard('manual-hall-refresh',true);if(window.MXCloud.clearLeaderboardCache)window.MXCloud.clearLeaderboardCache();}finally{await refreshHofWorldTabs(tab);}});};
  grid.innerHTML=notice+'<div id="hofWorldMsg">'+t('worldLoading')+'</div>';bindRankingRefresh();
  if(!window.MXCloud){grid.innerHTML=notice+'<div id="hofWorldMsg">'+t('worldOffline')+'</div>';bindRankingRefresh();return;}
  const myUid=window.MXCloud.uid,myProfileId=save.profileId;
  try{
    if(!guest&&save.profileId){try{if(window.MXCloud.cleanupOrphanRankingRows)await window.MXCloud.cleanupOrphanRankingRows();if(window.MXCloud.cleanupPlaceholderRankingRows)await window.MXCloud.cleanupPlaceholderRankingRows();await repairCurrentLeaderboard('hall-of-fame',true);}catch(syncErr){console.warn('[Moleculox] leaderboard repair skipped:',syncErr&&syncErr.code);}}
    let result=null,rows=null;
    if(tab==='week'){result=await window.MXCloud.getWeeklyLeaderboard(100,true);rows=result&&result.rows;}
    else if(tab==='month'){result=await window.MXCloud.getMonthlyLeaderboard(100,true);rows=result&&result.rows;}
    else rows=await window.MXCloud.getLeaderboard(100,true);
    if(!scr.hof.classList.contains('on'))return;
    if(!rows){grid.innerHTML=notice+'<div id="hofWorldMsg">'+t('worldOffline')+'</div>';bindRankingRefresh();return;}
    if(!rows.length){grid.innerHTML=notice+'<div id="hofWorldMsg">'+t('worldEmpty')+'</div>';bindRankingRefresh();return;}
    const rankingRows=rows.map((r,i)=>isRankingRowBlocked(r,myUid,myProfileId)?'':rowHtml(r,i,myUid,myProfileId)).join('');
    grid.innerHTML=notice+(rankingRows||'<div id="hofWorldMsg">'+ml('Engellediğin oyuncular gizlendi.','Blocked players are hidden.','Blockierte Spieler sind ausgeblendet.','Los jugadores bloqueados están ocultos.','Jogadores bloqueados estão ocultos.','ブロックしたプレイヤーは非表示です。')+'</div>');bindRankingRefresh();bindRankingSafetyControls(grid);
  }catch(e){if(scr.hof.classList.contains('on')){grid.innerHTML=notice+'<div id="hofWorldMsg">'+t('worldOffline')+'</div>';bindRankingRefresh();}}
}

