let activeScienceLegendEgg=null;
function scienceLegendCfg(card){return card&&SCIENCE_LEGEND_EASTER[card.id]||null;}
function scienceLegendResearchKey(prefix,id){return prefix+String(id||'');}
function ensureScienceLegendState(){
  ensureCollectionSaveState();ensureResearchState(save);
  const schema=Math.max(0,Math.floor(Number(save.scienceLegendSchema)||0));
  if(schema<SCIENCE_LEGEND_SCHEMA){
    if(schema<2){
      // R336/R337 were passive-unlock test builds. Reset only test card state; game progress is untouched.
      save.scienceLegends={};save.scienceLegendRevealed={};
    }else if(schema<3){
      // R339 migration only: discard any old staged Dalton test state once.
      if(save.scienceLegends)delete save.scienceLegends.dalton;
      if(save.scienceLegendRevealed)delete save.scienceLegendRevealed.dalton;
    }
    // R342 schema 5 preserves all legitimate Series I/II discoveries and enables Series III.
    save.scienceLegendSchema=SCIENCE_LEGEND_SCHEMA;
  }
  for(const card of SCIENCE_LEGENDS){
    if(Number(save.researchAchievements[scienceLegendResearchKey(SCIENCE_LEGEND_DISC_PREFIX,card.id)])>0)save.scienceLegends[card.id]=true;
  }
}
function scienceLegendDiscovered(card){ensureScienceLegendState();return !!(card&&save.scienceLegends[card.id]);}
function legendExactHintTokens(){ensureResearchState(save);return Math.max(0,Math.floor(Number(save.researchAchievements[SCIENCE_LEGEND_HINT_KEY])||0));}
function addLegendExactHintTokens(n=1){ensureResearchState(save);n=Math.max(0,Math.floor(Number(n)||0));save.researchAchievements[SCIENCE_LEGEND_HINT_KEY]=legendExactHintTokens()+n;return legendExactHintTokens();}
function consumeLegendExactHint(){const n=legendExactHintTokens();if(n<1)return false;save.researchAchievements[SCIENCE_LEGEND_HINT_KEY]=n-1;persist();return true;}
function legendPrecisionTokens(){ensureResearchState(save);return Math.max(0,Math.floor(Number(save.researchAchievements[SCIENCE_LEGEND_PRECISION_KEY])||0));}
function addLegendPrecisionTokens(n=1){ensureResearchState(save);n=Math.max(0,Math.floor(Number(n)||0));save.researchAchievements[SCIENCE_LEGEND_PRECISION_KEY]=legendPrecisionTokens()+n;return legendPrecisionTokens();}
function consumeLegendPrecision(){const n=legendPrecisionTokens();if(n<1)return false;save.researchAchievements[SCIENCE_LEGEND_PRECISION_KEY]=n-1;persist();return true;}
function scienceLegendRewardText(card){
  const cfg=scienceLegendCfg(card),r=cfg&&cfg.reward||{},parts=[];
  if(r.hammer)parts.push(slMl('Çekiç ×','Hammer ×','Hammer ×','Martillo ×','Martelo ×','ハンマー ×','Marteau ×','锤子 ×','Martello ×','망치 ×','Молоток ×')+r.hammer);
  if(r.hint)parts.push(slMl('Kesin Hamle ×','Exact Move ×','Exakter Zug ×','Movimiento exacto ×','Movimento exato ×','正確な一手 ×','Coup exact ×','精确步骤 ×','Mossa esatta ×','정확한 수 ×','Точный ход ×')+r.hint);
  if(r.precision)parts.push(slMl('Tek Kare ×','One-Square ×','Ein-Feld ×','Una casilla ×','Uma casa ×','1マス ×','Une case ×','单格 ×','Una casella ×','한 칸 ×','Один шаг ×')+r.precision);
  return parts.join(' · ');
}
function scienceLegendRewardIcon(kind){
  const map={hammer:'hammer',hint:'bolt',precision:'target',gift:'gift'},name=map[kind]||'gift';
  return '<svg class="scienceLegendRewardSvg scienceLegendRewardSvg--'+kind+'" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><use href="#mlx-'+name+'"></use></svg>';
}
function scienceLegendRewardHtml(card,withGift){
  const cfg=scienceLegendCfg(card),r=cfg&&cfg.reward||{},parts=[];
  if(r.hammer)parts.push('<span class="scienceLegendRewardItem">'+scienceLegendRewardIcon('hammer')+'<span>×'+r.hammer+'</span></span>');
  if(r.hint)parts.push('<span class="scienceLegendRewardItem">'+scienceLegendRewardIcon('hint')+'<span>'+slMl('Kesin Hamle ×','Exact Move ×','Exakter Zug ×','Movimiento exacto ×','Movimento exato ×','正確な一手 ×','Coup exact ×','精确步骤 ×','Mossa esatta ×','정확한 수 ×','Точный ход ×')+r.hint+'</span></span>');
  if(r.precision)parts.push('<span class="scienceLegendRewardItem">'+scienceLegendRewardIcon('precision')+'<span>'+slMl('Tek Kare ×','One-Square ×','Ein-Feld ×','Una casilla ×','Uma casa ×','1マス ×','Une case ×','单格 ×','Una casella ×','한 칸 ×','Один шаг ×')+r.precision+'</span></span>');
  const row='<span class="scienceLegendRewardItems">'+parts.join('<span class="scienceLegendRewardDivider" aria-hidden="true">·</span>')+'</span>';
  return (withGift?'<span class="scienceLegendRewardLead">'+scienceLegendRewardIcon('gift')+'</span>':'')+row;
}
function grantScienceLegendReward(card){
  ensureScienceLegendState();const cfg=scienceLegendCfg(card);if(!cfg)return false;
  const key=scienceLegendResearchKey(SCIENCE_LEGEND_REWARD_PREFIX,card.id);
  if(Number(save.researchAchievements[key])>0)return false;
  const r=cfg.reward||{};
  if(r.hammer)addBooster('hammer',r.hammer);
  if(r.hint)addLegendExactHintTokens(r.hint);
  if(r.precision)addLegendPrecisionTokens(r.precision);
  save.researchAchievements[key]=1;return true;
}
function scienceLegendCampaignCard(levelIndex){
  const level1=Math.floor(Number(levelIndex)||0)+1;
  return SCIENCE_LEGENDS.find(card=>{const c=scienceLegendCfg(card);return c&&c.campaignLevel===level1&&!scienceLegendDiscovered(card);})||null;
}
function scienceLegendDailyCard(){
  ensureScienceLegendState();const day=String(currentDailyId||utcDayId()||'daily');
  if(Number(save.researchAchievements[SCIENCE_LEGEND_DAILY_CLAIM_PREFIX+day])>0)return null;
  const locked=SCIENCE_LEGENDS.filter(card=>!scienceLegendDiscovered(card));if(!locked.length)return null;
  let h=2166136261;for(let i=0;i<day.length;i++){h^=day.charCodeAt(i);h=Math.imul(h,16777619);}
  const start=(h>>>0)%SCIENCE_LEGENDS.length;
  for(let k=0;k<SCIENCE_LEGENDS.length;k++){const card=SCIENCE_LEGENDS[(start+k)%SCIENCE_LEGENDS.length];if(!scienceLegendDiscovered(card))return card;}
  return null;
}
function scienceLegendCurrentCard(){
  if(duelMode||crystalMode||chainMode||reactorMode||tutorialActive)return null;
  if(dailyMode)return scienceLegendDailyCard();
  return scienceLegendCampaignCard(lv);
}
function removeScienceLegendEgg(){const old=document.getElementById('scienceLegendEgg');if(old)old.remove();activeScienceLegendEgg=null;}
function setupScienceLegendEggForCurrentLevel(){
  // R371: Science Legends are level-completion rewards, not hidden-click
  // rewards. The old faint sigil made discovery easy to miss on mobile.
  removeScienceLegendEgg();
}
function finalizeScienceLegendEggDiscovery(resultStars){
  const card=scienceLegendCurrentCard();if(!card)return null;
  const mode=dailyMode?'daily':'campaign';removeScienceLegendEgg();ensureScienceLegendState();
  if(scienceLegendDiscovered(card))return null;
  if(mode==='daily'&&Math.max(0,Math.floor(Number(resultStars)||0))<3){
    prop('⭐ '+slMl('BİLİM EFSANESİ · KART İÇİN 3 YILDIZ GEREKİYOR','SCIENCE LEGEND · 3 STARS REQUIRED FOR THE CARD','WISSENSCHAFTSLEGENDE · 3 STERNE FÜR DIE KARTE NÖTIG','LEYENDA CIENTÍFICA · SE NECESITAN 3 ESTRELLAS','LENDA CIENTÍFICA · 3 ESTRELAS NECESSÁRIAS','科学レジェンド · カードには3つ星が必要','LÉGENDE SCIENTIFIQUE · 3 ÉTOILES REQUISES','科学传奇 · 卡片需要3星','LEGGENDA SCIENTIFICA · SERVONO 3 STELLE','과학 전설 · 카드에는 별 3개 필요','ЛЕГЕНДА НАУКИ · ДЛЯ КАРТЫ НУЖНЫ 3 ЗВЕЗДЫ'),3000);
    return null;
  }
  save.scienceLegends[card.id]=true;
  save.researchAchievements[scienceLegendResearchKey(SCIENCE_LEGEND_DISC_PREFIX,card.id)]=1;
  if(mode==='daily'){
    const day=String(currentDailyId||utcDayId()||'daily');
    save.researchAchievements[SCIENCE_LEGEND_DAILY_CLAIM_PREFIX+day]=1;
  }
  const rewarded=grantScienceLegendReward(card);persistLocalOnly();
  prop('🏛️ '+scienceLegendUi('discovered')+' · '+card.name+(rewarded?' · '+scienceLegendRewardText(card):''),3000);
  return card;
}

function scienceLegendStats(){
  ensureCollectionSaveState();
  const discIds=Object.keys(save.disc||{}).filter(id=>save.disc[id]&&MOLS[id]);
  let totalStars=0,threeStars=0,highestCompleted=0,lightning=0;
  for(const k in save.stars){const idx=Math.max(0,Math.floor(Number(k)||0)),st=Math.max(0,Math.min(3,Math.floor(Number(save.stars[k])||0)));totalStars+=st;if(st===3)threeStars++;if(st>0)highestCompleted=Math.max(highestCompleted,idx+1);}
  const levels=Math.max(0,Math.min(LEVELS.length,Math.max(Math.floor(Number(save.cur)||0),highestCompleted)));
  const elements=new Set();discIds.forEach(id=>{const m=MOLS[id];if(m&&Array.isArray(m.s))m.s.forEach(a=>a&&a[0]&&elements.add(a[0]));});
  for(let i=0;i<Math.min(levels,LEVELS.length);i++){const L=LEVELS[i];if(L&&Array.isArray(L.a)&&L.a.some(a=>!!(a&&a[7])))lightning++;}
  return {molecules:discIds.length,levels,totalStars,threeStars,elements:elements.size,lightning};
}
function scienceLegendProgress(card,stats){
  ensureScienceLegendState();const done=scienceLegendDiscovered(card);return {current:done?1:0,raw:done?1:0,target:1,done,pct:done?100:0};
}
