const splashEin=$('#einBoxS');
if(splashEin){
  let splashEinTapAt=0;
  const reactSplashEinstein=e=>{
    // The main-menu Einstein stays mounted while other screens are visible.
    // Never let its hidden tap handler react during gameplay.
    const splash=$('#splash');
    if(!splash||!splash.classList.contains('on'))return;
    const now=Date.now();
    if(now-splashEinTapAt<350)return;
    splashEinTapAt=now;
    if(e&&e.cancelable)e.preventDefault();
    SFX.click();
    // R212: tap/click gives a visible one-eye wink, then a short natural blink.
    wink();setTimeout(blink,360);
  };
  // Pointer events cover modern mobile browsers; click is a reliable fallback
  // for itch.io/iOS embedded pages where pointerdown may be swallowed.
  splashEin.addEventListener('pointerdown',reactSplashEinstein,{passive:false});
  splashEin.addEventListener('click',reactSplashEinstein,{passive:false});
  splashEin.setAttribute('role','button');
  splashEin.setAttribute('aria-label',ml('Dr. Edward Atom göz kırpma tepkisi','Dr. Edward Atom wink reaction','Dr. Edward Atom Zwinkern','Guiño de Dr. Edward Atom','Piscadela de Dr. Edward Atom','Dr. Edward Atomのウィンク'));
}
// R346: Edward is visually above MY MOLECULES, but his transparent rectangle
// must never steal that button's tap. CSS makes the mascot pointer-transparent;
// this delegated background hit keeps the optional wink on unobstructed Edward.
const splashSurface=$('#splash');
if(splashSurface&&splashEin){
  splashSurface.addEventListener('pointerdown',e=>{
    if(!splashSurface.classList.contains('on'))return;
    if(e.target&&e.target.closest&&e.target.closest('button,a,input,select,textarea,[role=button]'))return;
    const r=splashEin.getBoundingClientRect();
    if(e.clientX>=r.left&&e.clientX<=r.right&&e.clientY>=r.top&&e.clientY<=r.bottom){wink();setTimeout(blink,360);}
  },{passive:true});
}
