function sayDuration(txt,requested){
  const plain=String(txt||'').replace(/<[^>]*>/g,' ').replace(/\s+/g,' ').trim();
  const words=plain?plain.split(' ').length:0;
  // R48: readable on phones and across longer translations; never flashes away.
  const calculated=5100+words*430+Math.max(0,plain.length-70)*24;
  const natural=Math.min(14000,Math.max(7000,calculated));
  return Math.min(14000,Math.max(Number(requested)||0,natural));
}
function say(txt,mood,dur,fx){
  const bubbleText=$('#bubbleText');
  if(bubbleText)bubbleText.innerHTML=txt;else bub.innerHTML=txt;
  const readMs=sayDuration(txt,dur);
  bub.classList.remove('on','shk','glow','long');
  if(fx)bub.classList.add(fx);
  if(String(txt||'').replace(/<[^>]*>/g,'').length>96)bub.classList.add('long');
  bub.style.setProperty('--bubble-duration',readMs+'ms');
  bub.setAttribute('aria-label',String(txt||'').replace(/<[^>]*>/g,' ')+(ml(" — kapatmak için dokun"," — tap to dismiss"," — zum Schließen tippen"," — toca para cerrar"," — toque para fechar"," — タップして閉じる")));
  void bub.offsetWidth;bub.classList.add('on');
  einMood(mood||'talk',Math.min(readMs,2200));
  const speechMoxy=document.getElementById('moxyGameCompanion');
  if(speechMoxy&&!speechMoxy.hidden){
    if(!moxyDrEInteractionBusy){
      speechMoxy.classList.remove('mx-visit-dre','mx-visit-return');
      speechMoxy.style.removeProperty('--mx-visit-x');speechMoxy.style.removeProperty('--mx-visit-y');
    }
    moxyPose('dre',false);
  }
  clearTimeout(sayT);
  // R181: restore the classic thin read-timer behavior. The line finishes, then
  // the bubble closes; the player can dismiss it immediately by tapping it.
  sayT=setTimeout(closeSayBubble,readMs);
}
if(bub){
  const dismiss=e=>{if(!bub.classList.contains('on'))return;if(e&&e.cancelable)e.preventDefault();closeSayBubble();};
  bub.addEventListener('pointerdown',dismiss,{passive:false});
  bub.addEventListener('click',dismiss,{passive:false});
}


function showVictoryLabFx(mode){
  const wrap=$('#victoryLabFx'),particles=$('#victoryLabParticles');if(!wrap||!particles)return;
  clearTimeout(showVictoryLabFx.t);
  wrap.classList.remove('on','mini');particles.innerHTML='';
  const mini=mode==='mini';if(mini)wrap.classList.add('mini');
  const quality=mxFxQuality();
  const count=effectsAllowed()?(mini?(quality==='low'?7:quality==='mid'?11:14):(quality==='low'?12:quality==='mid'?19:26)):0;
  const colors=['#4fd8ff','#9d7bff','#ffd76a','#ffffff','#58e6a9','#ff6f91'];
  for(let i=0;i<count;i++){
    const p=document.createElement('i');p.className='vlfParticle';
    const ang=(-160+Math.random()*140)*Math.PI/180,dist=(mini?84:150)+Math.random()*(mini?108:250);
    p.style.setProperty('--x',(Math.cos(ang)*dist)+'px');p.style.setProperty('--y',(Math.sin(ang)*dist+96+Math.random()*120)+'px');
    p.style.setProperty('--w',(3+Math.random()*5)+'px');p.style.setProperty('--h',(6+Math.random()*8)+'px');
    p.style.setProperty('--r',(Math.random()*180)+'deg');p.style.setProperty('--c',colors[i%colors.length]);
    p.style.setProperty('--d',(mini?0.82+Math.random()*.18:0.98+Math.random()*.24)+'s');p.style.setProperty('--delay',(Math.random()*.14)+'s');
    particles.appendChild(p);
  }
  void wrap.offsetWidth;wrap.classList.add('on');
  showVictoryLabFx.t=setTimeout(()=>{wrap.classList.remove('on','mini');particles.innerHTML='';},mini?1080:1360);
}

