function showDailyLoginReward(streak,reward){
  if(!scr.splash.classList.contains('on')||reward<=0)return;
  let card=document.getElementById('mxDailyLoginReward');if(card)card.remove();
  card=document.createElement('div');card.id='mxDailyLoginReward';card.setAttribute('role','status');
  card.innerHTML='<b>'+ml('GÜNLÜK GİRİŞ','DAILY LOGIN','TÄGLICHE ANMELDUNG','INICIO DIARIO','LOGIN DIÁRIO','デイリーログイン','CONNEXION QUOTIDIENNE','每日登录','ACCESSO GIORNALIERO')+'</b><span>'+streak+'/7</span><strong>+'+reward+' <i class="coinIcon" aria-hidden="true"></i></strong>';
  scr.splash.appendChild(card);requestAnimationFrame(()=>card.classList.add('on'));
  stopSplashConversation();
  if(splashBubble&&splashBubbleText){splashBubbleText.textContent=dailyLoginRewardText(streak,reward);splashBubble.classList.add('on');einMood('happy',2600);}
  setTimeout(()=>flyMoleCoinsToCounter(reward,card,'#splashCoinChip'),520);
  setTimeout(()=>card.classList.add('leaving'),3600);
  setTimeout(()=>{card.remove();if(splashBubble)splashBubble.classList.remove('on');startSplashConversation(false,650);},4300);
}
async function maybeClaimDailyLoginReward(){
  if(dailyLoginClaimBusy||!scr.splash.classList.contains('on')||!save||!save.profileId)return;
  const acc=typeof accountState!=='undefined'?accountState:null;
  // Guests never call the reward endpoint and never receive a local fallback.
  if(!acc||!acc.signedIn||acc.isAnonymous||!window.MXCloud||!window.MXCloud.claimDailyLogin)return;
  const signature=String(acc.uid||'')+'|'+String(save.profileId||'')+'|'+utcDayId();
  if(dailyLoginClaimSignature===signature)return;
  dailyLoginClaimBusy=true;
  try{
    const res=await window.MXCloud.claimDailyLogin(save.profileId);
    if(!res||!res.ok||res.accountRequired||res.offline)return;
    dailyLoginClaimSignature=signature;
    const reward=Math.max(0,Math.floor(Number(res.reward)||0)),streak=Math.max(1,Math.min(7,Math.floor(Number(res.streak)||1)));
    save.dailyLoginDate=String(res.day||utcDayId());save.dailyLoginStreak=streak;
    if(reward>0){
      ensureCoinLedger(save);
      if(Number.isFinite(Number(res.earned))){
        save.researchAchievements[COIN_EARN_KEY]=Math.max(Math.floor(Number(save.researchAchievements[COIN_EARN_KEY])||0),Math.floor(Number(res.earned)||0));
        save.researchAchievements[COIN_SPEND_KEY]=Math.max(Math.floor(Number(save.researchAchievements[COIN_SPEND_KEY])||0),Math.floor(Number(res.spent)||0));
        ensureCoinLedger(save);
      }else addCoins(reward);
      if(Number.isFinite(Number(res.balance)))save.coins=Math.max(save.coins,Math.floor(Number(res.balance)||0));
      persistLocalOnly();updateCoins(false);showDailyLoginReward(streak,reward);
    }else persistLocalOnly();
  }catch(e){console.warn('[daily-login] claim failed',e&&e.message||e);}
  finally{dailyLoginClaimBusy=false;}
}
function stopSplashConversation(){
  clearTimeout(splashTalkTimer);clearTimeout(splashTalkGapTimer);
  if(splashBubble)splashBubble.classList.remove('on');
}
function startSplashConversation(reset=false,delay=180){
  if(!splashBubble||!splashBubbleText)return;
  clearTimeout(splashTalkTimer);clearTimeout(splashTalkGapTimer);
  if(!scr.splash.classList.contains('on')){splashBubble.classList.remove('on');return;}
  // R172: tell each player once that the main campaign contains 801 experiments.
  // This is an in-game Dr. Edward Atom bubble only; it is not an OS notification or permission prompt.
  if(reset&&save&&save.profileId&&!save.seen801CampaignIntro){
    save.seen801CampaignIntro=true;persist();
    splashTalkGapTimer=setTimeout(()=>{
      if(!scr.splash.classList.contains('on'))return;
      splashBubbleText.textContent=ml(
        'Laboratuvar artık 801 deneyden oluşuyor. Hepsini tamamlayabilir misin?',
        'The laboratory now holds 801 experiments. Can you complete them all?',
        'Das Labor umfasst jetzt 801 Experimente. Kannst du sie alle abschließen?',
        'El laboratorio ahora tiene 801 experimentos. ¿Puedes completarlos todos?',
        'O laboratório agora tem 801 experimentos. Você consegue completar todos?',
        'ラボには全部で801の実験がある。すべて完了できるかな？',
        'Le laboratoire compte désormais 801 expériences. Peux-tu toutes les terminer ?',
        '实验室现在共有801项实验。你能全部完成吗？',
        'Il laboratorio ora contiene 801 esperimenti. Riesci a completarli tutti?'
      );
      splashBubble.classList.add('on');einMood('happy',2100);
      splashTalkTimer=setTimeout(()=>{
        splashBubble.classList.remove('on');splashTalkIndex=0;
        splashTalkGapTimer=setTimeout(()=>startSplashConversation(false,0),900);
      },5000);
    },Math.max(120,Number(delay)||180));
    return;
  }
  const rows=splashTalkMessages();if(!rows.length)return;
  const sig=LANG+'|'+splashPlayerName()+'|'+save.dailyDate+'|'+(save.cur||0)+'|'+(accountState.isAnonymous?'g':'m')+'|'+(nextBonusMission()?nextBonusMission().milestone:0)+'|'+((currentMonthlyLaureate()&&currentMonthlyLaureate().playerName)||'');
  if(reset||sig!==splashTalkSignature){splashTalkIndex=0;splashTalkSignature=sig;}
  splashTalkGapTimer=setTimeout(()=>{
    if(!scr.splash.classList.contains('on'))return;
    splashBubbleText.textContent=rows[splashTalkIndex%rows.length];
    splashBubble.classList.add('on');
    einMood(splashTalkIndex%3===0?'happy':'talk',2100);
    splashTalkTimer=setTimeout(()=>{
      splashBubble.classList.remove('on');
      splashTalkIndex=(splashTalkIndex+1)%rows.length;
      splashTalkGapTimer=setTimeout(()=>startSplashConversation(false,0),1150);
    },5600);
  },Math.max(0,Number(delay)||0));
}
let idleT=null,idleN=0,sleeping=false,zzT=null,autoHintT=null;
function wake(){
  idleN=0;
  if(!sleeping)return;
  sleeping=false;clearInterval(zzT);
  EIN.lids.forEach(l=>l.classList.remove('on'));
  look(0,-0.4,600,0.6);prop('❗',700);
}
function goSleep(){
  sleeping=true;
  EIN.lids.forEach(l=>l.classList.add('on'));
  prop('💤',3000);
  zzT=setInterval(()=>{if(sleeping)prop('💤',2600);},4200);
  say(t('sleeping'),'sad',3600);
}
function schedIdle(){
  clearTimeout(idleT);
  idleT=setTimeout(()=>{
    if(scr.game.classList.contains('on')&&!won&&!$('#modal').classList.contains('on')){
      idleN++;
      if(idleN>=2){if(!sleeping)goSleep();}
      else{
        say(rnd(LN.idle),'talk',3500,Math.random()<0.5?'shk':null);
      }
      schedIdle();
    }
  },22000+Math.random()*9000);
}
function resetIdle(){wake();schedIdle();}

/* ================= GAME STATE ================= */
const board=$('#board'),bctx=board.getContext('2d');
// HOTFIX 4: cache the immutable grid layer. The old renderer rebuilt every
