  bctx.font='900 '+Math.max(8,Math.round(T*.18))+'px system-ui';bctx.fillStyle=on?'#d9ffea':'#5a3b00';bctx.fillText(pressureSystemLabel(sys),T*.23,-T*.22);bctx.restore();
