function applyReplicatorLanding(i,finishedAnim){
  if(!replicatorLabActive()||!finishedAnim||!finishedAnim.replicatorCrossed||!atoms[i])return false;
  const targetCount=replicatorTargetCount();
  if(atoms.length>=targetCount)return false;
  if(!replicatorSpawnFree()){
    setDrEPose('clipboard',3200,3,true);mxHaptic('error');
    say(ml('×2 çıkışı dolu. Önce işaretli çıkış hücresini boşalt.','The ×2 output is occupied. Clear the marked output cell first.','Der ×2-Ausgang ist belegt. Räume zuerst das markierte Ausgangsfeld frei.','La salida ×2 está ocupada. Libera primero la casilla marcada.','A saída ×2 está ocupada. Libere primeiro a casa marcada.','×2の出口が塞がれています。先に出口マスを空けてください。','La sortie ×2 est occupée. Libère d’abord la case de sortie marquée.','×2出口被占用。请先清空标记的出口格。','L’uscita ×2 è occupata. Libera prima la casella di uscita segnata.'),'talk',3000,'shk');
    return false;
  }
  const src=atoms[i],clone={x:replicatorChamber.spawnX,y:replicatorChamber.spawnY,e:src.e,ph:Math.random()*6.28,frozen:false,fire:false,sticky:false,zombie:false,lightning:false,zombieGen:0};
  atoms.push(clone);replicatorCreatedThisLevel++;replicatorFxUntil=performance.now()+900;
  mxTrack('replicator_created',mxTelemetryLevelParams({element:String(src.e||''),atom_count:atoms.length,target_atom_count:targetCount,moves:Number(moves)||0,attempt_seconds:mxTelemetryAttemptSeconds()}));
  if(SFX.sparkle)SFX.sparkle();else if(SFX.select)SFX.select();mxHaptic('medium');
  prop('×2  '+String(src.e||'')+' → '+String(src.e||'')+' + '+String(src.e||''),1500);
  if(lv===501&&replicatorCreatedThisLevel===1){
    setDrEPose('happy',4800,4,true);
    say(ml('Harika! ×2 odası '+src.e+' atomunu kopyaladı. Orijinal yoluna devam etti; yeni '+src.e+' işaretli çıkışta oluştu. Şimdi H₂O’yu tamamla.','Perfect! The ×2 chamber copied the '+src.e+' atom. The original kept moving and a new '+src.e+' appeared at the marked output. Now finish H₂O.','Perfekt! Die ×2-Kammer hat '+src.e+' kopiert. Das Original glitt weiter; die Kopie erschien am markierten Ausgang. Jetzt H₂O vollenden.','¡Perfecto! La cámara ×2 copió '+src.e+'. El original siguió moviéndose y la copia apareció en la salida marcada. Ahora completa H₂O.','Perfeito! A câmara ×2 copiou '+src.e+'. O original continuou e a cópia apareceu na saída marcada. Agora complete H₂O.','成功！×2チャンバーが'+src.e+'を複製しました。元の原子は進み続け、コピーが出口に現れました。H₂Oを完成させましょう。','Parfait ! La chambre ×2 a copié '+src.e+'. L’original a continué et la copie est apparue à la sortie. Termine maintenant H₂O.','成功！×2舱复制了'+src.e+'。原原子继续滑动，副本出现在标记出口。现在完成H₂O。','Perfetto! La camera ×2 ha copiato '+src.e+'. L’originale ha continuato e la copia è comparsa all’uscita. Ora completa H₂O.'),'happy',4800,'glow');
  }
  wakeMainLoop();return true;
}
function applySynthesizerLanding(i,finishedAnim){
  if(!synthesizerLabActive()||synthesizerComplete||synthesizerFaulted||!finishedAnim||!finishedAnim.synthesizerCrossed||!atoms[i])return{consumed:false,event:'none'};
  const y=synthesizerChamber,a=atoms[i],element=String(a.e||''),valid=element===y.inputA||element===y.inputB;
  const consume=()=>{atoms.splice(i,1);bounce=null;sel=Math.max(0,Math.min(i,atoms.length-1));};
  if(!valid){
    consume();synthesizerBuffer=[];synthesizerFaulted=true;synthesizerFxUntil=performance.now()+1100;
    mxTrack('synthesizer_wrong_input',mxTelemetryLevelParams({element,expected_a:y.inputA,expected_b:y.inputB,moves:Number(moves)||0,attempt_seconds:mxTelemetryAttemptSeconds()}));
    mxHaptic('error');SFX.thunk();prop('Σ  '+element+'  ×',1700);setDrEPose('clipboard',5200,4,true);
    say(ml('Yanlış girdi: '+element+' bu cihazın kalibre edilmiş çiftinde yok. Atom yüksek enerjili işlemde tüketildi ve sentez kilitlendi; GERİ AL ile atomu ve cihaz durumunu geri getir.','Wrong input: '+element+' is not in this device’s calibrated pair. The atom was consumed and synthesis locked; use UNDO to restore both the atom and device state.','Falsche Eingabe: '+element+' gehört nicht zum kalibrierten Paar. Das Atom wurde verbraucht und die Synthese gesperrt; RÜCKGÄNGIG stellt Atom und Gerät wieder her.','Entrada incorrecta: '+element+' no pertenece al par calibrado. El átomo se consumió y la síntesis quedó bloqueada; DESHACER restaura el átomo y el dispositivo.','Entrada errada: '+element+' não pertence ao par calibrado. O átomo foi consumido e a síntese travou; DESFAZER restaura o átomo e o aparelho.','入力エラー：'+element+'は校正済みの組に含まれません。原子は消費され装置がロックしました。「元に戻す」で原子と装置状態を復元できます。','Mauvaise entrée : '+element+' ne fait pas partie de la paire calibrée. L’atome a été consommé et la synthèse verrouillée ; ANNULER restaure l’atome et l’appareil.','输入错误：'+element+'不属于校准输入对。该原子已被消耗且合成器锁定；使用撤销可恢复原子和设备状态。','Ingresso errato: '+element+' non appartiene alla coppia calibrata. L’atomo è stato consumato e la sintesi bloccata; ANNULLA ripristina atomo e dispositivo.'),'sad',6200,'shk');
    wakeMainLoop();return{consumed:true,event:'wrong'};
  }
  if(!synthesizerBuffer.length){
    consume();synthesizerBuffer=[element];synthesizerFxUntil=performance.now()+850;
    if(synthesizerTxnHistoryStart<0)synthesizerTxnHistoryStart=Math.max(0,hist.length-1);
    mxTrack('synthesizer_input_stored',mxTelemetryLevelParams({element,slot:1,moves:Number(moves)||0,attempt_seconds:mxTelemetryAttemptSeconds()}));
    SFX.select();mxHaptic('medium');prop('Σ  '+element+' + ?',1500);
    say(ml(element+' tüketildi ve ilk giriş olarak tutuldu. Şimdi kalibre edilmiş eşini Sentezleyiciye gönder.','The '+element+' atom was consumed and stored as input one. Now feed its calibrated partner into the Synthesizer.','Das '+element+'-Atom wurde verbraucht und als erste Eingabe gespeichert. Führe nun den kalibrierten Partner in den Synthesizer.','El átomo '+element+' se consumió y quedó como primera entrada. Ahora introduce su pareja calibrada en el Sintetizador.','O átomo '+element+' foi consumido e guardado como primeira entrada. Agora envie o parceiro calibrado ao Sintetizador.',''+element+'原子を消費し、1つ目の入力として保持しました。次に校正された相方をシンセサイザーへ送ってください。','L’atome '+element+' a été consommé et stocké comme première entrée. Envoie maintenant son partenaire calibré dans le Synthétiseur.',''+element+'原子已消耗并存为第一输入。现在把与其配对的校准原子送入合成器。','L’atomo '+element+' è stato consumato e conservato come primo ingresso. Ora invia il partner calibrato nel Sintetizzatore.'),'talk',4300,'glow');
    wakeMainLoop();return{consumed:true,event:'stored'};
  }
  const pair=[String(synthesizerBuffer[0]),element].sort().join('|'),recipe=[String(y.inputA),String(y.inputB)].sort().join('|');
  if(pair!==recipe){
    consume();synthesizerBuffer=[];synthesizerFaulted=true;synthesizerFxUntil=performance.now()+1100;
    collapseSynthesizerUndoToOrigin();
    mxTrack('synthesizer_wrong_pair',mxTelemetryLevelParams({element,expected_a:y.inputA,expected_b:y.inputB,moves:Number(moves)||0,attempt_seconds:mxTelemetryAttemptSeconds()}));
    mxHaptic('error');SFX.thunk();prop('Σ  ×',1700);setDrEPose('clipboard',4800,4,true);
    say(ml('İki giriş kalibre edilmiş çifti oluşturmuyor. İkisi de tüketildi ve cihaz kilitlendi; GERİ AL doğru çifti denemeden önce tüm sentez durumunu geri getirir.','Those inputs do not form the calibrated pair. Both were consumed and the device locked; UNDO restores the complete synthesis state before you try the correct pair.','Diese Eingaben bilden nicht das kalibrierte Paar. Beide wurden verbraucht und das Gerät gesperrt; RÜCKGÄNGIG stellt den gesamten Synthesezustand wieder her.','Las entradas no forman el par calibrado. Ambas se consumieron y el dispositivo se bloqueó; DESHACER restaura todo el estado de síntesis.','As entradas não formam o par calibrado. Ambas foram consumidas e o aparelho travou; DESFAZER restaura todo o estado da síntese.','入力が校正済みの組になっていません。両方とも消費され装置がロックしました。「元に戻す」で合成前の全状態を復元できます。','Ces entrées ne forment pas la paire calibrée. Elles ont été consommées et l’appareil verrouillé ; ANNULER restaure tout l’état de synthèse.','两个输入并非校准配对，均已被消耗且设备锁定；撤销会恢复完整的合成前状态。','Gli ingressi non formano la coppia calibrata. Entrambi sono stati consumati e il dispositivo bloccato; ANNULLA ripristina l’intero stato di sintesi.'),'sad',6000,'shk');
    wakeMainLoop();return{consumed:true,event:'wrong-pair'};
  }
  const sx=y.spawnX,sy=y.spawnY,blocked=grid[sy]?.[sx]!==false||atoms.some((b,k)=>k!==i&&b.x===sx&&b.y===sy);
  if(blocked){
    mxHaptic('error');SFX.thunk();setDrEPose('clipboard',3600,3,true);
    say(ml('Σ çıkışı dolu. İkinci giriş henüz tüketilmedi; işaretli çıkış hücresini boşalt ve bu atomu yeniden geçir.','The Σ output is occupied. Input two was not consumed; clear the marked output cell and route this atom through again.','Der Σ-Ausgang ist belegt. Die zweite Eingabe wurde nicht verbraucht; räume den markierten Ausgang und führe das Atom erneut hindurch.','La salida Σ está ocupada. La segunda entrada no se consumió; libera la casilla de salida y vuelve a pasar este átomo.','A saída Σ está ocupada. A segunda entrada não foi consumida; libere a casa de saída e passe o átomo novamente.','Σ出口が塞がれています。2つ目の入力は消費されていません。出口マスを空けて、この原子をもう一度通してください。','La sortie Σ est occupée. La seconde entrée n’a pas été consommée ; libère la case de sortie et refais passer cet atome.','Σ出口被占用。第二输入尚未消耗；清空标记出口格后让该原子再次通过。','L’uscita Σ è occupata. Il secondo ingresso non è stato consumato; libera la casella e fai ripassare l’atomo.'),'talk',4800,'shk');
    return{consumed:false,event:'blocked'};
  }
  const first=String(synthesizerBuffer[0]);consume();
  atoms.push({x:sx,y:sy,e:String(y.output),ph:Math.random()*6.28,frozen:false,fire:false,sticky:false,zombie:false,lightning:false,photonBoost:false,zombieGen:0});
  sel=atoms.length-1;synthesizerBuffer=[];synthesizerComplete=true;synthesizerFxUntil=performance.now()+1300;
  collapseSynthesizerUndoToOrigin();
  mxTrack('synthesizer_created',mxTelemetryLevelParams({input_a:first,input_b:element,output:String(y.output),atom_count:atoms.length,moves:Number(moves)||0,attempt_seconds:mxTelemetryAttemptSeconds()}));
  SFX.sparkle&&SFX.sparkle();mxHaptic('success');prop(first+' + '+element+'  →  '+String(y.output),2200);setDrEPose('happy',5000,4,true);
  say(ml('Sentez tamamlandı: iki giriş tamamen tüketildi ve yeni '+y.output+' atomu işaretli çıkışta oluştu. Bu bir normal kimyasal reaksiyon değil; Moleculox’un yüksek enerjili deneysel element dönüşümüdür.','Synthesis complete: both inputs were fully consumed and a new '+y.output+' atom formed at the marked output. This is not an ordinary chemical reaction; it is Moleculox high-energy experimental element transmutation.','Synthese abgeschlossen: Beide Eingaben wurden vollständig verbraucht, ein neues '+y.output+'-Atom erschien am Ausgang. Das ist keine normale chemische Reaktion, sondern Moleculox-Hochenergie-Elementumwandlung.','Síntesis completa: ambas entradas se consumieron y apareció un átomo '+y.output+' nuevo en la salida. No es una reacción química normal, sino transmutación elemental experimental de alta energía de Moleculox.','Síntese concluída: as duas entradas foram consumidas e um novo átomo '+y.output+' surgiu na saída. Não é reação química comum, mas transmutação elementar experimental de alta energia da Moleculox.','合成完了。2つの入力は完全に消費され、新しい'+y.output+'原子が出口に生成されました。通常の化学反応ではなく、Moleculoxの高エネルギー実験的元素変換です。','Synthèse terminée : les deux entrées ont été consommées et un nouvel atome '+y.output+' est apparu à la sortie. Ce n’est pas une réaction chimique ordinaire, mais une transmutation élémentaire expérimentale à haute énergie Moleculox.','合成完成：两个输入均被完全消耗，新'+y.output+'原子在出口生成。这不是普通化学反应，而是Moleculox高能实验性元素嬗变。','Sintesi completata: entrambi gli ingressi sono stati consumati e un nuovo atomo '+y.output+' è apparso all’uscita. Non è una normale reazione chimica, ma trasmutazione elementare sperimentale ad alta energia Moleculox.'),'happy',6200,'glow');
  wakeMainLoop();return{consumed:true,event:'created'};
}
function deferLandingResolution(i,finishedAnim,landDist){
  const token=++landingResolutionToken,levelAtLanding=lv;
  landingResolutionBusy=true;
  // Finish the visual landing first. Rule checks, character reactions and
  // particle construction run on the following frame instead of stealing the
  // final pixels of the slide on slower phones.
  requestAnimationFrame(()=>{
    if(token!==landingResolutionToken||lv!==levelAtLanding)return;
    try{
      const beforeLandingBonds=Number(finishedAnim.prevBonds)||0;
      applyReplicatorLanding(i,finishedAnim);
      const synthResult=applySynthesizerLanding(i,finishedAnim);
      const movedIdx=synthResult.consumed?undefined:i;
      const landingResult=afterMove(movedIdx);
      const afterLandingBonds=bondsMatched(),bonded=afterLandingBonds>beforeLandingBonds;
      if(!synthResult.consumed)gameFeelLandingContact(i,finishedAnim.d,landDist,bonded);
      if(bonded){mxHaptic('medium');moxyReact('pop',false);}
      if(chainActive()&&!won){if(finishedAnim.chainTrigger)beginChainReaction(finishedAnim.chainTrigger);else if(finishedAnim.chainAutoStep)setTimeout(runNextChainAuto,mobileMechanicResponseBoost()?45:75);}
    }finally{
      if(token===landingResolutionToken)landingResolutionBusy=false;
      if(!anim)setAtomMotionActive(false);
      wakeMainLoop();
    }
  });
}
let T=42,dpr=1,tut=0;

let currentDailyLevel=null,currentDailyId='';
