async function startDaily(){
  try{await ensureFullCampaignReady();}catch(_e){}
  const challenge=certifiedDailyChallenge();
  currentDailyLevel=challenge.level;currentDailyId=challenge.dayId;
  startLevel(challenge.themeIndex,'daily');
  $('#lvPill').textContent=t('todaysExpLabel');
  const advancedNote=challenge.variant==='CAMPAIGN-ADVANCED'?('<br><b>🧪 '+ml('İleri mekanik günlük deney · Kaynak Bölüm ','Advanced-mechanics Daily · Source Level ','Fortgeschrittenes Tagesexperiment · Quelllevel ','Experimento diario avanzado · Nivel fuente ','Experimento diário avançado · Fase de origem ','上級メカニック・デイリー · 元レベル ','Daily avancé · Niveau source ','高级机制每日实验 · 来源关卡 ','Daily avanzato · Livello sorgente ')+challenge.sourceLevel+'</b>'):'';
  setTimeout(()=>say(t('dailyIntro')+advancedNote+'<br>'+levelMoleculeInfoHtml(),'happy',6800,'glow'),220);
}
function goToLevel(i,expectedKey=''){
  i=resolveCampaignLevelIndex(i,expectedKey);
  const nextLv=LEVELS[i],nextMol=nextLv&&MOLS[nextLv.m];
  const tr=$('#levelTransition');

  // Critical rule: gameplay load is never blocked by transition animation.
  // Load the new level immediately; the reveal is only a decorative overlay.
  try{
    startLevel(i,'campaign',expectedKey);
  }catch(err){
    console.error('[next-level] startLevel failed',err);
    levelNavigationBusy=false;
    if(tr){tr.classList.remove('on','mxOut');tr.innerHTML='';}
    show('levels');
    return;
  }

  if(!tr||!nextLv||!nextMol)return;

  const levelLabel=ml('BÖLÜM','LEVEL','LEVEL','NIVEL','FASE','レベル');
  const entryName=String(nextMol.n||''),entryNameLength=Array.from(entryName).length;
  const entrySizeClass=entryNameLength>38?' mxEntryNameXL':(entryNameLength>27?' mxEntryNameLong':'');
  tr.innerHTML=
    '<div class="mxLevelEntryCard'+entrySizeClass+'">'+
      '<small>'+levelLabel+'</small>'+
      '<strong>'+(i+1)+'</strong>'+
      '<div class="mxEntryAtom">⚛</div>'+
      '<b dir="auto">'+esc(entryName)+'</b>'+
      '<em dir="auto">'+esc(nextMol.f||'')+'</em>'+
    '</div>';
  tr.classList.remove('mxOut');
  void tr.offsetWidth;
  tr.classList.add('on');

  try{SFX.whoosh();}catch(_e){}
  // Independent cleanup. Even if this timer is throttled, gameplay is already loaded underneath.
  const entryHold=entryNameLength>27?880:700;
  setTimeout(()=>{
    tr.classList.add('mxOut');
    setTimeout(()=>{
      tr.classList.remove('on','mxOut');
      tr.innerHTML='';
    },240);
  },entryHold);
}

function storyChapterIndex(index){return Math.min(20,Math.floor(index/15));}
