function expansionTriptychPages(index,level,storyArt,options={}){
  const levelNumber=Number(options.levelNumber)||Number(index)+1;
  const narrative=options.narration!==undefined?options.narration:(level&&level.story);
  const chunks=splitStoryTextIntoPages(narrative,3),crops=expansionTriptychCrops(levelNumber);
  const panelArt=expansionStoryPanelArt(levelNumber,!!options.epilogue);
  const mol=level&&MOLS&&MOLS[level.m],formula=options.formula||((mol&&(mol.f||mol.n))||level&&level.m||'');
  return crops.map((crop,step)=>{
    const speaker=step===1?'moxy':'drE';
    const panelImg=Array.isArray(panelArt)&&panelArt[step]?panelArt[step]:(storyArt||'');
    const panelCrop=(Array.isArray(panelArt)&&panelArt[step])?null:crop;
    return {dialogue:expansionStoryDialogue(levelNumber,step,formula,!!options.epilogue),narration:chunks[step],caption:(step===2&&options.finalCaption)?options.finalCaption:expansionStoryPageCaption(step),speaker,cast:[speaker],img:panelImg,crop:panelCrop,bang:'',finale:!!options.finale&&step===2};
  });
}
function storyEpisodeForIndex(index){
  const levelNumber=Number(index)+1;
  const level=Array.isArray(LEVELS)?LEVELS[index]:null;
  // R152: authored canonical episodes win before sparse expansion checkpoints.
  // The former order shadowed Levels 302–305, leaving seven written pages and
  // their illustrations permanently unreachable.
  if(STORY_UNIVERSE&&Array.isArray(STORY_UNIVERSE.episodes)){
    const canonical=STORY_UNIVERSE.episodes.find(ep=>Number(ep&&ep.startLevel)===levelNumber);
    if(canonical)return canonical;
  }
  // R128: expansion story remains sparse, but each supplied triptych is now
  // presented as three real pages with its own dialogue and narration beat.
  if(Number(index)>=301&&level&&level.expansion){
    if(!expansionStoryCheckpoint(index))return null;
    const act=expansionStoryAct(index,level);if(!act)return null;
    const storyArt=expansionStoryArt(index);
    return {id:(level.exp||('exp-'+levelNumber)),startLevel:levelNumber,chapter:act.chapter,title:act.title,world:'',textOnly:!storyArt,finale:levelNumber===501,pages:storyArt?expansionTriptychPages(index,level,storyArt):[{dialogue:level.story,narration:'',caption:'',speaker:'narrator',cast:[],img:'',bang:''}]};
  }
  const act=expansionStoryAct(index,level);
  if(!act)return null;
  const storyArt=expansionStoryArt(index);
  if(storyArt){
    return {id:(level.exp||('exp-'+levelNumber)),startLevel:levelNumber,chapter:act.chapter,title:act.title,world:'',textOnly:false,finale:levelNumber===501,pages:expansionTriptychPages(index,level,storyArt)};
  }
  return {id:(level.exp||('exp-'+levelNumber)),startLevel:levelNumber,chapter:act.chapter,title:act.title,world:'',textOnly:true,pages:[{dialogue:level.story,narration:'',caption:'',speaker:'narrator',cast:[],img:'',bang:''}]};
}
function storyWorldForEpisode(episode){
  if(!episode||!STORY_UNIVERSE||!Array.isArray(STORY_UNIVERSE.worlds))return null;
  return STORY_UNIVERSE.worlds.find(world=>world&&world.id===episode.world)||null;
}
function storyChapterArt(chapterNumber){
  // Final R45: legacy monochrome chapter art was removed. If the standalone
  // story data cannot load, fall back to the matching full-colour world art.
  const n=Math.max(1,Math.min(21,Number(chapterNumber)||1));
  if(n<=5)return 'assets/images/worlds/world-quantum-lab-r40.webp';
  if(n<=10)return 'assets/images/worlds/world-element-island-r40.webp';
  if(n<=15)return 'assets/images/worlds/world-crystal-cave-r40.webp';
  return 'assets/images/worlds/world-orbital-station-r40.webp';
}
function storyPagesFor(level,index){
  const episode=storyEpisodeForIndex(index);
  if(episode){
    const world=storyWorldForEpisode(episode);
    const chapterLabel=storyChapterLabel(episode.chapter,storyTextValue(episode.title));
    const milestoneArt=expansionStoryArt(index);
    return (episode.pages||[]).map((page,pageIndex)=>{
      const suppliedArt=episode.textOnly?'':(page.img||'');
      const checkpointArt=suppliedArt?'':milestoneArt;
      return {
      title:chapterLabel,
      text:storyTextValue(page.dialogue||page.text),
      dialogue:storyTextValue(page.dialogue),
      narration:storyTextValue(page.narration||page.text),
      caption:storyTextValue(page.caption),
      bang:episode.textOnly?'':storyTextValue(Object.prototype.hasOwnProperty.call(page,'bang')?page.bang:(episode.bang||'⚛')),
      speaker:episode.textOnly?(page.speaker||'narrator'):(page.speaker||'drE'),
      cast:episode.textOnly?[]:(Array.isArray(page.cast)?page.cast.slice():[page.speaker||'drE']),
      img:suppliedArt||checkpointArt,
      crop:page.crop||null,
      worldArt:(suppliedArt||checkpointArt)?'':(episode.textOnly?expansionBackgroundUri(index):((level&&level.expansion&&expansionBackgroundUri(index))|| (world&&world.art?world.art:''))),
      worldName:world?storyTextValue(world.name):'',
      episodeId:episode.id||'',
      chapter:Number(episode.chapter)||1,
      finale:!!episode.finale,
      pageNumber:pageIndex+1
    };});
  }
  // Safe legacy fallback if the standalone story-data file is unavailable.
  const chapter=storyChapterIndex(index),rawDetail=level&&level.story?level.story:'';
  const storyLang=normalizeLang(LANG);
  // Final R81: if the standalone story data is unavailable, never leak an
  // English legacy story line into DE/ES/PT/JA. Use the localized generic
  // fallback unless that legacy row explicitly contains the selected language.
  const detail=(rawDetail&&typeof rawDetail==='object')
    ?(rawDetail[storyLang]||((storyLang==='tr'||storyLang==='en')?storyTextValue(rawDetail):''))
    :storyTextValue(rawDetail);
  return [{
    title:(ml("BÖLÜM ","CHAPTER ","KAPITEL ","CAPÍTULO ","CAPÍTULO ","チャプター "))+(chapter+1)+' · MOLECULOX',
    text:detail||(ml("Deneyler devam ediyor.","The experiments continue.","Die Experimente gehen weiter.","Los experimentos continúan.","Os experimentos continuam.","実験は続きます。")),
    caption:ml("Bir sonraki deney seni finale yaklaştırıyor.","The next experiment moves you closer to the finale.","Das nächste Experiment bringt dich dem Finale näher.","El siguiente experimento te acerca a la final.","O próximo experimento aproxima você da final.","次の実験でフィナーレに近づきます。"),
    bang:(level&&level.expansion)?'':'⚛',speaker:(level&&level.expansion)?'narrator':'drE',cast:(level&&level.expansion)?[]:['drE'],img:(level&&level.expansion)?'':storyChapterArt(chapter+1),worldArt:(level&&level.expansion)?expansionBackgroundUri(index):'',episodeId:(level&&level.expansion)?'expansion-text':'legacy',chapter:chapter+1
  }];
}
let storyContinueAction=null,storyPageIndex=0,storyPageList=[],storyActiveLevel=null,storyActiveIndex=-1;
const CURRENT_STORY_SCHEMA=9;
const CURRENT_STORY_VISUAL_SCHEMA=153;
function ensureStorySeenSchema(){
  save.storySeen=save.storySeen&&typeof save.storySeen==='object'?save.storySeen:{};
  if(Number(save.storySchema||0)<CURRENT_STORY_SCHEMA){
    // Preserve already-seen checkpoints across story-data/schema upgrades.
    // Clearing this map caused legitimately completed story chapters to replay.
    save.storySchema=CURRENT_STORY_SCHEMA;persist();
  }
  if(Number(save.storyVisualSchema||0)<CURRENT_STORY_VISUAL_SCHEMA){
    // R153: replay the updated Resonance Vault visual checkpoints in QA so the
    // split full-size story panels and the old-Dr-E cleanup can be verified.
    for(const levelNumber of [302,303,304,305,306,315,326,329,365,396,401,415,416,430,431,445,446,458,480,501])delete save.storySeen[String(levelNumber)];
    delete save.storySeen['501-epilogue'];
    save.storyVisualSchema=CURRENT_STORY_VISUAL_SCHEMA;persist();
  }
}
function ensureStoryPanel(){
  let panel=document.getElementById('levelStoryPanel');if(panel)return panel;
  panel=document.createElement('section');panel.id='levelStoryPanel';panel.setAttribute('aria-live','polite');panel.setAttribute('role','dialog');panel.setAttribute('aria-modal','true');
  panel.innerHTML='<button id="storySkip" type="button" aria-label="'+storyUi('skip')+'">×</button><div class="storyPageHead"><div id="storyChapter"></div><div id="storyPageCounter"></div></div><div class="comicStrip"><div class="comicPanel comicHero"><div class="comicBang" id="storyBang"></div><div class="storyScene"><img id="storyHeroArt" src="assets/images/dr-edward-atom.png" alt="Dr. Edward Atom"><img id="nullStoryArt" src="assets/images/characters/dr-null-canon-r40.webp" alt="Dr. Null"><img id="storyCatArt" src="assets/images/characters/null-cat-canon-r40.webp" alt="Dr. Null cat"><img id="storyMoxyArt" src="assets/images/characters/moxy-canon-r40.webp" alt="Moxy"></div></div><div class="comicPanel comicReaction"><div class="speechBubble"><div class="storySpeakerName" id="storySpeaker"></div><div id="storyText"></div></div><div class="reactionMolecule" id="storyMolecule">⚛</div><div class="storyNarration"><div class="storyNarratorLabel" id="storyNarratorLabel"></div><div id="storyNarration"></div></div><div class="reactionText" id="storyReaction"></div></div></div><div class="storyNav"><button id="storyBack" class="btn" type="button">◀</button><button id="storyContinue" class="btn green" type="button"></button></div><button id="storySkipText" class="storySkipText" type="button"></button>';
  document.body.appendChild(panel);
  const finish=()=>{panel.classList.remove('on');resumeSolveClock('story');clearTimeout(showLevelStory.timer);const cb=storyContinueAction;storyContinueAction=null;storyPageList=[];storyPageIndex=0;storyActiveLevel=null;storyActiveIndex=-1;if(cb)setTimeout(cb,180);};
  panel.querySelector('#storySkip').addEventListener('pointerdown',e=>{e.preventDefault();finish();},{passive:false});
  panel.querySelector('#storySkipText').addEventListener('pointerdown',e=>{e.preventDefault();SFX.back();finish();},{passive:false});
  panel.querySelector('#storyBack').addEventListener('pointerdown',e=>{e.preventDefault();if(storyPageIndex>0){storyPageIndex--;SFX.back();renderStoryPage(panel);}},{passive:false});
  panel.querySelector('#storyContinue').addEventListener('pointerdown',e=>{e.preventDefault();SFX.click();if(storyPageIndex<storyPageList.length-1){storyPageIndex++;renderStoryPage(panel);}else finish();},{passive:false});
  return panel;
}
function preloadStoryNeighbors(){
  for(let step=1;step<=2;step++){
    const next=storyPageList[storyPageIndex+step];
    if(!next) continue;
    const url=next.img||next.worldArt;
    if(url){const im=new Image();im.decoding='async';im.src=url;}
  }
}
function renderStoryPage(panel){
  const page=storyPageList[storyPageIndex]||{},cast=Array.isArray(page.cast)?page.cast:[];
  panel.querySelector('#storyChapter').textContent=page.title||'MOLECULOX';
  panel.querySelector('#storyPageCounter').textContent=(storyPageIndex+1)+' / '+storyPageList.length;
  const dialogue=String(page.dialogue||page.text||'').trim();
  const narration=String(page.narration||'').trim();
  const speakerNames={drE:'DR. EDWARD ATOM',null:'DR. NULL',cat:storyUi('cat'),moxy:'MOXY'};
  panel.querySelector('#storySpeaker').textContent=speakerNames[page.speaker]||'';
  panel.querySelector('#storyText').textContent=dialogue;
  panel.querySelector('#storyNarratorLabel').textContent=storyUi('narrator');
  panel.querySelector('#storyNarration').textContent=narration;
  panel.querySelector('#storyReaction').textContent=page.caption||'';
  panel.classList.toggle('storyHasDialogue',!!dialogue);
  const storyFx=String(page.bang||'').trim();
  panel.querySelector('#storyMolecule').textContent='';
  panel.querySelector('#storyBang').textContent=storyFx;
  panel.classList.toggle('storyHasFx',!!storyFx);
  panel.classList.toggle('showEinstein',cast.includes('drE'));
  panel.classList.toggle('showNull',cast.includes('null'));
  panel.classList.toggle('showCat',cast.includes('cat'));
  panel.classList.toggle('showMoxy',cast.includes('moxy'));
  panel.classList.toggle('bothCharacters',cast.includes('drE')&&cast.includes('null'));
  panel.classList.toggle('speakerNull',page.speaker==='null');
  panel.classList.toggle('speakerCat',page.speaker==='cat');
  panel.classList.toggle('speakerMoxy',page.speaker==='moxy');
  panel.classList.toggle('storyTriptychPage',!!page.crop);
  panel.classList.toggle('storyTriptychRows',!!page.crop&&page.crop.layout==='rows');
  panel.classList.toggle('storyTriptychGrid',!!page.crop&&page.crop.layout==='grid');
  panel.classList.remove('storyCast1','storyCast2','storyCast3','storyCast4');
  panel.classList.add('storyCast'+Math.max(1,Math.min(4,cast.length||1)));
  panel.classList.toggle('storyAltPose',storyPageIndex%2===1);
  panel.querySelector('#storyBack').disabled=storyPageIndex===0;
  const finalPage=storyPageIndex===storyPageList.length-1;
  panel.querySelector('#storyContinue').textContent=finalPage
    ?(page.finale?storyUi('finish'):storyUi('continue'))
    :storyUi('next');
  const hero=panel.querySelector('.comicHero');
  if(hero){
    let sceneImg=hero.querySelector('.sceneArtImg');
    if(page.img){
      /* R152: standalone 16:9 pages remain complete. Supplied triptychs use their
         authored crop metadata, so each story beat shows its own panel rather than
         repeating the complete source three times. */
      if(!sceneImg||String(sceneImg.tagName).toLowerCase()!=='img'){
        if(sceneImg)sceneImg.remove();sceneImg=document.createElement('img');hero.insertBefore(sceneImg,hero.firstChild);
      }
      sceneImg.alt=page.caption||'';sceneImg.src=page.img;
      sceneImg.style.removeProperty('--mx-story-img-w');
      sceneImg.style.removeProperty('--mx-story-img-h');
      sceneImg.style.removeProperty('--mx-story-img-x');
      sceneImg.style.removeProperty('--mx-story-img-y');
      if(page.crop){
        const crop=page.crop,sourceW=Math.max(1,Number(crop.sourceW)||1672),sourceH=Math.max(1,Number(crop.sourceH)||941);
        const cropW=Math.max(1,Number(crop.w)||sourceW),cropH=Math.max(1,Number(crop.h)||sourceH),heroRatio=cropW/cropH;
        hero.style.setProperty('aspect-ratio',String(heroRatio),'important');
        const cropWidthPct=(cropW/(cropH*heroRatio))*100;
        const baseLeftPct=-(Math.max(0,Number(crop.x)||0)/(cropH*heroRatio))*100;
        const overflowPct=Math.max(0,cropWidthPct-100);
        const focus=String(crop.focus||'xMidYMid');
        const explicitFocus=Number(crop.focusX);
        const focusRatio=Number.isFinite(explicitFocus)?Math.max(0,Math.min(1,explicitFocus)):(focus.startsWith('xMin')?0:(focus.startsWith('xMax')?1:.5));
        const focusShift=overflowPct*focusRatio;
        sceneImg.className='sceneArtImg sceneArtCropR152';
        sceneImg.style.setProperty('--mx-story-img-w',(sourceW/(cropH*heroRatio)*100).toFixed(4)+'%');
        sceneImg.style.setProperty('--mx-story-img-h',(sourceH/cropH*100).toFixed(4)+'%');
        sceneImg.style.setProperty('--mx-story-img-x',(baseLeftPct-focusShift).toFixed(4)+'%');
        sceneImg.style.setProperty('--mx-story-img-y',(-(Math.max(0,Number(crop.y)||0)/cropH)*100).toFixed(4)+'%');
      }else{
        hero.style.removeProperty('aspect-ratio');sceneImg.className='sceneArtImg sceneArtFullR152';
      }
      hero.style.backgroundImage='';hero.style.backgroundSize='';hero.style.backgroundPosition='';
      panel.classList.add('hasSceneArt');
    }else{
      if(sceneImg)sceneImg.remove();
      if(page.worldArt){
        hero.style.backgroundImage='linear-gradient(180deg,rgba(3,12,28,.08),rgba(3,12,28,.36)),url("'+page.worldArt.replace(/"/g,'')+'")';
        hero.style.backgroundSize='cover';hero.style.backgroundPosition='center';
      }else{hero.style.backgroundImage='';hero.style.backgroundSize='';hero.style.backgroundPosition='';}
      panel.classList.remove('hasSceneArt');
    }
  }
  preloadStoryNeighbors();
}
