function maybeWarnHardMoveCap(){
  const cap=campaignHardMoveCap(),threshold=hardMoveCapWarningThreshold();
  if(!cap||!threshold||hardMoveCapWarned||won||moves<threshold)return;
  hardMoveCapWarned=true;
  const left=Math.max(0,cap-moves);
  mxTrack('zero_star_window_entered',mxTelemetryLevelParams({moves:moves,move_cap:cap,moves_remaining:left,attempt_seconds:mxTelemetryAttemptSeconds()}));
  setTimeout(()=>{if(!won&&lv>=0&&moves<cap)say(zeroStarWindowCopy(left),'talk',4600,'glow');},180);
}
function showHardMoveCapModal(){return false;}
function autoResetCampaignAtMoveCap(){
  const cap=campaignHardMoveCap();
  if(!cap||won||moves<cap)return false;
  const restartLevel=lv;
  mxTrack('hard_move_cap_auto_reset',mxTelemetryLevelParams({moves:moves,move_cap:cap,reference_moves:Number(LV.referenceMoves||LV.mn||LV.p)||0,attempt_seconds:mxTelemetryAttemptSeconds()}));
  hardMoveCapModalOpen=false;
  closeSayBubble();
  startLevel(restartLevel,'campaign');
  setTimeout(()=>{if(lv===restartLevel&&!won)say(zeroStarCapResetCopy(),'talk',5200,'shk');},140);
  return true;
}
function hardMoveCapBlocksNextMove(){
  if(chainAutoExecuting||autoSolveInProgress||autoSolveExecutingStep)return false;
  const cap=campaignHardMoveCap();
  if(!cap||moves<cap)return false;
  return autoResetCampaignAtMoveCap();
}

function mxFitActionRailToEdward(){
  const rail=$('#actionCol'),ed=$('#einBoxG'),game=(typeof scr!=='undefined'&&scr.game)?scr.game:$('#gameScr');
  if(!rail||!ed||!game||!game.classList.contains('on'))return;
  rail.style.setProperty('--mx-action-rail-lift','0px');
  requestAnimationFrame(()=>{
    if(!game.classList.contains('on'))return;
    const rr=rail.getBoundingClientRect(),er=ed.getBoundingClientRect();
    if(!rr.height||!er.height)return;
    const overlap=Math.max(0,rr.bottom+10-er.top);
    const special=game.classList.contains('reactorMode')||game.classList.contains('chainMode')||game.classList.contains('crystalMode');
    const maxLift=special?92:68;
    rail.style.setProperty('--mx-action-rail-lift',Math.min(maxLift,Math.ceil(overlap))+'px');
  });
}
function updateHUD(){
  $('#movePill').textContent=t('moves',moves,LV.p);
  const sp=$('#starRow').children;
  const count=starsForMoves(moves,LV.p);
  for(let i=0;i<sp.length;i++)sp[i].classList.toggle('off',i>=count);
  const goalCard=$('#goalCard');
  if(goalCard)goalCard.classList.remove('mxGoalBreath','mxGoalNear','mxGoalSuccess','goalPop');
  const crystalOn=crystalActive(),chainOn=chainActive(),reactorOn=reactorActive();
  const cc=$('#crystalCounter');if(cc){cc.classList.toggle('on',crystalOn);renderLabComponentHud(cc);}
  const ch=$('#chainCounter');if(ch){ch.classList.toggle('on',chainOn);ch.classList.toggle('hot',chainOn&&chainAutoActive);ch.textContent=chainOn?chainCounterText():('⚡ '+ml('KOMBO','COMBO','KOMBO','COMBO','COMBO','コンボ')+' x1');}
  const rc=$('#reactorCounter');if(rc){rc.classList.toggle('on',reactorOn);rc.textContent=reactorOn?reactorCounterText():('☢️ '+reactorImpactLabel(true)+' 0');}
  $('#btnUndo').disabled=!hist.length||won||chainAutoActive||autoSolveInProgress;
  const special=duelMode||chainMode||reactorMode,locked=autoSolveInProgress;
  $('#btnHint').disabled=special||locked;$('#btnRestart').disabled=duelMode||locked;$('#btnGear').disabled=special||locked;
  const home=$('#btnHome');if(home)home.disabled=locked;
  ['#btnHammer','#btnPrecision','#btnBarrier'].forEach(id=>{const b=$(id);if(b)b.disabled=locked;});
  $('#btnLab').disabled=special||locked;$('#btnMols').disabled=special||locked;$('#btnAchv').disabled=special||locked;
  maybeWarnHardMoveCap();
}

