/* ================= STANDARD MOLECULE GEOMETRY ================= */
function moleculeGeometryReady(){
  if(!curMol||!atoms.length)return false;
  const minX=Math.min(...atoms.map(b=>b.x)),minY=Math.min(...atoms.map(b=>b.y));
  return curMol.key===atoms.map(a=>a.e+','+(a.x-minX)+','+(a.y-minY)).sort().join('|');
}

function afterMove(movedIdx){
  setDeadlockVisual(false);
  if(movedIdx!==undefined)applyRotationPad(movedIdx);
  if(movedIdx!==undefined)checkLightning(movedIdx);
  checkMelt();
  updateFusionGroups(true);

  const moleculeReady=moleculeGeometryReady();
  const objectiveReady=objectiveCollected();
  if(moleculeReady&&objectiveReady){
    winSeq(movedIdx);
    return;
  }
  if(moleculeReady&&crystalActive()&&!objectiveReady&&!crystalGoalWarned){
    crystalGoalWarned=true;say(objectiveNeedAllCopy(),'talk',3400,'glow');showLabProgressToast(1800);
  }

  if(movedIdx!==undefined&&checkFragileImpact(movedIdx))return;
  if(movedIdx!==undefined){checkStick(movedIdx);checkZombie(movedIdx);}
  if(autoResetCampaignAtMoveCap())return;
  updatePressureDoors(true);
  advanceMovingWalls();
  updateIntensity();
  refreshGoalLastMoveSignal();
  if(onlineDuelMode)queueOnlineLiveState();
  if(demoMode)return;
  if(movedIdx!==undefined)scheduleReactiveEinstein(movedIdx);
  if(tutorialActive&&tutorialStep===3&&movedIdx===0){tutorialGoStep(4);}
  if(!slowSaid&&moves>t2&&!won&&!tutorialActive){slowSaid=true;say(rnd(LN.slow),'talk',3200,'shk');einMood('wag',800);}
}
