function rotatingChamberRouteAction(step){return Array.isArray(step)&&+step[0]===-1&&+step[1]===4;}
function rotatingChamberRouteIndex(step){return rotatingChamberRouteAction(step)&&Number.isInteger(+step[2])?Math.max(0,+step[2]):0;}
