  let d=raw&&Number.isInteger(raw[2])?raw[2]:-1;
  const legal=(ai,dir)=>ai>=0&&atoms[ai]&&dir>=0&&dir<=3&&!atoms[ai].frozen&&!!legalMoveDestination(ai,dir);
