let smartHintReqSeq=0,smartHintWorker=null,smartHintWorkerBusyId=0,smartHintWorkerIdleTimer=0;
const smartHintPending=new Map();
function disposeSmartHintWorker(reason='worker-reset'){
  clearTimeout(smartHintWorkerIdleTimer);smartHintWorkerIdleTimer=0;
  try{if(smartHintWorker)smartHintWorker.terminate();}catch(_){ }
  smartHintWorker=null;smartHintWorkerBusyId=0;
  for(const [id,p] of smartHintPending){clearTimeout(p.timer);try{p.resolve({ok:false,reason});}catch(_){ }}
  smartHintPending.clear();
}
function scheduleSmartHintWorkerIdleDispose(){
  clearTimeout(smartHintWorkerIdleTimer);
  smartHintWorkerIdleTimer=setTimeout(()=>{if(!smartHintWorkerBusyId)disposeSmartHintWorker('worker-idle');},30000);
}
function ensureSmartHintWorker(){
  if(smartHintWorker)return smartHintWorker;
  const w=new Worker('js/smart-hint-worker.js?v=R287-TEST-801');smartHintWorker=w;
  w.onmessage=e=>{
    const r=e.data||{},p=smartHintPending.get(r.id);if(!p)return;
    clearTimeout(p.timer);smartHintPending.delete(r.id);smartHintWorkerBusyId=0;
    if(lv!==p.targetLv)p.resolve({ok:false,reason:'level-changed'});else p.resolve(r);
    scheduleSmartHintWorkerIdleDispose();
  };
  w.onerror=()=>disposeSmartHintWorker('worker-error');
  return w;
}
function requestSmartHintPath(opts={}){
  const direct=matchCurrentToPath(LV&&LV.fs);
  if(direct)return Promise.resolve({ok:true,path:[direct],source:'verified-certified-prefix',nodes:0,ms:0});
  if(typeof Worker==='undefined')return Promise.resolve({ok:false,reason:'worker-unavailable'});
  // A second request while the previous solver is still working should not sit
  // behind a stale search. Cancel that worker and start from the newest board.
  if(smartHintWorkerBusyId)disposeSmartHintWorker('superseded');
  const id=++smartHintReqSeq,targetLv=lv,snap=smartHintSnapshot(),prefer=Array.isArray(LV&&LV.fs)?LV.fs.slice(Math.max(0,moveLog.length),Math.max(0,moveLog.length)+2):[];
  return new Promise(resolve=>{
    let w;
    try{w=ensureSmartHintWorker();}catch(e){resolve({ok:false,reason:'worker-start'});return;}
    const timeout=Math.max(1800,Number(opts.timeout)||5200);
    const timer=setTimeout(()=>{
      const p=smartHintPending.get(id);if(!p)return;smartHintPending.delete(id);smartHintWorkerBusyId=0;
      p.resolve({ok:false,reason:'timeout'});
      // A timed-out synchronous worker is still busy; recycle it rather than
      // letting the next request queue behind an exhausted search.
      disposeSmartHintWorker('timeout-reset');
    },timeout);
    smartHintPending.set(id,{resolve,timer,targetLv});smartHintWorkerBusyId=id;
    try{w.postMessage({id,state:snap,targetKey:snap.targetKey,prefer,maxNodes:opts.maxNodes||65000,maxDepth:opts.maxDepth||22});}
    catch(e){clearTimeout(timer);smartHintPending.delete(id);smartHintWorkerBusyId=0;disposeSmartHintWorker('worker-post');resolve({ok:false,reason:'worker-post'});}
  });
}

