    mxTrack('hint_used',mxTelemetryLevelParams({hint_type:'exact_move_rotating_chamber',cost_molecoin:Number(cost)||0,free_hint:!!useQuantum,hint_count:Number(attemptHintCount)||0,moves:Number(moves)||0}));
