  prop('💡 '+atoms[i].e+' '+DIRAR[d]+charge,4300);
  const prefix=resetToRoute?(ml("Çözüm rotasına dönüldü. ","Solution route restored. ","Lösungsroute wiederhergestellt. ","Ruta de solución restaurada. ","Rota da solução restaurada. ","解答ルートに戻りました。")):'';
  const repClue=repulsorHintText(i,d,true),synthClue=synthesizerHintText(i,d,true),mechanicClue=repClue||synthClue;
  say(prefix+t('hintDir',atoms[i].e,DIRN_()[d],DIRAR[d])+(mechanicClue?'<br><small>'+mechanicClue+'</small>':'')+(cost>0?' <b>−'+cost+' MoleCoin</b> · '+ml('Kalan: ','Balance: ','Rest: ','Saldo: ','Saldo: ','残高: ','Solde : ','余额: ','Saldo: ')+coinBalance():''),'talk',mechanicClue?8200:7200,'glow');
  SFX.hint();updateHUD();
