function currentLevelMechanicIds(){
  if(!LV||lv<0||!scr.game||!scr.game.classList.contains('on'))return [];
  const ids=[];if(LV&&LV.rotatingChamberLab)ids.push('rotatingChamber');
  if(LV&&LV.repulsorLab)ids.push('repulsor');
  if(LV&&LV.synthesizerLab)ids.push('synthesizer');
  if(LV&&LV.replicatorLab)ids.push('replicator');
  if(LV&&LV.photonBoostLab)ids.push('photonBoost');
  if(atoms.some(a=>a.frozen))ids.push('frozen');
  if(atoms.some(a=>a.fire))ids.push('fire');
  if(atoms.some(a=>a.lightning))ids.push('lightning');
  if(atoms.some(a=>a.sticky))ids.push('sticky');
  if(atoms.some(a=>a.zombie))ids.push('zombie');
  if(oneWayTiles&&oneWayTiles.size)ids.push('oneWay');
  if(breakableWalls&&[...breakableWalls.values()].some(w=>!w.broken))ids.push('hammer');
  if(portalPairs&&portalPairs.size)ids.push('portal');
  if(riftPairs&&riftPairs.size)ids.push('rift');
  if(movingWalls&&movingWalls.length)ids.push('movingWall');
  if(pressureSystems&&pressureSystems.length)ids.push('pressureDoor');
  if(atoms.some(a=>a.fragile))ids.push('fragile');
  if(linkedPairs&&linkedPairs.length)ids.push('linked');
  if(fusionActive())ids.push('fusion');
  if(prebuiltActive())ids.push('prebuilt');
  if(rotationActive())ids.push('rotation');
  if(typeof enzymeActive==='function'&&enzymeActive())ids.push('enzymeGate');else if(typeof bioActive==='function'&&bioActive())ids.push('bioAssembly');else if(typeof crystalActive==='function'&&crystalActive())ids.push('classicCatalyst');
  if(typeof chainActive==='function'&&chainActive())ids.push('classicChain');
  if(typeof reactorActive==='function'&&reactorActive())ids.push('classicReactor');
  return [...new Set(ids)];
}

function mxMechanicSvg(id){
  const safe=String(id||'').replace(/[^A-Za-z0-9_-]/g,'');
  return '<svg class="mxMechanicSvg mxMechanicSvg--'+safe+'" viewBox="0 0 32 32" aria-hidden="true" focusable="false"><use href="#mlx-mech-'+safe+'"></use></svg>';
}
function updateLevelMechanicBar(){
  const bar=$('#levelMechanicBar');if(!bar)return;
  // R183: Catalyst/Chain/Reactor already have dedicated HUD counters. Repeating the
  // same mode as a second mechanic chip made those levels' HUD taller, which in
  // turn forced the 8x10 board and atoms to shrink. Keep the legend for genuine
  // board mechanics, but remove only the redundant mode chip.
  const ids=currentLevelMechanicIds().filter(id=>id!=='classicCatalyst'&&id!=='classicChain'&&id!=='classicReactor');
  const legendOn=!!ids.length&&!duelMode;
  if(scr.game)scr.game.classList.toggle('mxMechanicLegendOn',legendOn);
  if(!legendOn){bar.hidden=true;bar.innerHTML='';return;}
  bar.hidden=false;
  bar.setAttribute('aria-label',ml('Bu deneydeki özel mekanikler','Special mechanics in this experiment','Spezielle Mechaniken in diesem Experiment','Mecánicas especiales de este experimento','Mecânicas especiais deste experimento','この実験の特殊メカニック','Mécaniques spéciales de cette expérience','本实验的特殊机制','Meccaniche speciali di questo esperimento'));
  bar.innerHTML=ids.map(id=>{const info=MECHANIC_INFO[id];if(!info)return '';const title=mechanicTitleLabel(info);return '<button type="button" class="mxLevelMechanicChip mxLevelMechanicChip--'+id+'" data-level-mechanic="'+id+'" title="'+String(title).replace(/&/g,'&amp;').replace(/"/g,'&quot;')+'" aria-label="'+String(title).replace(/&/g,'&amp;').replace(/"/g,'&quot;')+'">'+mxMechanicSvg(id)+'<span class="srOnly">'+String(title).replace(/&/g,'&amp;').replace(/"/g,'&quot;')+'</span></button>';}).join('');
  bar.querySelectorAll('[data-level-mechanic]').forEach(btn=>bindTap(btn,()=>{SFX.select();showMechanicBriefing([btn.dataset.levelMechanic],{fromLevelBar:true});}));
}
function blockedMechanicExplanation(i,d){
  if(!atoms[i])return '';
  const g=fusionGroupFor(i);
  if(g){
    if(g.kind==='prebuilt')return ml('🧩 Bu atom hazır rijit modülün parçası. Tek başına hareket etmez; modülün bütün atomlarının yolu açık olmalı.','🧩 This atom belongs to a prebuilt rigid module. It cannot move alone; every atom in the module needs a clear path.','🧩 Dieses Atom gehört zu einem vorgefertigten starren Modul. Es bewegt sich nicht allein; der Weg muss für alle Atome des Moduls frei sein.','🧩 Este átomo pertenece a un módulo rígido preparado. No puede moverse solo; todos los átomos del módulo necesitan el camino libre.','🧩 Este átomo pertence a um módulo rígido pronto. Ele não se move sozinho; todos os átomos do módulo precisam ter o caminho livre.','🧩 この原子は完成済みの剛体モジュールの一部です。単独では動かず、モジュール全体の進路が空いている必要があります。','🧩 Cet atome appartient à un module rigide préassemblé. Il ne se déplace pas seul ; le trajet doit être libre pour tous les atomes du module.','🧩 这个原子属于预组装的刚性模块，不能单独移动；模块中所有原子的路径都必须畅通。','🧩 Questo atomo fa parte di un modulo rigido preassemblato. Non si muove da solo; il percorso deve essere libero per tutti gli atomi del modulo.');
    return ml('🧬 Bu atom tamamlanmış bir Fusion grubunun parçası. Grup birlikte hareket eder; üyelerden birinin yolu kapalıysa tüm grup durur.','🧬 This atom is part of a completed Fusion group. The group moves together; if one member is blocked, the whole group stops.','🧬 Dieses Atom gehört zu einer fertigen Fusion-Gruppe. Die Gruppe bewegt sich gemeinsam; ist ein Mitglied blockiert, stoppt die gesamte Gruppe.','🧬 Este átomo forma parte de un grupo de Fusión completado. El grupo se mueve unido; si un miembro está bloqueado, se detiene todo el grupo.','🧬 Este átomo faz parte de um grupo de Fusão concluído. O grupo se move junto; se um membro estiver bloqueado, todo o grupo para.','🧬 この原子は完成したフュージョングループの一部です。グループは一体で動き、1つでも塞がれると全体が止まります。','🧬 Cet atome fait partie d’un groupe de Fusion terminé. Le groupe se déplace ensemble ; si un membre est bloqué, tout le groupe s’arrête.','🧬 这个原子属于已完成的融合刚性组。整个组一起移动；任一成员受阻，整个组都会停止。','🧬 Questo atomo fa parte di un gruppo di Fusione completato. Il gruppo si muove insieme; se un membro è bloccato, si ferma tutto il gruppo.');
  }
  if(stickyMate.has(i))return ml('🍯 Bu atom yapışkan bir çiftin parçası. İki atom birlikte kayar; ikisinden birinin yolu kapalıysa çift hareket etmez.','🍯 This atom is part of a sticky pair. Both atoms slide together; if either path is blocked, the pair cannot move.','🍯 Dieses Atom gehört zu einem Klebepaar. Beide gleiten gemeinsam; ist einer der Wege blockiert, bewegt sich das Paar nicht.','🍯 Este átomo forma parte de una pareja pegajosa. Ambos se deslizan juntos; si uno de los caminos está bloqueado, la pareja no se mueve.','🍯 Este átomo faz parte de um par pegajoso. Os dois deslizam juntos; se um dos caminhos estiver bloqueado, o par não se move.','🍯 この原子は粘着ペアの一部です。2つは一緒に滑り、どちらかの進路が塞がれると動けません。','🍯 Cet atome fait partie d’une paire collante. Les deux glissent ensemble ; si l’un des trajets est bloqué, la paire ne bouge pas.','🍯 这个原子属于黏性组合。两个原子一起滑动；任一路径受阻时，这一对都无法移动。','🍯 Questo atomo fa parte di una coppia adesiva. I due scorrono insieme; se uno dei percorsi è bloccato, la coppia non si muove.');
  if(linkedMate.has(i))return ml('🔗 Bu atom bağlı eşine göre hareket eder. İki atomun hareket kuralını birlikte düşün; bağlantı tek atomluk normal kaydırma değildir.','🔗 This atom is linked to its partner. Plan the movement of both atoms together; the link is not a normal single-atom slide.','🔗 Dieses Atom ist mit seinem Partner verbunden. Plane beide Bewegungen zusammen; die Verbindung ist kein normaler Einzelzug.','🔗 Este átomo está enlazado con su pareja. Planifica el movimiento de ambos; el enlace no es un deslizamiento normal de un solo átomo.','🔗 Este átomo está ligado ao parceiro. Planeje o movimento dos dois; a ligação não é um deslizamento normal de um único átomo.','🔗 この原子は相方とリンクしています。2つの動きを一緒に考えてください。通常の単独スライドではありません。','🔗 Cet atome est lié à son partenaire. Planifiez le mouvement des deux ; ce lien n’est pas un glissement normal d’un seul atome.','🔗 这个原子与伙伴相连。请同时考虑两个原子的移动；这不是普通的单原子滑动。','🔗 Questo atomo è collegato al suo compagno. Pianifica il movimento di entrambi; il collegamento non è uno scorrimento normale di un singolo atomo.');
  const [dx,dy]=DIRS[d],nx=atoms[i].x+dx,ny=atoms[i].y+dy;
  if(!oneWayAllows(atoms[i].x,atoms[i].y,nx,ny,d))return ml('↪️ Tek yönlü zemin bu yöndeki geçişe izin vermiyor. Ok yönünü takip et.','↪️ The one-way floor does not allow movement in this direction. Follow the arrow.','↪️ Das Einbahnfeld erlaubt diese Richtung nicht. Folge dem Pfeil.','↪️ La casilla de un solo sentido no permite esta dirección. Sigue la flecha.','↪️ O piso de mão única não permite esta direção. Siga a seta.','↪️ 一方通行マスではこの方向へ進めません。矢印に従ってください。','↪️ La case à sens unique n’autorise pas cette direction. Suivez la flèche.','↪️ 单向地块不允许这个方向。请沿箭头方向移动。','↪️ La casella a senso unico non permette questa direzione. Segui la freccia.');
  if(enzymeGate&&!enzymeGate.open&&enzymeGate.x===nx&&enzymeGate.y===ny)return ml('🧬 Enzim/Bio kapısı henüz kapalı. Üstte gösterilen gerekli biyolojik parçaları tamamlayınca açılacak.','🧬 The Enzyme/Bio gate is still closed. It opens after you complete the required biological components shown above.','🧬 Das Enzym-/Bio-Tor ist noch geschlossen. Es öffnet sich, sobald die oben gezeigten Bio-Komponenten vollständig sind.','🧬 La puerta Enzyme/Bio sigue cerrada. Se abrirá al completar los componentes biológicos indicados arriba.','🧬 O portal Enzyme/Bio ainda está fechado. Ele abre ao completar os componentes biológicos mostrados acima.','🧬 酵素／Bioゲートはまだ閉じています。上に表示された必要な生体パーツをそろえると開きます。','🧬 La porte Enzyme/Bio est encore fermée. Elle s’ouvrira lorsque les composants biologiques indiqués en haut seront complétés.','🧬 酶/Bio门仍然关闭。完成上方显示的所需生物组件后才会开启。','🧬 La porta Enzyme/Bio è ancora chiusa. Si aprirà quando completi i componenti biologici richiesti mostrati in alto.');
  const ps=pressureSystems.find(sys=>sys.door&&sys.door.x===nx&&sys.door.y===ny);
  if(ps&&!pressureOccupied(ps))return ml('🔘 Basınç kapısı kapalı. Aynı harfli düğmenin üzerinde bir atom tutarak kapıyı aç.','🔘 The pressure door is closed. Keep an atom on the switch with the same letter to open it.','🔘 Die Drucktür ist geschlossen. Halte ein Atom auf dem Schalter mit demselben Buchstaben, um sie zu öffnen.','🔘 La puerta de presión está cerrada. Mantén un átomo sobre el interruptor con la misma letra para abrirla.','🔘 A porta de pressão está fechada. Mantenha um átomo no botão com a mesma letra para abri-la.','🔘 圧力ドアは閉じています。同じ文字のスイッチ上に原子を置いて開けてください。','🔘 La porte à pression est fermée. Maintenez un atome sur l’interrupteur portant la même lettre pour l’ouvrir.','🔘 压力门关闭。让一个原子停在同字母开关上即可开启。','🔘 La porta a pressione è chiusa. Mantieni un atomo sull’interruttore con la stessa lettera per aprirla.');
  if(movingWalls.some(w=>w.x===nx&&w.y===ny))return ml('🚧 Hareketli duvar şu anda yolu kapatıyor. Bir sonraki konumunu hesaba kat.','🚧 The moving wall is blocking the path right now. Plan around its next position.','🚧 Die bewegliche Wand blockiert gerade den Weg. Plane ihre nächste Position ein.','🚧 La pared móvil está bloqueando el camino ahora. Ten en cuenta su siguiente posición.','🚧 A parede móvel está bloqueando o caminho agora. Considere a próxima posição dela.','🚧 移動壁が現在進路を塞いでいます。次の位置を考えて動いてください。','🚧 Le mur mobile bloque actuellement le passage. Anticipez sa prochaine position.','🚧 移动墙当前挡住了路径。请考虑它的下一个位置。','🚧 Il muro mobile sta bloccando il percorso. Considera la sua prossima posizione.');
  const bw=breakableWalls.get(breakableKey(nx,ny));
  if(bw&&!bw.broken)return ml('🔨 Bu çatlak duvar normal kaydırmayla geçilmez. İstersen Hammer kullanarak kaldırabilirsin.','🔨 This cracked wall cannot be passed by a normal slide. You may remove it with the Hammer.','🔨 Diese rissige Wand kann nicht normal passiert werden. Du kannst sie mit dem Hammer entfernen.','🔨 Esta pared agrietada no se atraviesa con un deslizamiento normal. Puedes quitarla con el Martillo.','🔨 Esta parede rachada não pode ser atravessada com um deslizamento normal. Você pode removê-la com o Martelo.','🔨 このひび割れ壁は通常のスライドでは通れません。必要ならハンマーで壊せます。','🔨 Ce mur fissuré ne se traverse pas par un glissement normal. Vous pouvez le retirer avec le Marteau.','🔨 这面裂墙不能通过普通滑动穿过。你可以使用锤子将其移除。','🔨 Questo muro crepato non si supera con uno scorrimento normale. Puoi rimuoverlo con il Martello.');
  return '';
}
function mechanicVisualCue(id){
  const cues={
    rotatingChamber:()=>ml('Görünüş: kesik camgöbeği kare çerçeve ve merkezde ↻. Alana dokunmak odayı 90° döndürür ve 1 hamle sayar. 552’den sonra A/B/C etiketli birden fazla oda bağımsız dönebilir; sıra önemlidir.','Look: a dashed cyan square chamber with ↻ at its center. Tapping it rotates the chamber 90° and costs 1 move. From 552 onward, multiple A/B/C chambers can rotate independently, so order matters.','Aussehen: gestrichelte türkise Kammer mit ↻ in der Mitte. Antippen dreht sie um 90° und kostet 1 Zug.','Aspecto: cámara cuadrada cian discontinua con ↻ en el centro. Tocarla gira 90° y cuesta 1 movimiento.','Visual: câmara quadrada ciano tracejada com ↻ no centro. Tocar gira 90° e custa 1 jogada.','見た目：シアンの点線四角と中央の↻。タップで90°回転し1手を消費。','Aspect : chambre carrée cyan en pointillés avec ↻ au centre. La toucher la tourne de 90° pour 1 coup.','外观：青色虚线方形舱室，中央有↻。点击旋转90°并计1步。','Aspetto: camera quadrata ciano tratteggiata con ↻ al centro. Toccarla ruota di 90° e costa 1 mossa.'),
    repulsor:()=>ml('Görünüş: duvar hücresindeki ⇱ enerji çekirdeği ve çevresindeki dört hafif parlayan etki hücresi. Atom bu hücrelerden birine girince çekirdekten dümdüz uzağa itilir. Yön okları yalnız ilk eğitimde kısa süre görünür.','Look: a ⇱ energy core inside a wall cell with four softly glowing trigger cells around it. Enter one of them and the atom is pushed straight away from the Core. Direction arrows appear only briefly in the first lesson.','Aussehen: ⇱-Energiekern in einer Wandzelle mit vier sanft leuchtenden Auslösefeldern. Betritt ein Atom eines davon, wird es direkt vom Kern weggestoßen. Richtungspfeile erscheinen nur kurz in der ersten Lektion.','Aspecto: núcleo ⇱ en una pared con cuatro casillas de activación suavemente iluminadas. Al entrar en una, el átomo es empujado directamente lejos del Núcleo. Las flechas solo aparecen brevemente en la primera lección.','Visual: núcleo ⇱ numa parede com quatro casas de ativação suavemente brilhantes. Ao entrar numa delas, o átomo é empurrado diretamente para longe do Núcleo. As setas aparecem apenas por instantes na primeira lição.','見た目：壁マス内の⇱コアと周囲4つの淡く光る作動マス。入ると原子はコアから真っすぐ外向きに押されます。方向矢印は最初のレッスンで短時間だけ表示されます。','Aspect : noyau ⇱ dans une case murale avec quatre cases de déclenchement légèrement lumineuses. En y entrant, l’atome est repoussé directement à l’opposé du Noyau. Les flèches n’apparaissent que brièvement dans la première leçon.','外观：墙格中的⇱能量核心，周围有四个轻微发光的触发格。原子进入后会被直接推向远离核心的方向。方向箭头只在第一次教学中短暂显示。','Aspetto: nucleo ⇱ in una casella muro con quattro celle di attivazione leggermente luminose. Entrando in una di esse, l’atomo viene spinto direttamente lontano dal Nucleo. Le frecce appaiono solo brevemente nella prima lezione.'),
    synthesizer:()=>ml('Görünüş: zemindeki Σ karesi giriş odasıdır; iki küçük yuva tüketilen girişleri gösterir. Element harfli daire yeni atomun doğacağı belirlenmiş çıkıştır. A + B → C; A ve B artık tahtada kalmaz.','Look: the Σ floor square is the input chamber; its two small slots show consumed inputs. The circled element marks the fixed output where the new atom appears. A + B → C; A and B do not remain on the board.','Aussehen: Das Σ-Feld ist die Eingabekammer; zwei kleine Plätze zeigen verbrauchte Eingaben. Der Elementkreis markiert den festen Ausgang. A + B → C; A und B bleiben nicht auf dem Brett.','Aspecto: la casilla Σ es la entrada; dos ranuras muestran las entradas consumidas. El círculo con elemento marca la salida fija. A + B → C; A y B no permanecen en el tablero.','Visual: a casa Σ é a entrada; dois encaixes mostram as entradas consumidas. O círculo com elemento marca a saída fixa. A + B → C; A e B não permanecem no tabuleiro.','見た目：Σ床が入力室、2つの小枠が消費済み入力を示します。元素記号入りの円が新原子の固定出口です。A+B→Cで、AとBは盤面に残りません。','Aspect : la case Σ est l’entrée ; deux petits emplacements montrent les entrées consommées. Le cercle avec symbole marque la sortie fixe. A + B → C ; A et B ne restent pas sur le plateau.','外观：Σ地格是输入舱，两个小槽表示已消耗输入；带元素符号的圆圈是新原子的固定出口。A+B→C，A和B不会留在棋盘上。','Aspetto: la casella Σ è l’ingresso; due piccoli alloggi mostrano gli ingressi consumati. Il cerchio con elemento è l’uscita fissa. A + B → C; A e B non restano sulla tavola.'),
    photonBoost:()=>ml('Görünüş: zemindeki hν pedi atomu parlak bir foton halesiyle yükler. Hale varken atom bir engelleyici atomun içinden bir kez geçer; sonra hale söner.','Look: the hν floor pad gives the atom a bright photon halo. While the halo is active it can phase through one blocking atom; then the halo disappears.','Aussehen: Das hν-Feld gibt dem Atom einen hellen Photonenring. Solange er leuchtet, kann es einmal durch ein blockierendes Atom gleiten; danach erlischt der Ring.','Aspecto: la plataforma hν da al átomo un halo fotónico. Mientras brilla puede atravesar un átomo bloqueador una vez; después desaparece.','Visual: o piso hν dá ao átomo um halo de fóton. Enquanto brilha, ele atravessa um átomo bloqueador uma vez; depois o halo some.','見た目：hνパッドで原子に光るフォトンハローが付きます。光っている間は邪魔な原子を1個だけ通り抜け、その後ハローが消えます。','Aspect : la dalle hν donne un halo photonique à l’atome. Tant qu’il brille, il peut traverser une fois un atome bloquant ; le halo disparaît ensuite.','外观：hν地格会给原子加上明亮光子光环。光环存在时可穿过一个挡路原子，随后光环消失。','Aspetto: la piattaforma hν dà all’atomo un alone fotonico. Finché brilla può attraversare una volta un atomo bloccante; poi l’alone svanisce.'),
    replicator:()=>ml('Görünüş: zemindeki parlak ×2 odası giriş; küçük + işaretli hücre kopyanın çıkışıdır. Atom ×2 üzerinden kayarken kopya otomatik doğar.','Look: the glowing ×2 floor chamber is the input; the small + cell marks the copy output. A copy is created automatically while the atom slides through ×2.','Aussehen: Das leuchtende ×2-Feld ist der Eingang; das kleine + markiert den Kopie-Ausgang. Beim Durchgleiten wird automatisch eine Kopie erzeugt.','Aspecto: la cámara ×2 brillante es la entrada; la casilla + marca la salida de la copia. Al deslizarse por ×2 se crea una copia automáticamente.','Visual: a câmara ×2 brilhante é a entrada; a casa + marca a saída da cópia. Ao atravessar ×2, uma cópia nasce automaticamente.','見た目：光る×2床が入口、小さな+マスがコピーの出口です。原子が×2を通過すると自動でコピーが生成されます。','Aspect : la case ×2 lumineuse est l’entrée ; la petite case + indique la sortie de la copie. Le passage dans ×2 crée automatiquement une copie.','外观：发光的×2地格是入口，小“+”格是副本出口。原子滑过×2时会自动生成副本。','Aspetto: la camera ×2 luminosa è l’ingresso; la casella + indica l’uscita della copia. Attraversando ×2 nasce automaticamente una copia.'),
    frozen:()=>ml('Görünüş: atomun üzerinde ❄️ buz işareti.','Look: ❄️ ice symbol on the atom.','Aussehen: ❄️-Symbol auf dem Atom.','Aspecto: símbolo ❄️ sobre el átomo.','Visual: símbolo ❄️ no átomo.','見た目：原子上の❄️印。'),
    fire:()=>ml('Görünüş: atomun üzerinde 🔥 alev.','Look: 🔥 flame on the atom.','Aussehen: 🔥 auf dem Atom.','Aspecto: 🔥 sobre el átomo.','Visual: 🔥 no átomo.','見た目：原子上の🔥。'),
    lightning:()=>ml('Görünüş: atomun üzerinde ⚡ yük simgesi.','Look: ⚡ charge symbol on the atom.','Aussehen: ⚡-Ladungssymbol.','Aspecto: símbolo ⚡ de carga.','Visual: símbolo ⚡ de carga.','見た目：原子上の⚡印。'),
    sticky:()=>ml('Görünüş: atomun üzerinde 🍯 bal simgesi ve kehribar yapışkan halka. Temas ettiği ilk hareketli atomla birlikte kayar.','Look: 🍯 honey symbol on the atom with an amber sticky ring. The first movable atom it touches will then slide with it.','Aussehen: 🍯-Honigsymbol am Atom mit bernsteinfarbenem Klebering. Das erste bewegliche Atom, das es berührt, gleitet danach mit ihm.','Aspecto: símbolo 🍯 sobre el átomo y aro adhesivo ámbar. El primer átomo móvil que lo toque se deslizará después junto a él.','Visual: símbolo 🍯 no átomo e anel adesivo âmbar. O primeiro átomo móvel que o tocar passará a deslizar junto com ele.','見た目：原子上の🍯マークと琥珀色の粘着リング。最初に触れた移動可能な原子と、その後は一緒に滑ります。','Aspect : symbole 🍯 sur l’atome et anneau collant ambré. Le premier atome mobile qui le touche glissera ensuite avec lui.','外观：原子上有🍯蜂蜜标记和琥珀色黏性环。第一个接触它的可移动原子之后会与它一起滑动。','Aspetto: simbolo 🍯 sull’atomo e anello adesivo ambrato. Il primo atomo mobile che lo tocca poi scorrerà insieme a lui.'),
    zombie:()=>ml('Görünüş: sabit çift yörünge, iki faz düğümü ve çatlak enerji çekirdeği kararsız atomu işaretler.','Look: fixed twin orbits, two phase nodes and a fractured energy core mark an unstable atom.','Aussehen: feste Doppelbahnen, zwei Phasenknoten und ein gebrochener Energiekern markieren ein instabiles Atom.','Aspecto: órbitas dobles fijas, dos nodos de fase y un núcleo de energía fracturado marcan un átomo inestable.','Visual: órbitas duplas fixas, dois nós de fase e um núcleo de energia fraturado marcam um átomo instável.','見た目：固定された二重軌道、2つの位相ノード、亀裂の入ったエネルギー核が不安定原子の印です。','Aspect : deux orbites fixes, deux nœuds de phase et un noyau d’énergie fracturé signalent un atome instable.','外观：固定双轨道、两个相位节点与破裂能量核心表示不稳定原子。','Aspetto: doppie orbite fisse, due nodi di fase e un nucleo energetico fratturato indicano un atomo instabile.'),
    oneWay:()=>ml('Görünüş: zemindeki büyük ok; yalnız ok yönünde geçilir.','Look: large floor arrow; pass only with it.','Aussehen: großer Bodenpfeil; nur in Pfeilrichtung.','Aspecto: flecha grande en el suelo.','Visual: seta grande no chão.','見た目：床の大きな矢印。'),
    hammer:()=>ml('Görünüş: çatlak duvarın köşesinde küçük 🔨 işareti.','Look: cracked wall with a small 🔨 mark.','Aussehen: rissige Wand mit kleinem 🔨.','Aspecto: pared agrietada con 🔨.','Visual: parede rachada com 🔨.','見た目：ひび割れ壁と小さな🔨。'),
    rift:()=>ml('Görünüş: siyah-mor yarık ve elmas işaretli eş Rift karoları geçerken zorunlu ışınlar.','Look: black-violet rifts with diamond markers force a warp while crossing.','Aussehen: Schwarz-violette Risse mit Rautensymbol lösen beim Überqueren einen Zwangs-Warp aus.','Aspecto: las fisuras negro-violeta con rombos fuerzan el salto al cruzarlas.','Visual: fendas preto-violeta com losango forçam o salto ao atravessar.','見た目：黒紫の裂け目と菱形マーク。通過時に強制ワープ。','Aspect : failles noir-violet à losange, téléportation forcée au passage.','外观：黑紫色裂隙带菱形标记，经过时强制传送。','Aspetto: fenditure nero-viola con rombo, teletrasporto forzato al passaggio.'),
    portal:()=>ml('Görünüş: dönen A ve B portalları birbirinin eşidir.','Look: spinning A and B portals are paired.','Aussehen: drehende Portale A und B gehören zusammen.','Aspecto: los portales A y B están emparejados.','Visual: portais A e B são um par.','見た目：回転するA/Bポータル。'),
    movingWall:()=>ml('Görünüş: üzerinde ↔ bulunan çizgili duvar.','Look: striped wall marked ↔.','Aussehen: gestreifte Wand mit ↔.','Aspecto: pared rayada con ↔.','Visual: parede listrada com ↔.','見た目：↔印の縞壁。'),
    pressureDoor:()=>ml('Görünüş: aynı harfli yuvarlak düğme + çizgili kapı. Çizgili/şeffafsa açıktır.','Look: round switch + striped door with the same letter. Striped/transparent means open.','Aussehen: runder Schalter und gestreifte Tür mit gleichem Buchstaben. Transparent = offen.','Aspecto: interruptor redondo y puerta rayada con la misma letra. Transparente = abierta.','Visual: botão redondo e porta listrada com a mesma letra. Transparente = aberta.','見た目：同じ文字の丸スイッチと縞扉。透明なら開いています。'),
    fragile:()=>ml('Görünüş: elmas çerçeve ve kalan darbe sayısı.','Look: diamond outline plus remaining-impact number.','Aussehen: Diamantrahmen plus Resttrefferzahl.','Aspecto: marco de diamante y número restante.','Visual: moldura de diamante e número restante.','見た目：ダイヤ枠と残り回数。'),
    linked:()=>ml('Görünüş: iki atom arasında hareketli noktalı bağ.','Look: animated dotted link between two atoms.','Aussehen: bewegte gestrichelte Verbindung.','Aspecto: línea de puntos animada.','Visual: linha pontilhada animada.','見た目：2原子間の動く点線。'),
    precision:()=>ml('Görünüş: seçili atomun çevresinde 🎯 hedef halkası ve 1 □ göstergesi.','Look: a 🎯 target ring around the selected atom plus the 1 □ indicator.','Aussehen: 🎯-Zielring um das gewählte Atom und Anzeige 1 □.','Aspecto: aro 🎯 alrededor del átomo seleccionado e indicador 1 □.','Visual: anel 🎯 no átomo selecionado e indicador 1 □.','見た目：選択原子の🎯リングと1 □表示。'),
    rotation:()=>ml('Görünüş: zeminde mor-mavi dönen halka ve ortasında 90° işareti.','Look: a violet-cyan rotating floor ring marked 90°.','Aussehen: violett-türkiser Drehring mit 90°-Markierung.','Aspecto: aro giratorio violeta-cian con 90°.','Visual: anel giratório violeta-ciano com 90°.','見た目：紫とシアンに光る90°回転リング。','Aspect : anneau rotatif violet-cyan marqué 90°.','外观：紫青色旋转地环，中间标有90°。','Aspetto: anello rotante viola-ciano con indicazione 90°.'),
    prebuilt:()=>ml('Görünüş: hazır modülün bağları altın/camgöbeği çift parıltıyla vurgulanır.','Look: the ready module uses a gold/cyan double glow.','Aussehen: Das fertige Modul leuchtet gold/türkis.','Aspecto: el módulo listo usa un doble brillo dorado/cian.','Visual: o módulo pronto usa brilho duplo dourado/ciano.','見た目：完成済みモジュールは金色／シアンの二重発光。','Aspect : le module prêt a une double lueur or/cyan.','外观：现成模块使用金色/青色双重辉光。','Aspetto: il modulo pronto usa un doppio bagliore oro/ciano.'),
    fusion:()=>ml('Görünüş: tamamlanan alt yapının atomları mor-mavi çift bağ ışımasıyla tek grup olarak işaretlenir.','Look: a completed sub-structure is marked as one group by a violet-cyan double bond glow.','Aussehen: Eine fertige Teilstruktur wird durch ein violett-türkises Doppelglühen als Gruppe markiert.','Aspecto: una subestructura completada queda marcada como grupo con un brillo doble violeta-cian.','Visual: uma subestrutura concluída é marcada como grupo por um brilho duplo violeta-ciano.','見た目：完成した部分構造は紫とシアンの二重発光で1グループとして表示されます。','Aspect : une sous-structure terminée est marquée comme un groupe par une double lueur violet-cyan.','外观：完成的子结构会以紫色—青色双重发光标记为一个整体。','Aspetto: una sottostruttura completata viene segnata come gruppo da un doppio bagliore viola-ciano.'),
    bioAssembly:()=>ml('Görünüş: A–T, C–G ve omurga parçaları tamamlanınca mor Bio Assembly alanı yeşil onayla açılır.','Look: after A–T, C–G and backbone pieces are collected, the violet Bio Assembly field opens with a green check.','Aussehen: Nach A–T, C–G und Rückgrat öffnet sich das violette Bio-Assembly-Feld mit grünem Häkchen.','Aspecto: tras A–T, C–G y el esqueleto, el campo Bio Assembly violeta se abre con una marca verde.','Visual: após A–T, C–G e a espinha dorsal, o campo Bio Assembly violeta abre com um visto verde.','見た目：A–T、C–G、骨格を集めると紫のBio Assemblyフィールドが緑のチェックで開きます。','Aspect : après A–T, C–G et le squelette, le champ Bio Assembly violet s’ouvre avec une coche verte.','外观：收集A–T、C–G和骨架后，紫色Bio Assembly区域会以绿色勾号开启。','Aspetto: dopo A–T, C–G e lo scheletro, il campo Bio Assembly viola si apre con una spunta verde.'),
    enzymeGate:()=>ml('Görünüş: üç biyolojik parça toplanınca camgöbeği Enzim Kapısı yeşil onayla açılır.','Look: after the three biological pieces are collected, the cyan Enzyme Gate opens with a green check.','Aussehen: Nach dem Sammeln der drei Bio-Teile öffnet sich das türkise Enzym-Tor mit grünem Häkchen.','Aspecto: al recoger las tres piezas biológicas, la Puerta Enzimática cian se abre con una marca verde.','Visual: ao coletar as três peças biológicas, o Portal Enzimático ciano abre com um visto verde.','見た目：3つの生体パーツを集めるとシアンの酵素ゲートが緑のチェックで開きます。','Aspect : après les trois éléments biologiques, la Porte Enzymatique cyan s’ouvre avec une coche verte.','外观：收集三个生物要素后，青色酶门会以绿色勾号开启。','Aspetto: raccolti i tre elementi biologici, la Porta Enzimatica ciano si apre con una spunta verde.'),
    classicCatalyst:()=>ml('Görünüş: üç farklı laboratuvar simgesi ve üstte üç sayaç.','Look: three lab symbols and three counters at the top.','Aussehen: drei Laborsymbole und drei Zähler oben.','Aspecto: tres símbolos y tres contadores arriba.','Visual: três símbolos e três contadores no topo.','見た目：3つのラボ記号と上部カウンター。'),
    classicChain:()=>ml('Görünüş: parlayan doğru hamle ve COMBO sayacı.','Look: glowing correct move and COMBO counter.','Aussehen: leuchtender richtiger Zug und COMBO-Zähler.','Aspecto: movimiento brillante y contador COMBO.','Visual: jogada brilhante e contador COMBO.','見た目：光る正解手とCOMBO表示。'),
    classicReactor:()=>ml('Görünüş: yanıp sönen lazer ve Darbe sayacı.','Look: pulsing laser and Impact counter.','Aussehen: pulsierender Laser und Trefferzähler.','Aspecto: láser pulsante y contador de impactos.','Visual: laser pulsante e contador de impactos.','見た目：点滅レーザーと衝突カウンター。')
  };
  return cues[id]?cues[id]():'';
}
function currentLevelMechanicsGuideHtml(){
  const ids=currentLevelMechanicIds();if(!ids.length)return '';
  const cards=ids.map(id=>{const info=MECHANIC_INFO[id];if(!info)return '';const cue=mechanicVisualCue(id);return '<article class="currentMechanicCard"><b>'+info.icon+' '+mechanicTitleLabel(info)+'</b><span>'+t(info.descKey)+'</span>'+(cue?'<em>'+cue+'</em>':'')+'</article>';}).join('');
  return '<section class="guideSection currentLevelMechanics"><h4>🧭 '+ml('BU BÖLÜMDEKİ ÖZEL İŞARETLER','SPECIAL SYMBOLS IN THIS LEVEL','SONDERZEICHEN IN DIESEM LEVEL','SÍMBOLOS ESPECIALES DE ESTE NIVEL','SÍMBOLOS ESPECIAIS DESTA FASE','このレベルの特別な記号')+'</h4><p>'+ml('Tahtada anlamı belirsiz bir şekil görürsen burada yalnızca bu bölümde kullanılan kuralları bulursun.','If a board symbol is unclear, this section lists only the rules used in the current level.','Wenn ein Symbol unklar ist, stehen hier nur die Regeln des aktuellen Levels.','Si un símbolo no está claro, aquí aparecen solo las reglas del nivel actual.','Se um símbolo não estiver claro, aqui aparecem só as regras da fase atual.','記号が分からない時、このレベルで使うルールだけを確認できます。')+'</p><div class="currentMechanicGrid">'+cards+'</div></section>';
}
function allMechanicsGuideHtml(){
  const rows=trainingMechanicCatalog().map(row=>{
    const id=row[0],info=MECHANIC_INFO[id];if(!info)return '';
    const cue=mechanicVisualCue(id);
    return '<button class="currentMechanicCard mxGuideMechanicCard" data-guide-mechanic="'+id+'"><b>'+info.icon+' '+mechanicTitleLabel(info)+'</b><span>'+t(info.descKey)+'</span>'+(cue?'<em>'+cue+'</em>':'')+'<small>▶ '+ml('Etkileşimli Dr. Edward Atom eğitimini aç','Open the interactive Dr. Edward Atom lesson','Interaktive Dr.-Edward-Atom-Lektion öffnen','Abrir la lección interactiva de Dr. Edward Atom','Abrir a lição interativa do Dr. Edward Atom','Dr. Edward Atomのインタラクティブ練習を開く','Ouvrir la leçon interactive du Dr. Edward Atom','打开Dr. Edward Atom互动教学','Apri la lezione interattiva del Dr. Edward Atom')+'</small></button>';
  }).join('');
  return '<section class="guideSection mxAllMechanicsGuide"><h4>🧠 '+ml('TÜM MEKANİKLER · EKSİKSİZ REHBER','ALL MECHANICS · COMPLETE GUIDE','ALLE MECHANIKEN · KOMPLETTER LEITFADEN','TODAS LAS MECÁNICAS · GUÍA COMPLETA','TODAS AS MECÂNICAS · GUIA COMPLETO','全メカニック・完全ガイド','TOUTES LES MÉCANIQUES · GUIDE COMPLET','全部机制 · 完整指南','TUTTE LE MECCANICHE · GUIDA COMPLETA')+'</h4><p>'+ml('Kampanya ve Bonus Laboratuvarındaki her kural aşağıdadır. Bir karta dokunursan Dr. Edward Atom kısa, uygulamalı deneyi açar.','Every campaign and Bonus Lab rule is listed below. Tap a card and Dr. Edward Atom opens his short interactive experiment.','Alle Regeln der Kampagne und des Bonuslabors stehen unten. Tippe auf eine Karte für Dr. Edward Atoms kurzes interaktives Experiment.','Aquí aparecen todas las reglas de campaña y Laboratorio extra. Toca una tarjeta para abrir el experimento interactivo de Dr. Edward Atom.','Todas as regras da campanha e do Laboratório bônus estão abaixo. Toque em um cartão para abrir o experimento interativo do Dr. Edward Atom.','キャンペーンとボーナスラボの全ルールを掲載。カードをタップするとDr. Edward Atomの短い実験を開けます。','Toutes les règles de la campagne et du Laboratoire bonus figurent ci-dessous. Touchez une carte pour lancer la courte expérience interactive du Dr. Edward Atom.','下方列出战役与奖励实验室的所有规则。点击卡片即可打开Dr. Edward Atom互动实验。','Qui trovi tutte le regole della campagna e del Laboratorio bonus. Tocca una scheda per aprire l’esperimento interattivo del Dr. Edward Atom.')+'</p><div class="currentMechanicGrid">'+rows+'</div></section>';
}

function mechanicTutorialDemo(id){
  const tr=LANG==='tr';
  const demos={
    rotatingChamber:{cells:['▦','↻','90°','▦'],action:'TURN 90°',result:ml('Oda, duvarlar ve içindeki atomlarla birlikte döner. Her dokunuş 1 hamledir.','The chamber rotates with its walls and atoms. Every tap costs 1 move.','Die Kammer dreht sich mit Wänden und Atomen. Jeder Tipp kostet 1 Zug.','La cámara gira con paredes y átomos. Cada toque cuesta 1 movimiento.','A câmara gira com paredes e átomos. Cada toque custa 1 jogada.','壁と原子ごと区画が回転し、タップごとに1手です。','La chambre tourne avec ses murs et atomes. Chaque toucher coûte 1 coup.','舱体连同墙和原子一起旋转，每次点击计1步。','La camera ruota con pareti e atomi. Ogni tocco costa 1 mossa.')},
    repulsor:{cells:['H','→','□ ⇱','↱','↑'],action:ml('ALANA GİR','ENTER THE FIELD','FELD BETRETEN','ENTRA EN EL CAMPO','ENTRE NO CAMPO','フィールドへ入る','ENTRER DANS LE CHAMP','进入力场','ENTRA NEL CAMPO'),result:ml('Atom çekirdeğin yanındaki hücreye girince çekirdekten uzağa döner ve yeni yönde duvara kadar kaymayı sürdürür.','When the atom enters a cell beside the Core, it turns directly away from the Core and keeps sliding in the new direction until blocked.','Betritt das Atom ein Feld neben dem Kern, dreht es direkt vom Kern weg und gleitet bis zum nächsten Hindernis weiter.','Al entrar junto al Núcleo, el átomo gira directamente alejándose y sigue deslizándose hasta encontrar un obstáculo.','Ao entrar ao lado do Núcleo, o átomo vira para longe dele e continua deslizando até encontrar um obstáculo.','コアの隣マスへ入ると原子はコアから外向きへ曲がり、障害物まで新しい方向へ滑り続けます。','En entrant à côté du Noyau, l’atome tourne directement vers l’extérieur et continue de glisser jusqu’à un obstacle.','原子进入核心旁边的格子后，会立刻转向远离核心，并沿新方向滑到障碍物为止。','Entrando accanto al Nucleo, l’atomo gira direttamente verso l’esterno e continua a scorrere fino a un ostacolo.')},
    synthesizer:{cells:['A','+','B','→','Σ','→','C'],action:ml('İKİ GİRDİYİ Σ ÜZERİNDEN GEÇİR','FEED BOTH INPUTS THROUGH Σ','BEIDE EINGABEN DURCH Σ','PASA AMBAS ENTRADAS POR Σ','PASSE AS DUAS ENTRADAS POR Σ','2つの入力をΣへ','PASSER LES DEUX ENTRÉES DANS Σ','让两个输入通过Σ','PASSA ENTRAMBI GLI INGRESSI IN Σ'),result:ml('A ve B tamamen tüketilir; C çıkış hücresinde yeni bir element olarak oluşur. Bu Fusion değildir: girişler yeni yapının içinde kalmaz. Replicator da değildir: aynı atom kopyalanmaz.','A and B are fully consumed; C appears as a new element on the output cell. This is not Fusion: the inputs do not remain inside a structure. It is not Replicator either: no identical copy is made.','A und B werden vollständig verbraucht; C erscheint als neues Element am Ausgang. Keine Fusion: Die Eingaben bleiben nicht in einer Struktur. Kein Replikator: Es entsteht keine identische Kopie.','A y B se consumen por completo; C aparece como elemento nuevo en la salida. No es Fusión: las entradas no quedan en una estructura. Tampoco es Replicador: no se crea una copia idéntica.','A e B são consumidos; C surge como elemento novo na saída. Não é Fusão: as entradas não ficam numa estrutura. Nem Replicador: não há cópia idêntica.','AとBは完全に消費され、Cが新元素として出口に現れます。Fusionのように入力が構造内へ残らず、Replicatorのような同一コピーでもありません。','A et B sont entièrement consommés ; C apparaît comme nouvel élément à la sortie. Ce n’est pas une Fusion : les entrées ne restent pas dans une structure. Ni un Réplicateur : aucune copie identique.','A和B被完全消耗，C作为新元素出现在出口。这不是融合：输入不会留在结构中；也不是复制器：不会生成相同副本。','A e B vengono consumati del tutto; C appare come nuovo elemento all’uscita. Non è Fusione: gli ingressi non restano nella struttura. Né Replicatore: nessuna copia identica.')},
    photonBoost:{cells:['H','→','hν','→','H✦','⇢','O','→','H'],action:ml('hν PEDİNDEN GEÇ','CROSS THE hν PAD','ÜBER DAS hν-FELD','CRUZA LA PLATAFORMA hν','PASSE PELO PISO hν','hνパッドを通る','PASSER SUR hν','穿过hν地格','PASSA SUL PAD hν'),result:ml('Atom parlar. Bu yük bir kez başka bir atomun içinden geçmeni sağlar; geçişten sonra söner. Kullanmazsan yük sonraki hamleye kalır.','The atom glows. This charge lets it phase through one other atom once; it disappears after the pass. If unused, the charge stays for the next move.','Das Atom leuchtet. Die Ladung lässt es einmal durch ein anderes Atom gleiten und verschwindet danach. Ungenutzt bleibt sie für den nächsten Zug.','El átomo brilla. La carga le permite atravesar un átomo una vez y desaparece después. Si no se usa, permanece para el siguiente movimiento.','O átomo brilha. A carga permite atravessar um átomo uma vez e some depois. Se não for usada, fica para a próxima jogada.','原子が光ります。このチャージで別の原子を1回だけ通り抜けられ、通過後に消えます。使わなければ次の手まで残ります。','L’atome brille. Cette charge lui permet de traverser un autre atome une fois, puis disparaît. Si elle n’est pas utilisée, elle reste pour le coup suivant.','原子会发光。该能量可让它穿过另一个原子一次，穿过后消失；若未使用，会保留到下一步。','L’atomo brilla. La carica permette di attraversare un altro atomo una volta, poi svanisce. Se non usata, resta per la mossa successiva.')},
    replicator:{cells:['H','→','×2','→','H + H'],action:ml('ATOMU ×2 ÜZERİNDEN KAYDIR','SLIDE THROUGH ×2','DURCH ×2 GLEITEN','DESLIZA POR ×2','DESLIZE POR ×2','×2を通す','GLISSER DANS ×2','滑过×2','SCORRI ATTRAVERSO ×2'),result:ml('Orijinal atom yoluna devam eder; aynı elementten bir kopya işaretli çıkış hücresinde oluşur.','The original keeps sliding; one matching copy appears on the marked output cell.','Das Original gleitet weiter; eine identische Kopie erscheint am markierten Ausgang.','El original sigue deslizándose; una copia idéntica aparece en la salida marcada.','O original continua deslizando; uma cópia idêntica aparece na saída marcada.','元の原子は滑り続け、同じ原子のコピーが出口マスに現れます。','L’original continue de glisser ; une copie identique apparaît à la sortie marquée.','原原子继续滑动，一个相同副本会出现在标记出口。','L’originale continua a scorrere; una copia identica compare all’uscita segnata.')},
    frozen:{cells:['H','→','❄️ H'],action:ml("DİĞER ATOMU KAYDIR","SLIDE THE OTHER ATOM","ANDERES ATOM SCHIEBEN","DESLIZA EL OTRO ÁTOMO","DESLIZE O OUTRO ÁTOMO","もう一方の原子を動かす"),result:ml("Donmuş atom yerinde kalır; molekül onun çevresinde kurulur.","The frozen atom stays put; build the molecule around it.","Das gefrorene Atom bleibt stehen; baue das Molekül darum herum.","El átomo congelado permanece fijo; construye la molécula a su alrededor.","O átomo congelado fica parado; monte a molécula ao redor dele.","凍結原子は動きません。その周囲に分子を組み立てます。")},
    fire:{cells:['🔥 H','→','❄️ H'],action:ml("ATEŞİ BUZA YAKLAŞTIR","MOVE FIRE TO THE ICE","FEUER ZUM EIS BEWEGEN","MUEVE EL FUEGO AL HIELO","MOVA O FOGO ATÉ O GELO","炎を氷へ近づける"),result:ml("Ateş temas edince buz erir ve atom serbest kalır.","Contact with fire melts the ice and frees the atom.","Feuerkontakt schmilzt das Eis und befreit das Atom.","El contacto con fuego derrite el hielo y libera el átomo.","O contato com fogo derrete o gelo e libera o átomo.","炎に触れると氷が溶け、原子が自由になります。")},
    lightning:{cells:['⚡ atom','→','H—❄️ H'],action:ml("ZİNCİRE TEMAS ET","TOUCH THE CHAIN","KETTE BERÜHREN","TOCA LA CADENA","TOQUE NA CADEIA","連鎖に触れる"),result:ml("⚡ işareti elektrik yükünü gösterir. Enerji bağlı grup boyunca ilerleyip buzu çözer.","The ⚡ symbol marks electric charge. Energy travels through the connected group and thaws the ice.","Das ⚡-Symbol zeigt elektrische Ladung. Energie läuft durch die verbundene Gruppe und taut das Eis.","El símbolo ⚡ indica carga eléctrica. La energía recorre el grupo conectado y descongela el hielo.","O símbolo ⚡ indica carga elétrica. A energia percorre o grupo conectado e descongela o gelo.","⚡は電荷を示します。エネルギーが連結グループを伝わって氷を溶かします。")},
    sticky:{cells:['H','→','🧲 H'],action:ml("TEMASI DENE","TRY THE CONTACT","KONTAKT TESTEN","PRUEBA EL CONTACTO","TESTE O CONTATO","接触を試す"),result:ml("Temas eden atom o noktada yapışır; geri ayrılamaz.","The touching atom sticks at that point and cannot separate.","Das berührende Atom klebt dort fest und kann sich nicht mehr lösen.","El átomo que toca queda pegado y no puede separarse.","O átomo que toca fica preso e não pode se separar.","接触した原子はその場でくっつき、離れられません。")},
    zombie:{cells:['H','→','◎ H'],action:ml("TEMASI DENE","TRY THE CONTACT","KONTAKT TESTEN","PRUEBA EL CONTACTO","TESTE O CONTATO","接触を試す"),result:ml("Temas kararsızlığı aktarır. Isı veya elektrik yükü atomu stabilize eder.","Contact transfers instability. Heat or electrical charge stabilizes the atom.","Kontakt überträgt Instabilität. Wärme oder elektrische Ladung stabilisiert das Atom.","El contacto transfiere inestabilidad. El calor o la carga eléctrica estabilizan el átomo.","O contato transfere instabilidade. Calor ou carga elétrica estabilizam o átomo.","接触で不安定性が伝わり、熱または電荷で安定化できます。")},
    oneWay:{cells:['H','→','↪️','→'],action:ml("OK YÖNÜNDE GEÇ","FOLLOW THE ARROW","PFEILRICHTUNG FOLGEN","SIGUE LA FLECHA","SIGA A SETA","矢印に従う"),result:ml("Ok yönünde geçebilirsin; ters yönden geri dönemezsin.","You may pass with the arrow, but cannot return against it.","Du kannst in Pfeilrichtung passieren, aber nicht dagegen zurück.","Puedes pasar en la dirección de la flecha, pero no volver en contra.","Você pode passar na direção da seta, mas não voltar contra ela.","矢印方向には通れますが、逆方向には戻れません。")},
    hammer:{cells:['H','🧱','H'],action:ml("ÇEKİCİ KULLAN","USE THE HAMMER","HAMMER BENUTZEN","USA EL MARTILLO","USE O MARTELO","ハンマーを使う"),result:ml("Alt araç çubuğundaki çekici seç, sonra çatlak duvara dokun.","Select the hammer in the bottom toolbar, then tap the cracked wall.","Wähle den Hammer unten und tippe dann auf die rissige Wand.","Selecciona el martillo abajo y toca la pared agrietada.","Selecione o martelo na barra inferior e toque na parede rachada.","下のツールバーでハンマーを選び、ひび割れ壁をタップします。")},
    rift:{cells:['H','→','🕳️ ◆','⇢','🕳️ ◇','→'],action:ml('RIFT ÜZERİNDEN GEÇ','CROSS THE RIFT','RIFT ÜBERQUEREN','CRUZA LA FISURA','ATRAVESSE A FENDA','リフトを通過','TRAVERSER LA FAILLE','穿过裂隙','ATTRAVERSA IL RIFT'),result:ml('Atom Rift karosuna basıp durmaz; geçerken eş Rift’e sıçrar ve aynı yönde kaymayı sürdürür.','The atom does not need to stop on the Rift; crossing it warps to the twin Rift and continues in the same direction.','Das Atom muss nicht auf dem Rift stoppen; beim Überqueren springt es zum Zwilling und gleitet in derselben Richtung weiter.','El átomo no tiene que detenerse; al cruzar salta a la fisura gemela y sigue en la misma dirección.','O átomo não precisa parar; ao atravessar salta para a fenda gêmea e segue na mesma direção.','停止する必要はありません。通過時に対のリフトへワープし、同じ方向へ滑り続けます。','L’atome n’a pas besoin de s’arrêter ; en traversant, il saute vers la faille jumelle et continue dans la même direction.','原子无需停在裂隙上；经过时会跳到另一端并沿相同方向继续滑动。','L’atomo non deve fermarsi; attraversando salta al Rift gemello e continua nella stessa direzione.')},
    portal:{cells:['H','→','🌀 A','…','🌀 B'],action:ml("PORTALA GİR","ENTER THE PORTAL","PORTAL BETRETEN","ENTRA EN EL PORTAL","ENTRE NO PORTAL","ポータルに入る"),result:ml("Atom A portalından girip eşleşen B portalından çıkar.","The atom enters portal A and exits its linked portal B.","Das Atom betritt Portal A und verlässt das verbundene Portal B.","El átomo entra por el portal A y sale por el portal B enlazado.","O átomo entra pelo portal A e sai pelo portal B conectado.","原子はポータルAに入り、対応するポータルBから出ます。")},
    movingWall:{cells:['H','→','🚧','⇄'],action:ml("BİR HAMLE YAP","MAKE A MOVE","ZUG MACHEN","HAZ UN MOVIMIENTO","FAÇA UM MOVIMENTO","1手動かす"),result:ml("Duvar her hamlede desenindeki sonraki konuma geçer.","The wall advances to its next patterned position after a move.","Die Wand wechselt nach einem Zug zur nächsten Position ihres Musters.","La pared avanza a la siguiente posición de su patrón tras un movimiento.","A parede avança para a próxima posição do padrão após um movimento.","壁は1手ごとにパターン上の次の位置へ移動します。")},
    pressureDoor:{cells:['H','→','🔘 A','⇢','▥ A'],action:ml("DÜĞMEYE BAS","PRESS THE BUTTON","SCHALTER DRÜCKEN","PULSA EL BOTÓN","PRESSIONE O BOTÃO","スイッチを押す"),result:ml("Aynı harfli çizgili kutu açık kapıdır. Atom A düğmesinden ayrılınca yeniden katı duvar olur.","The striped square with the same letter is the open door. It becomes a solid wall when the atom leaves switch A.","Das gestreifte Feld mit demselben Buchstaben ist die offene Tür. Verlässt das Atom Schalter A, wird sie wieder zur festen Wand.","La casilla rayada con la misma letra es la puerta abierta. Cuando el átomo deja el interruptor A, vuelve a ser pared sólida.","A casa listrada com a mesma letra é a porta aberta. Quando o átomo sai do botão A, ela volta a ser parede sólida.","同じ文字の縞模様マスが開いたドアです。原子がスイッチAを離れると再び壁になります。")},
    fragile:{cells:['💎 H','→','H'],action:ml("DİKKATLİ KAYDIR","SLIDE CAREFULLY","VORSICHTIG SCHIEBEN","DESLIZA CON CUIDADO","DESLIZE COM CUIDADO","慎重に動かす"),result:ml("Kırılgan atom fazla darbe alırsa parçalanır; kısa ve temiz rota kur.","Too many impacts shatter it; use a short, clean route.","Zu viele Stöße zerstören es; nutze eine kurze, saubere Route.","Demasiados impactos lo rompen; usa una ruta corta y limpia.","Impactos demais o quebram; use uma rota curta e limpa.","衝突が多すぎると壊れます。短く安全なルートを使いましょう。")},
    linked:{cells:['🔗 H','+','🔗 H','→'],action:ml("İKİSİNİ BİRLİKTE KAYDIR","SLIDE BOTH TOGETHER","BEIDE ZUSAMMEN SCHIEBEN","DESLIZA AMBOS JUNTOS","DESLIZE OS DOIS JUNTOS","2つ同時に動かす"),result:ml("Birini hareket ettirince eşi de aynı yönde gider. İkisinin yolu açık olmalı.","Moving either one sends its mate in the same direction. Both paths must be clear.","Bewegst du eines, bewegt sich sein Partner in dieselbe Richtung. Beide Wege müssen frei sein.","Mover uno envía a su pareja en la misma dirección. Ambos caminos deben estar libres.","Mover um faz o parceiro ir na mesma direção. Os dois caminhos devem estar livres.","片方を動かすと相方も同じ方向へ動きます。両方の道が空いている必要があります。")},
    prebuilt:{cells:['H—C','🧩','+','I','→','✅'],action:ml('HAZIR MODÜLE EKLE','ADD TO THE READY MODULE','ZUM FERTIGEN MODUL HINZUFÜGEN','AÑADE AL MÓDULO LISTO','ADICIONE AO MÓDULO PRONTO','完成済みモジュールに追加','AJOUTER AU MODULE PRÊT','加入现成模块','AGGIUNGI AL MODULO PRONTO'),result:ml('Vurgulanan parça en baştan rijittir. Onu tek parça taşı ve kalan atomları çevresine yerleştir.','The highlighted fragment is rigid from the start. Move it as one piece and place the remaining atoms around it.','Das markierte Fragment ist von Beginn an starr. Bewege es als Einheit und ergänze die übrigen Atome.','El fragmento resaltado es rígido desde el inicio. Muévelo como una sola pieza y coloca los átomos restantes.','O fragmento destacado é rígido desde o início. Mova-o como uma peça e coloque os átomos restantes ao redor.','強調された断片は最初から剛体です。一体のまま動かし、残りの原子を周囲に配置します。','Le fragment surligné est rigide dès le départ. Déplacez-le d’un bloc et placez les autres atomes autour.','高亮片段从一开始就是刚性整体。整体移动它，再把剩余原子放到周围。','Il frammento evidenziato è rigido fin dall’inizio. Spostalo come un unico pezzo e sistema gli altri atomi attorno.')},
    rotation:{cells:['F—C—F','→','🔄 90°','→','F\nC\nF'],action:ml("PLATFORMDA DUR","STOP ON THE PAD","AUF DEM FELD STOPPEN","DETENTE EN LA PLATAFORMA","PARE NA PLATAFORMA","パッド上で停止","ARRÊTER SUR LA PLATEFORME","停在平台上","FERMATI SULLA PIATTAFORMA"),result:ml("Rijit Fusion grubu platformdaki atomun çevresinde 90° döner.","The rigid Fusion group rotates 90° around the atom on the pad.","Die starre Fusion-Gruppe dreht sich um 90° um das Atom auf dem Feld.","El grupo rígido de Fusión gira 90° alrededor del átomo de la plataforma.","O grupo rígido de Fusão gira 90° ao redor do átomo na plataforma.","剛体フュージョングループがパッド上の原子を中心に90°回転します。","Le groupe rigide de Fusion pivote de 90° autour de l’atome sur la plateforme.","刚性融合组会以平台上的原子为轴旋转90°。","Il gruppo rigido di Fusione ruota di 90° attorno all’atomo sulla piattaforma.")},
    fusion:{cells:['H—O','🧬','→','O—H','✅'],action:ml("ALT YAPILARI TAMAMLA","COMPLETE THE SUB-STRUCTURES","TEILSTRUKTUREN VERVOLLSTÄNDIGEN","COMPLETA LAS SUBESTRUCTURAS","COMPLETE AS SUBESTRUTURAS","部分構造を完成","COMPLÉTER LES SOUS-STRUCTURES","完成子结构","COMPLETA LE SOTTOSTRUTTURE"),result:ml("Geçerli alt yapı oluşunca rijit bir grup olur ve birlikte kayar. Son molekülü tahtanın istediğin yerinde tamamlayabilirsin.","Once a valid sub-structure forms, it becomes a rigid group and slides together. You may complete the final molecule anywhere on the board.","Sobald eine gültige Teilstruktur entsteht, wird sie zu einer starren Gruppe und gleitet gemeinsam. Das Endmolekül kann überall auf dem Brett entstehen.","Cuando se forma una subestructura válida, se convierte en un grupo rígido y se desliza unido. Puedes completar la molécula final en cualquier lugar del tablero.","Quando uma subestrutura válida se forma, ela vira um grupo rígido e desliza junto. Você pode completar a molécula final em qualquer lugar do tabuleiro.","有効な部分構造ができると剛体グループになり、一緒に滑ります。最終分子は盤面のどこで完成しても構いません。","Une sous-structure valide devient un groupe rigide qui glisse ensemble. La molécule finale peut être complétée n’importe où sur le plateau.","有效子结构形成后会成为刚性整体并一起滑动。最终分子可以在棋盘任意位置完成。","Quando si forma una sottostruttura valida, diventa un gruppo rigido e scorre insieme. Puoi completare la molecola finale in qualsiasi punto della tavola.")},
    enzymeGate:{cells:[labComponentTrainingToken('substrate'),labComponentTrainingToken('cofactor'),labComponentTrainingToken('atp'),'→','✓'],action:ml('ÜÇ BİYO PARÇAYI TOPLA','COLLECT ALL THREE BIO PARTS','ALLE DREI BIO-TEILE SAMMELN','RECOGE LAS TRES PIEZAS BIO','COLETE AS TRÊS PEÇAS BIO','3つの生体パーツを集める','COLLECTER LES TROIS ÉLÉMENTS BIO','收集三个生物要素','RACCOGLI I TRE ELEMENTI BIO'),result:ml('Substrat, kofaktör ve ATP tamamlanınca Enzim Kapısı açılır; sonra gerçek molekülü tamamla.','The Enzyme Gate opens after the substrate, cofactor and ATP are collected; then complete the real molecule.','Nach Substrat, Cofaktor und ATP öffnet sich das Enzym-Tor; vervollständige dann das echte Molekül.','La Puerta Enzimática se abre al reunir sustrato, cofactor y ATP; después completa la molécula real.','O Portal Enzimático abre após coletar substrato, cofator e ATP; então complete a molécula real.','基質、補因子、ATPを集めると酵素ゲートが開き、その後に実在分子を完成させます。','La Porte Enzymatique s’ouvre après le substrat, le cofacteur et l’ATP ; termine ensuite la vraie molécule.','收集底物、辅因子和ATP后酶门开启；然后完成真实分子。','La Porta Enzimatica si apre dopo substrato, cofattore e ATP; poi completa la molecola reale.')},
    bioAssembly:{cells:[labComponentTrainingToken('atPair'),labComponentTrainingToken('cgPair'),labComponentTrainingToken('backbone'),'→','✓'],action:ml('DNA PARÇALARINI TOPLA','COLLECT THE DNA PARTS','DNA-TEILE SAMMELN','RECOGE LAS PIEZAS DE ADN','COLETE AS PEÇAS DE DNA','DNAパーツを集める','COLLECTER LES ÉLÉMENTS ADN','收集DNA组件','RACCOGLI LE PARTI DEL DNA'),result:ml('A–T, C–G ve şeker–fosfat omurgası tamamlanınca Bio Assembly açılır; ardından hedef molekülü bitir.','Bio Assembly opens after A–T, C–G and the sugar–phosphate backbone are collected; then finish the target molecule.','Nach A–T, C–G und Zucker-Phosphat-Rückgrat öffnet sich Bio Assembly; vollende dann das Zielmolekül.','Bio Assembly se abre al reunir A–T, C–G y el esqueleto azúcar–fosfato; después completa la molécula objetivo.','Bio Assembly abre após coletar A–T, C–G e a espinha dorsal açúcar–fosfato; depois conclua a molécula-alvo.','A–T、C–G、糖–リン酸骨格を集めるとBio Assemblyが開き、続いて目標分子を完成させます。','Bio Assembly s’ouvre après A–T, C–G et le squelette sucre-phosphate ; termine ensuite la molécule cible.','收集A–T、C–G和糖磷酸骨架后，Bio Assembly开启；然后完成目标分子。','Bio Assembly si apre dopo A–T, C–G e lo scheletro zucchero–fosfato; poi completa la molecola obiettivo.')},
    precision:{cells:['H','🎯','→','1 □'],action:ml("1 KARE TAŞI","MOVE 1 SQUARE","1 FELD BEWEGEN","MOVER 1 CASILLA","MOVER 1 CASA","1マス動かす","DÉPLACER D’UNE CASE","移动一格","SPOSTA DI UNA CASELLA"),result:ml("Bu isteğe bağlı araç atomu tam bir kare taşır. Yalnızca onaylanan kullanımda 250 MoleCoin harcanır.","This optional tool moves an atom exactly one tile. A confirmed use costs 250 MoleCoin.","Dieses optionale Werkzeug bewegt ein Atom genau ein Feld. Eine bestätigte Nutzung kostet 250 MoleCoin.","Esta herramienta opcional mueve un átomo exactamente una casilla. Un uso confirmado cuesta 250 MoleCoin.","Esta ferramenta opcional move um átomo exatamente uma casa. Um uso confirmado custa 250 MoleCoin.","この任意ツールは原子をちょうど1マス動かします。確定した使用には250 MoleCoinが必要です。","Cet outil facultatif déplace un atome exactement d’une case. Une utilisation confirmée coûte 250 MoleCoin.","此可选工具可让原子精确移动一格。确认使用时需花费250 MoleCoin。","Questo strumento facoltativo sposta un atomo esattamente di una casella. Un utilizzo confermato costa 250 MoleCoin.")},
    classicCatalyst:{cells:[labComponentTrainingToken('catalyst'),labComponentTrainingToken('energy'),labComponentTrainingToken('stabilizer'),'→','⚛️'],action:ml("ÜÇÜNÜ TOPLA","COLLECT ALL THREE","ALLE DREI SAMMELN","RECOGE LOS TRES","COLETE OS TRÊS","3つすべて集める"),result:ml("Önce üç laboratuvar bileşenini topla, sonra molekülü tamamla.","Collect all three lab components first, then complete the molecule.","Sammle zuerst alle drei Laborkomponenten und vervollständige dann das Molekül.","Recoge primero los tres componentes del laboratorio y luego completa la molécula.","Colete primeiro os três componentes do laboratório e depois complete a molécula.","先にラボ要素3つをすべて集め、その後分子を完成させます。")},
    classicChain:{cells:['✨','→','⚡','→','⚡'],action:ml("PARLAYAN HAMLEYİ YAP","MAKE THE GLOWING MOVE","LEUCHTENDEN ZUG MACHEN","HAZ EL MOVIMIENTO BRILLANTE","FAÇA O MOVIMENTO BRILHANTE","光る手を実行"),result:ml("Doğru hamle otomatik zincir reaksiyonunu başlatır.","The correct move starts the automatic chain reaction.","Der richtige Zug startet die automatische Kettenreaktion.","El movimiento correcto inicia la reacción en cadena automática.","O movimento correto inicia a reação em cadeia automática.","正しい手で自動連鎖反応が始まります。")},
    classicReactor:{cells:['H','☢️','▥','→'],action:ml("GÜVENLİ ANI BEKLE","WAIT FOR THE SAFE PHASE","SICHERE PHASE ABWARTEN","ESPERA LA FASE SEGURA","ESPERE A FASE SEGURA","安全なタイミングを待つ"),result:ml("Aktif lazere temas 1 hamle sayılır ve Darbe sayacını artırır. Reaktör Kaçışında ayrıca +3 saniye ceza verir.","Contact with an active laser counts as one move and increases the Impact counter. Reactor Escape also adds a 3-second penalty.","Kontakt mit einem aktiven Laser zählt als ein Zug und erhöht den Trefferzähler. Reaktor-Flucht gibt zusätzlich 3 Sekunden Strafe.","Tocar un láser activo cuenta como un movimiento y aumenta el contador de impactos. Escape del Reactor añade además 3 segundos.","Tocar um laser ativo conta como uma jogada e aumenta o contador de impactos. Fuga do Reator também adiciona 3 segundos.","作動中レーザーへの接触は1手として数えられ、衝突カウンターも増えます。リアクター脱出ではさらに3秒ペナルティ。")}
  };
  const demo=demos[id]||{cells:['⚛️','→','✅'],action:ml("DENE","TRY IT","AUSPROBIEREN","PRUÉBALO","TENTE","試す"),result:ml("Mekaniği gözlemle ve ardından gerçek bölüme geç.","Observe the mechanic, then continue to the real level.","Beobachte die Mechanik und fahre dann mit dem echten Level fort.","Observa la mecánica y luego continúa al nivel real.","Observe a mecânica e depois continue para a fase real.","メカニックを確認してから実際のレベルへ進みます。")};
  // The bespoke mini-animation remains the same, but non-TR/EN players now
  // receive localized action/result text instead of an English fallback.
  if(LANG!=='tr'&&LANG!=='en'){
    demo.action=ml('ÖRNEĞİ DENE','TRY THE EXAMPLE','BEISPIEL TESTEN','PROBAR EJEMPLO','TESTAR EXEMPLO','例を試す');
    demo.result=MECHANIC_INFO[id]?t(MECHANIC_INFO[id].descKey):ml('Mekaniği gözlemle ve gerçek bölüme geç.','Observe the mechanic, then continue to the real level.','Beobachte die Mechanik und fahre mit dem echten Level fort.','Observa la mecánica y continúa al nivel real.','Observe a mecânica e continue para a fase real.','仕組みを確認して実際のレベルへ進みます。');
  }
  return demo;
}
function riftTutorialSeen(){try{return localStorage.getItem('moleculox_qa_seen_rift_portal_v1_r131')==='1';}catch(_){return false;}}
function markMechanicTutorialSeen(id){
  if(id==='rift'){try{localStorage.setItem('moleculox_qa_seen_rift_portal_v1_r131','1');}catch(_){}}
  const flags={rotatingChamber:'seenRotatingChamber',repulsor:'seenRepulsor',synthesizer:'seenSynthesizer',photonBoost:'seenPhotonBoost',replicator:'seenReplicator',frozen:'seenFrozen',fire:'seenFire',lightning:'seenLightning',sticky:'seenSticky',zombie:'seenZombie',oneWay:'seenOneWay',hammer:'seenBreakableWall',portal:'seenPortal',rift:'seenRift',movingWall:'seenMovingWall',pressureDoor:'seenPressureDoor',fragile:'seenFragile',linked:'seenLinked',fusion:'seenFusion',prebuilt:'seenPrebuiltModule',rotation:'seenRotation',precision:'seenPrecisionTutorialV2',enzymeGate:'seenEnzymeGate',bioAssembly:'seenBioAssembly',classicCatalyst:'seenClassicCatalystTutorialV2',classicChain:'seenClassicChainTutorialV2',classicReactor:'seenClassicReactorTutorialV2'};
  const flag=flags[id];if(flag)save[flag]=true;
  if(id==='precision')save.seenPrecision=true;
  if(id==='fragile'){save.seenFragileAtom=true;}if(id==='bioAssembly'){save.seenBioAssembly=true;}
  if(id==='linked'){save.seenLinkedAtoms=true;}
  if(id==='hammer'){save.seenHammerWall=true;}
  persist();
}
function showMechanicBriefing(ids,opts){

  ids=(ids||[]).filter(id=>MECHANIC_INFO[id]);
  if(!ids.length)return;
  let page=0,demonstrated=false;
  function render(){
    const id=ids[page],info=MECHANIC_INFO[id],demo=mechanicTutorialDemo(id),last=page===ids.length-1;
    const cells=demo.cells.map((v,n)=>'<span class="'+(String(v).includes('mxTrainingToken')?'mxTrainingCell':'')+'" style="min-width:42px;height:42px;padding:0 8px;border-radius:11px;display:flex;align-items:center;justify-content:center;background:rgba(255,255,255,.075);border:1px solid rgba(255,255,255,.14);font-weight:900;transition:.28s;" data-tutorial-cell="'+n+'">'+v+'</span>').join('');
    const drGuide=ml('Parlayan deney düğmesine dokun. Hareketi adım adım göstereceğim.','Tap the glowing experiment button. I will show the action step by step.','Tippe auf die leuchtende Experiment-Schaltfläche. Ich zeige den Ablauf Schritt für Schritt.','Toca el botón brillante del experimento. Te mostraré la acción paso a paso.','Toque no botão brilhante do experimento. Vou mostrar a ação passo a passo.','光る実験ボタンをタップしてください。手順を順番に示します。');
    openModal('<div style="font-size:.72rem;font-weight:900;letter-spacing:.12em;color:#78e7ff;margin-bottom:5px">'+ml('EĞİTİM DENEYİ','TRAINING EXPERIMENT','TRAININGSEXPERIMENT','EXPERIMENTO DE PRÁCTICA','EXPERIMENTO DE TREINO','練習実験')+' · '+(page+1)+'/'+ids.length+'</div><h3>'+info.icon+' '+mechanicTitleLabel(info)+'</h3><div class="msub">'+t(info.descKey)+'</div><div class="mxMechanicVisualCue">'+mechanicVisualCue(id)+'</div>'+(page===0?mechanicContextNote(opts):'')+drETrainingCard(drGuide,'1/2')+'<div id="mechanicMiniLab" style="margin:15px 0 10px;padding:15px 10px;border-radius:18px;background:linear-gradient(145deg,rgba(20,49,76,.9),rgba(34,20,63,.92));border:1px solid rgba(120,231,255,.28);"><div style="display:flex;gap:7px;align-items:center;justify-content:center;flex-wrap:wrap">'+cells+'</div><div id="mechanicDemoResult" style="min-height:42px;margin-top:12px;font-size:.82rem;line-height:1.35;color:#dcecff">'+ml('Aşağıdaki düğmeye bas ve örneği çalıştır.','Press the button below to run the example.','Drücke die Schaltfläche unten, um das Beispiel auszuführen.','Pulsa el botón de abajo para ejecutar el ejemplo.','Pressione o botão abaixo para executar o exemplo.','下のボタンを押して例を実行してください。')+'</div></div><div class="mrow"><button class="btn amber mxGuidedTarget" id="mMechanicTry">▶ '+demo.action+'</button><button class="btn green" id="mMechanicNext" disabled>'+(last?ml('GERÇEK BÖLÜME GEÇ ▶','START REAL LEVEL ▶','ECHTES LEVEL STARTEN ▶','INICIAR NIVEL REAL ▶','INICIAR FASE REAL ▶','実際のレベルへ ▶'):ml('SONRAKİ EĞİTİM ▶','NEXT TRAINING ▶','NÄCHSTES TRAINING ▶','SIGUIENTE PRÁCTICA ▶','PRÓXIMO TREINO ▶','次の練習 ▶'))+'</button></div>');
    bindTap('#mMechanicTry',()=>{
      if(demonstrated)return;demonstrated=true;SFX.select();mxHaptic('light');
      const lab=$('#mechanicMiniLab'),result=$('#mechanicDemoResult'),tryBtn=$('#mMechanicTry'),next=$('#mMechanicNext');
      if(lab){lab.style.boxShadow='0 0 26px rgba(120,231,255,.24)';const cs=lab.querySelectorAll('[data-tutorial-cell]');cs.forEach((c,n)=>setTimeout(()=>{c.style.transform='translateY(-5px) scale(1.06)';c.style.borderColor='rgba(255,211,110,.8)';setTimeout(()=>{c.style.transform='';},320);},n*180));}
      setTimeout(()=>{if(result)result.innerHTML='✅ '+demo.result;if(tryBtn){tryBtn.classList.remove('mxGuidedTarget');tryBtn.disabled=true;tryBtn.textContent='✓ '+ml('DENEY TAMAM','EXPERIMENT COMPLETE','EXPERIMENT ABGESCHLOSSEN','EXPERIMENTO COMPLETADO','EXPERIMENTO CONCLUÍDO','実験完了');}if(next){next.disabled=false;next.classList.add('mxGuidedTarget');}setDrETraining(ml('Mükemmel. Sonucu gördün; devam etmek için parlayan düğmeye dokun.','Excellent. You saw the result; tap the glowing button to continue.','Ausgezeichnet. Du hast das Ergebnis gesehen; tippe zum Fortfahren auf die leuchtende Schaltfläche.','Excelente. Ya viste el resultado; toca el botón brillante para continuar.','Excelente. Você viu o resultado; toque no botão brilhante para continuar.','結果を確認できました。光るボタンをタップして続けてください。'),'2/2','👉');SFX.thunk();mxHaptic('success');},Math.max(650,demo.cells.length*180+220));
    });
    bindTap('#mMechanicNext',()=>{if(!demonstrated)return;const learnedId=ids[page],learnedInfo=MECHANIC_INFO[learnedId];markMechanicTutorialSeen(learnedId);markTrainingLearned('mechanic',learnedId,t(learnedInfo.titleKey),true);SFX.play();if(page<ids.length-1){page++;demonstrated=false;render();return;}
      const finish=()=>{closeModal();prop('🎓 '+ml('Mekanik öğrenildi','Mechanic learned','Mechanik gelernt','Mecánica aprendida','Mecânica aprendida','仕組みを習得'),2200);const frame=$('#boardFrame');if(frame){frame.classList.add('mxTutorialBoardPulse');setTimeout(()=>frame.classList.remove('mxTutorialBoardPulse'),5000);}if(ids.includes('hammer')){save.seenHammerSupport=true;const b=$('#btnHammer');if(b){b.classList.add('mxTutorialPulse');setTimeout(()=>b.classList.remove('mxTutorialPulse'),7000);}}if(ids.includes('precision')){save.seenPrecisionSupport=true;const b=$('#btnPrecision');if(b){b.classList.add('mxTutorialPulse');setTimeout(()=>b.classList.remove('mxTutorialPulse'),7000);}}persist();finishMechanicContext(opts);if(!(opts&&typeof opts.afterClose==='function'))setTimeout(()=>say(ml('Eğitim tamamlandı. Şimdi aynı kuralı gerçek bölümde kullan!','Training complete. Now use the same rule in the real level!','Training abgeschlossen. Nutze dieselbe Regel jetzt im echten Level!','Práctica completada. ¡Usa ahora la misma regla en el nivel real!','Treino concluído. Agora use a mesma regra na fase real!','練習完了。同じルールを実際のレベルで使ってみましょう！'),'happy',4200,'glow'),220);};
      openModal('<h3>✅ '+ml('Mekanik öğrenildi!','Mechanic learned!','Mechanik gelernt!','¡Mecánica aprendida!','Mecânica aprendida!','仕組みを習得しました！')+'</h3><div class="msub">'+ml('Bu eğitim artık otomatik olarak tekrar gösterilmeyecek. Eğitim Merkezi veya Moleculopedia’dan yeniden açabilirsin.','This lesson will not appear automatically again. You can replay it from the Training Center or Moleculopedia.','Diese Lektion wird nicht erneut automatisch angezeigt. Du kannst sie im Trainingszentrum oder in der Moleculopedia wiederholen.','Esta lección no volverá a aparecer automáticamente. Puedes repetirla desde el Centro de práctica o Moleculopedia.','Esta lição não aparecerá novamente de forma automática. Você pode repeti-la no Centro de Treino ou na Moleculopedia.','このレッスンは自動では再表示されません。トレーニングセンターまたはMoleculopediaから再実行できます。')+'</div><div class="mrow"><button class="btn ghost" id="mMechanicRepeat">↻ '+ml('TEKRAR DENE','TRY AGAIN','NOCH EINMAL','REPETIR','TENTAR NOVAMENTE','もう一度')+'</button><button class="btn green mxGuidedTarget" id="mMechanicContinue">'+ml('GERÇEK BÖLÜME GEÇ ▶','START REAL LEVEL ▶','ECHTES LEVEL STARTEN ▶','INICIAR NIVEL REAL ▶','INICIAR FASE REAL ▶','実際のレベルへ ▶')+'</button></div>');
      bindTap('#mMechanicRepeat',()=>showMechanicBriefing(ids,opts));
      bindTap('#mMechanicContinue',finish);
    });
  }
  render();
}
function mechanicsGuideModal(){
  const tr=LANG==='tr';
  const rows=trainingMechanicCatalog().map(row=>{
    const id=row[0],flag=row[1],info=MECHANIC_INFO[id];
    if(!info||!save[flag])return null;
    const fullTitle=t(info.titleKey),title=String(fullTitle).replace(/^\S+\s/,'').trim()||fullTitle;
    return [id,info.icon,title,t(info.descKey),flag];
  }).filter(Boolean);
  const comboRow=level42ComboSeen()?'<button class="mechanicGuideRow" id="mReplayLevel42Combo" style="width:100%;text-align:left;cursor:pointer"><div class="mechanicGuideIcon">🧪</div><div style="flex:1"><b>'+ml('Bölüm 42 · Donmuş Kararsız Atom + Ateş','Level 42 · Frozen Unstable Atom + Fire','Level 42 · Gefrorenes instabiles Atom + Feuer','Nivel 42 · Átomo inestable congelado + Fuego','Fase 42 · Átomo instável congelado + Fogo','レベル42・凍結不安定原子＋炎','Niveau 42 · Atome instable gelé + Feu','第42关 · 冻结不稳定原子 + 火焰','Livello 42 · Atomo instabile congelato + Fuoco')+'</b><small>'+ml('NF₃ deneyindeki üç işaretin birlikte nasıl çalıştığını yeniden izle.','Replay how the three symbols work together in the NF₃ experiment.','Sieh erneut, wie die drei Symbole im NF₃-Experiment zusammenwirken.','Repite cómo funcionan juntos los tres símbolos en el experimento NF₃.','Reveja como os três símbolos funcionam juntos no experimento NF₃.','NF₃実験で3つの印が連動する仕組みを再確認します。','Revois comment les trois symboles fonctionnent ensemble dans l’expérience NF₃.','重看NF₃实验中三个符号如何协同作用。','Rivedi come i tre simboli funzionano insieme nell’esperimento NF₃.')+'</small><small style="color:#78e7ff;margin-top:4px">▶ '+ml('Birleşik eğitimi yeniden çalıştır','Replay combined training','Kombiniertes Training wiederholen','Repetir entrenamiento combinado','Repetir treino combinado','複合練習を再実行','Relancer l’entraînement combiné','重新进行综合训练','Ripeti l’addestramento combinato')+'</small></div></button>':'';
  const standardRows=rows.length?rows.map(r=>'<button class="mechanicGuideRow" data-mechanic-replay="'+r[0]+'" style="width:100%;text-align:left;cursor:pointer"><div class="mechanicGuideIcon">'+r[1]+'</div><div style="flex:1"><b>'+r[2]+'</b><small>'+r[3]+'</small><small style="color:#78e7ff;margin-top:4px">▶ '+ml('Eğitimi yeniden çalıştır','Replay training','Training wiederholen','Repetir práctica','Repetir treino','練習を再実行')+'</small></div></button>').join(''):'';
  const html=(comboRow||standardRows)?comboRow+standardRows:'<div class="mechanicGuideRow"><small>'+ml('Henüz açılan bir mekanik yok — ilerledikçe burada birikecek.','Nothing unlocked yet — this fills in as you progress.','Noch keine Mechanik freigeschaltet – die Liste wächst mit deinem Fortschritt.','Aún no hay mecánicas desbloqueadas; aparecerán al avanzar.','Ainda não há mecânicas desbloqueadas; elas aparecerão com o progresso.','まだ仕組みは解放されていません。進行すると追加されます。')+'</small></div>';
  openModal('<h3>🎓 '+ml('Eğitim Merkezi · Mekanikler','Training Center · Mechanics','Trainingszentrum · Mechaniken','Centro de práctica · Mecánicas','Centro de treino · Mecânicas','トレーニングセンター・仕組み')+'</h3><div class="msub">'+ml('Yalnızca keşfettiğin kurallar burada görünür. Bir karta dokunarak kısa deneyi yeniden açabilirsin.','Only discovered rules appear here. Tap a card to replay its short experiment.','Hier erscheinen nur entdeckte Regeln. Tippe auf eine Karte, um das kurze Experiment zu wiederholen.','Aquí solo aparecen reglas descubiertas. Toca una tarjeta para repetir su experimento breve.','Aqui aparecem apenas regras descobertas. Toque em um cartão para repetir o experimento curto.','発見済みのルールだけが表示されます。カードをタップすると短い実験を再生できます。')+'</div><div class="settingsScroll mechanicGuideList">'+html+'</div><div class="mrow"><button class="btn green" id="mReplayAllMechanics"'+(rows.length?'':' disabled')+'>▶ '+ml('Tüm açılmış eğitimleri sırayla çalıştır','Replay all unlocked trainings','Alle freigeschalteten Trainings abspielen','Repetir todas las prácticas desbloqueadas','Repetir todos os treinos desbloqueados','解放済みの練習を順番に再生')+'</button></div><div class="mrow"><button class="btn ghost" id="mResetMechanicTips">'+ml('İlk kullanım açıklamalarını yeniden aç','Show first-use tips again','Ersthinweise erneut anzeigen','Mostrar de nuevo las explicaciones iniciales','Mostrar novamente as explicações iniciais','初回説明を再表示')+'</button><button class="btn" id="mGuideClose">'+t('close')+'</button></div>');
  const level42Replay=$('#mReplayLevel42Combo');if(level42Replay)bindTap(level42Replay,()=>showMechanicBriefing(['frozen','fire','zombie'],{context:'level42FireZombie'}));
  document.querySelectorAll('[data-mechanic-replay]').forEach(b=>bindTap(b,()=>showMechanicBriefing([b.dataset.mechanicReplay])));
  bindTap('#mReplayAllMechanics',()=>showMechanicBriefing(rows.map(r=>r[0])));
  bindTap('#mGuideClose',()=>settingsModal());
  bindTap('#mResetMechanicTips',()=>{save.seenRotatingChamber=false;save.seenRepulsor=false;save.seenSynthesizer=false;save.seenReplicator=false;save.seenPhotonBoost=false;save.seenFrozen=false;save.seenFire=false;save.seenLightning=false;save.seenSticky=false;save.seenZombie=false;save.seenOneWay=false;save.seenBreakableWall=false;save.seenPortal=false;save.seenRift=false;save.seenMovingWall=false;save.seenPressureDoor=false;save.seenFragile=false;save.seenFragileAtom=false;save.seenLinked=false;save.seenLinkedAtoms=false;save.seenFusion=false;save.seenPrebuiltModule=false;save.seenRotation=false;save.seenEnzymeGate=false;save.seenBioAssembly=false;save.seenHammerWall=false;save.tutorialTips=true;save.seenPrecision=false;save.seenPrecisionTutorialV2=false;save.seenClassicCatalystTutorialV2=false;save.seenClassicChainTutorialV2=false;save.seenClassicReactorTutorialV2=false;save.seenBarrierSupport=false;try{localStorage.removeItem('moleculox_qa_seen_rift_portal_v1_r131');}catch(_){}ensureResearchState(save);delete save.researchAchievements[LEVEL42_COMBO_KEY];persist();SFX.click();prop(ml('İlk kullanım açıklamaları yeniden etkinleştirildi.','First-use explanations enabled again.','Ersthinweise wurden erneut aktiviert.','Las explicaciones iniciales se activaron de nuevo.','As explicações iniciais foram ativadas novamente.','初回説明を再び有効にしました。'),1800);});
}

function moleculopediaCatalog(){
  const tr=LANG==='tr';
  const molecules=Object.keys(MX_EXP_MOL_INFO).map(id=>{
    const m=MOLS[id],x=richMoleculeInfo(id),li=expansionMoleculeFirstLevel(id),unlocked=!!save.disc[id];
    return {group:'molecule',id,icon:'🧬',title:m?(m.n+' · '+m.f):id,desc:(unlocked&&x)?x.about:'',unlocked,unlock:li>=0?li+1:0};
  }).sort((a,b)=>(a.unlock||9999)-(b.unlock||9999));
  const mechanics=trainingMechanicCatalog().map(row=>{
    const id=row[0],flag=row[1],info=MECHANIC_INFO[id],unlocked=!!save[flag];
    return {group:'mechanic',id,icon:info?info.icon:'⚛️',title:info?mechanicTitleLabel(info):row[2],desc:info?t(info.descKey):'',unlocked};
  });
  const supports=['hint','undo','restart','hammer','precision','barrier','lab'].map(id=>{
    const x=supportInfoText(id);return {group:'support',id,icon:x.icon,title:x.title,desc:x.desc,unlocked:id==='hint'||id==='undo'||id==='restart'||id==='lab'||!!save['seen'+id.charAt(0).toUpperCase()+id.slice(1)+'Support']};
  });
  const labs=LAB_ITEMS.map(it=>({group:'lab',id:it.id,icon:it.icon,title:lx(it.name),desc:lx(it.desc),unlocked:save.cur>=it.unlock,unlock:it.unlock,owned:labOwned(it.id)}));
  // R239: campaign research devices also live in the Laboratory reference tab.
  // They replay their mechanic lesson; they are not shop items and cannot be purchased here.
  [['replicator',502],['photonBoost',512],['synthesizer',522],['repulsor',532],['rotatingChamber',542]].forEach(([id,unlock])=>{
    const info=MECHANIC_INFO[id];if(!info)return;
    labs.push({group:'mechanic',id,icon:info.icon,title:mechanicTitleLabel(info),desc:t(info.descKey),unlocked:save.cur>=unlock-1||!!save[({replicator:'seenReplicator',photonBoost:'seenPhotonBoost',synthesizer:'seenSynthesizer',repulsor:'seenRepulsor',rotatingChamber:'seenRotatingChamber'})[id]],unlock});
  });
  return {molecules,mechanics,supports,labs};
}
function openMoleculopediaSafe(tab='molecules'){
  const api=window.MXExpansionScience;
  if(tab==='molecules'&&api&&!api.ready){
    api.load().then(()=>moleculopediaModal(tab)).catch(()=>moleculopediaModal(tab));
    return;
  }
  moleculopediaModal(tab);
}
function moleculopediaModal(tab){
  tab=tab||'mechanics';
  const cat=moleculopediaCatalog();
  const tabs=[
    ['molecules','🧬',ml('Moleküller','Molecules','Moleküle','Moléculas','Moléculas','分子','Molécules','分子','Molecole')],
    ['mechanics','⚛️',ml('Atomlar ve Mekanikler','Atoms & Mechanics','Atome & Mechaniken','Átomos y mecánicas','Átomos e mecânicas','原子と仕組み','Atomes & mécaniques','原子与机制','Atomi e meccaniche')],
    ['supports','🧰',ml('Destekler','Supports','Hilfen','Ayudas','Suportes','サポート','Aides','辅助','Supporti')],
    ['labs','🧪',ml('Laboratuvar','Laboratory','Labor','Laboratorio','Laboratório','ラボ','Laboratoire','实验室','Laboratorio')]
  ];
  const list=cat[tab]||cat.mechanics;
  const cards=list.map(it=>{
    const locked=!it.unlocked;
    const lockedAt=it.unlock?ml('Bölüm '+it.unlock+'’de açılır','Unlocks at level '+it.unlock,'Freischaltung bei Level '+it.unlock,'Se desbloquea en el nivel '+it.unlock,'Desbloqueia no nível '+it.unlock,'レベル'+it.unlock+'で解放'):ml('Henüz keşfedilmedi','Not discovered yet','Noch nicht entdeckt','Aún no descubierto','Ainda não descoberto','未発見');
    const status=locked?lockedAt:(it.group==='lab'?(it.owned?ml('Sahipsin','Owned','Im Besitz','Obtenido','Adquirido','所有済み'):ml('Açıldı','Unlocked','Freigeschaltet','Desbloqueado','Desbloqueado','解放済み')):(trainingLearned(it.group,it.id)?ml('Öğrenildi','Learned','Gelernt','Aprendido','Aprendido','習得済み'):ml('Açıldı','Unlocked','Freigeschaltet','Desbloqueado','Desbloqueado','解放済み')));
    const action=locked?'':('<small style="display:block;color:#78e7ff;margin-top:5px">▶ '+(it.group==='molecule'?ml('Detaylı bilgiyi aç','Open detailed info','Detailinfo öffnen','Abrir información detallada','Abrir informação detalhada','詳しい情報を開く','Ouvrir les informations détaillées','打开详细信息','Apri informazioni dettagliate'):ml('Aç ve tekrar dene','Open and replay','Öffnen und wiederholen','Abrir y repetir','Abrir e repetir','開いて再実行','Ouvrir et rejouer','打开并重试','Apri e riprova'))+'</small>');
    return '<button class="mechanicGuideRow moleculoCard '+(locked?'locked':'')+'" data-moleculo-group="'+it.group+'" data-moleculo-id="'+it.id+'" '+(locked?'disabled':'')+' style="width:100%;text-align:left;'+(locked?'opacity:.48;filter:grayscale(.35);':'cursor:pointer;')+'"><div class="mechanicGuideIcon">'+(locked?'🔒':it.icon)+'</div><div style="flex:1"><b>'+it.title+'</b><small>'+it.desc+'</small><small style="display:block;margin-top:4px;color:'+(locked?'#aab2c0':'#ffd36e')+'">'+status+'</small>'+action+'</div></button>';
  }).join('')||'<div class="mechanicGuideRow"><small>'+ml('Henüz içerik yok.','No entries yet.','Noch keine Einträge.','Aún no hay contenido.','Ainda não há conteúdo.','まだ項目はありません。')+'</small></div>';
  const tabHtml=tabs.map(x=>'<button class="btn '+(tab===x[0]?'green':'ghost')+' moleculoTab" data-moleculo-tab="'+x[0]+'">'+x[1]+' '+x[2]+'</button>').join('');
  openModal('<div class="moleculopediaHead"><h3>📘 '+ml('Moleculopedia','Moleculopedia','Moleculopedia','Moleculopedia','Moleculopedia','Moleculopedia','Moléculopédia','分子百科','Moleculopedia')+'</h3><div class="msub">'+ml('Keşfettiğin molekülleri, mekanikleri, destekleri ve laboratuvar cihazlarını burada incele. Molekül kartlarında gerçek bilimsel kullanım ve kısa bilgiler gösterilir.','Review discovered molecules, mechanics, supports, and laboratory equipment here. Molecule cards include real scientific uses and concise facts.','Sieh dir entdeckte Moleküle, Mechaniken, Hilfen und Laborgeräte an. Molekülkarten zeigen reale wissenschaftliche Anwendungen und kurze Fakten.','Consulta moléculas, mecánicas, ayudas y equipos de laboratorio descubiertos. Las tarjetas muestran usos científicos reales y datos breves.','Consulte moléculas, mecânicas, suportes e equipamentos descobertos. Os cartões mostram usos científicos reais e fatos curtos.','発見した分子、仕組み、サポート、ラボ装置を確認できます。分子カードには実際の科学的用途と短い情報を表示します。','Consulte les molécules, mécaniques, aides et équipements découverts. Les cartes moléculaires indiquent des usages scientifiques réels et des faits concis.','查看已发现的分子、机制、辅助和实验室设备。分子卡会显示真实科学用途和简短知识。','Consulta molecole, meccaniche, supporti e attrezzature scoperte. Le schede mostrano usi scientifici reali e fatti sintetici.')+'</div><div class="mrow" style="flex-wrap:wrap">'+tabHtml+'</div></div><div class="settingsScroll mechanicGuideList" style="margin-top:10px">'+cards+'</div><div class="mrow modalFixedClose"><button class="btn" id="mMoleculoClose">'+t('close')+'</button></div>');
  $('#modalBox').classList.add('mxTouchScrollModal','moleculopediaModal');
  document.querySelectorAll('[data-moleculo-tab]').forEach(b=>bindTap(b,()=>moleculopediaModal(b.dataset.moleculoTab)));
  document.querySelectorAll('[data-moleculo-group]').forEach(b=>bindTap(b,()=>{
    const g=b.dataset.moleculoGroup,id=b.dataset.moleculoId;
    if(g==='molecule')moleculeDetailModal(id);
    else if(g==='mechanic')showMechanicBriefing([id]);
    else if(g==='support')showSupportTutorial(id,()=>moleculopediaModal('supports'));
    else if(g==='lab')labEquipmentTutorial(id,()=>moleculopediaModal('labs'));
  }));
  bindTap('#mMoleculoClose',()=>{SFX.click();closeModal();});
}

