        clearTutorialRuntime();profileContextEpoch++;
        save=Object.assign(defaultSave(),{cur:0,playerName:name,volM:save.volM,volMu:save.volMu,volS:save.volS,volV:save.volV,muM:save.muM,muMu:save.muMu,muS:save.muS,muV:save.muV,externalMusic:save.externalMusic,dpad:save.dpad,lang:save.lang,profileId:newProfileId,tutorialDone:false});
