const MX_NATIVE=!!(window.Capacitor&&window.Capacitor.isNativePlatform&&window.Capacitor.isNativePlatform());
// Added 2026-07-26: iOS-specific flag (not just "any native platform"), so we
// iOS App Store build exposes Apple as the only account sign-in method.
// Google/email auth code remains shared for web/Android but is not rendered in native iOS.
const MX_IOS_NATIVE=!!(window.Capacitor&&window.Capacitor.getPlatform&&window.Capacitor.getPlatform()==='ios');
// Added 2026-07-26: Android has no native "Sign in with Apple" concept, and
// there's no Google Play equivalent of Apple's Guideline 4.8, so we simply
// don't offer Apple there. And on iOS specifically, only show Apple once the
// native plugin is actually installed — this way an App Store build shipped
// before the Capacitor/Firebase-Console setup is finished never shows a
// button that would just error when tapped; it silently falls back to
// Email-only until the native piece is wired up, then reappears on its own.
const MX_ANDROID_NATIVE=!!(window.Capacitor&&window.Capacitor.getPlatform&&window.Capacitor.getPlatform()==='android');
const MX_APPLE_NATIVE_READY=!!(window.Capacitor&&window.Capacitor.Plugins&&window.Capacitor.Plugins.FirebaseAuthentication&&typeof window.Capacitor.Plugins.FirebaseAuthentication.signInWithApple==='function');
const MX_SHOW_APPLE_BTN=MX_IOS_NATIVE&&MX_APPLE_NATIVE_READY;
const MX_IOS_APPLE_ONLY=MX_IOS_NATIVE;
// Added 2026-07-26: on the plain web build (not the iOS app itself), only
// show the Apple button to visitors actually on Apple hardware — checks
// both navigator.platform and userAgent since platform is being frozen/
// genericized in some browsers now, so either signal matching is enough.
// Inside the iOS app MX_IOS_NATIVE already guarantees Apple hardware, so
// this check is skipped there (redundant, and in-app WebView UA strings
// can be less reliable to sniff).
const MX_APPLE_DEVICE=MX_IOS_NATIVE||/Mac|iPhone|iPad|iPod/.test(String(navigator.platform||''))||/Mac|iPhone|iPad|iPod/.test(String(navigator.userAgent||''));
const MX_IOS_WEBKIT=/iPad|iPhone|iPod/.test(String(navigator.userAgent||''))||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1);
const MX_MOBILE_VIEWPORT_STABLE=!!((window.matchMedia&&window.matchMedia('(pointer:coarse)').matches)||('ontouchstart' in window))&&Math.min(screen.width||9999,screen.height||9999)<1100;
const MX_SHOW_APPLE_BTN_WEB=false; // Web edition: Google + email only; Apple button disabled by build policy
/* ================= R162 DOUBLE-TAP ZOOM LOCK =================
   Keep every real click/pointer input available to the game while cancelling
   only browser zoom gestures. The locked viewport is the primary protection;
   these capture-phase listeners cover Safari/WKWebView and desktop dblclick. */
(function installBrowserZoomLock(){
  const cancelBrowserZoom=e=>{if(e.cancelable)e.preventDefault();};
  document.addEventListener('dblclick',cancelBrowserZoom,{capture:true,passive:false});
  document.addEventListener('gesturestart',cancelBrowserZoom,{capture:true,passive:false});
  document.addEventListener('gesturechange',cancelBrowserZoom,{capture:true,passive:false});
  document.addEventListener('gestureend',cancelBrowserZoom,{capture:true,passive:false});
})();
document.body.classList.toggle('mxNative',MX_NATIVE);document.body.classList.toggle('mxWeb',!MX_NATIVE);document.body.classList.toggle('mxIOSNative',MX_IOS_NATIVE);document.body.classList.toggle('mxAndroidNative',MX_ANDROID_NATIVE);document.body.classList.toggle('mxIOSWebKit',MX_IOS_WEBKIT);document.body.classList.toggle('mxViewportStable',MX_MOBILE_VIEWPORT_STABLE);
const viewportRoot=document.documentElement;
let stableViewportWidth=Math.round(window.innerWidth||document.documentElement.clientWidth||360),stableViewportHeight=Math.round(window.innerHeight||document.documentElement.clientHeight||640);
let stableViewportOrientation=stableViewportWidth>stableViewportHeight?'landscape':'portrait';
let viewportRaf=0,viewportSettleTimer=0;
function isTextEditing(){const a=document.activeElement;return !!(a&&a.matches&&a.matches('input,textarea,select,[contenteditable="true"]'));}
function currentViewportSize(){
  return {
    w:Math.max(1,Math.round(window.innerWidth||document.documentElement.clientWidth||stableViewportWidth||360)),
    h:Math.max(1,Math.round(window.innerHeight||document.documentElement.clientHeight||stableViewportHeight||640))
  };
}
function applyStableViewport(force){
  if(isTextEditing()&&!force)return;
  const next=currentViewportSize(),w=next.w,h=next.h;
  const orientation=w>h?'landscape':'portrait';
  const changed=force||w!==stableViewportWidth||h!==stableViewportHeight;
  if(!changed)return;
  stableViewportWidth=w;stableViewportHeight=h;stableViewportOrientation=orientation;
  viewportRoot.style.setProperty('--app-h',h+'px');
  viewportRoot.style.setProperty('--app-w',w+'px');
  // Repeated scrollTo + canvas resize calls during Safari's toolbar animation can
  // create visible vertical jitter on high-refresh iPhones. Touch devices are
  // settled first, then resized once; desktop keeps the immediate behaviour.
  if(force||!MX_MOBILE_VIEWPORT_STABLE)window.scrollTo(0,0);
  fxResize();if(scr.game.classList.contains('on'))resize();
}
function runViewportUpdate(force){
  if(viewportRaf)cancelAnimationFrame(viewportRaf);
  viewportRaf=requestAnimationFrame(()=>{viewportRaf=0;applyStableViewport(!!force);});
}
function scheduleStableViewport(force){
  if(isTextEditing()&&!force)return;
  if(force){clearTimeout(viewportSettleTimer);viewportSettleTimer=0;runViewportUpdate(true);return;}
  const next=currentViewportSize();
  const orientation=next.w>next.h?'landscape':'portrait';
  const widthChanged=Math.abs(next.w-stableViewportWidth)>2;
  const orientationChanged=orientation!==stableViewportOrientation;
  if(!MX_MOBILE_VIEWPORT_STABLE||widthChanged||orientationChanged){
    clearTimeout(viewportSettleTimer);viewportSettleTimer=0;runViewportUpdate(false);return;
  }
  // R59: On touch phones, Safari/Chrome can emit continuous height-only
  // visualViewport changes while browser chrome animates. Re-applying --app-h
  // on every settled burst makes text/buttons appear to shimmer or blink on
  // some 120 Hz iPhones. Keep the current app height locked until a real width
  // or orientation change. Keyboard focus is handled separately below.
  return;
}
applyStableViewport(true);
window.addEventListener('resize',()=>scheduleStableViewport(false),{passive:true});
window.addEventListener('orientationchange',()=>setTimeout(()=>scheduleStableViewport(true),360),{passive:true});
if(window.visualViewport)window.visualViewport.addEventListener('resize',()=>{if(!isTextEditing())scheduleStableViewport(false);},{passive:true});
document.addEventListener('focusin',e=>{if(e.target&&e.target.matches&&e.target.matches('input,textarea,select,[contenteditable="true"]'))document.body.classList.add('keyboardOpen');},true);
document.addEventListener('focusout',e=>{if(e.target&&e.target.matches&&e.target.matches('input,textarea,select,[contenteditable="true"]')){document.body.classList.remove('keyboardOpen');setTimeout(()=>scheduleStableViewport(true),360);}},true);


/* V5.4 — unified touch feedback and accidental double-action protection */
(function installUnifiedPressFeedback(){
  const selector='button,.btn,[role="button"],.levelCard,.molCard';
  const clear=el=>{if(el&&el.classList)el.classList.remove('mxPressed');};
  document.addEventListener('pointerdown',e=>{
    const el=e.target.closest&&e.target.closest(selector);
    if(!el||el.disabled||el.getAttribute('aria-disabled')==='true')return;
    el.classList.add('mxPressed');
  },{passive:true});
  document.addEventListener('pointerup',e=>clear(e.target.closest&&e.target.closest(selector)),{passive:true});
  document.addEventListener('pointercancel',e=>clear(e.target.closest&&e.target.closest(selector)),{passive:true});
  document.addEventListener('pointerleave',e=>clear(e.target.closest&&e.target.closest(selector)),{capture:true,passive:true});
})();

/* itch.io on iPhone runs the game inside a third-party iframe. Safari may keep
   localStorage / IndexedDB unavailable until Storage Access is granted from a
   real user gesture. Ask once on the studio tap, then reload so profiles and
   Firebase auth are restored from persistent storage before the game starts. */
async function ensureItchPersistentStorage(){
  try{
    if(window.top===window.self || typeof document.requestStorageAccess!=="function") return true;
    if(typeof document.hasStorageAccess==="function" && await document.hasStorageAccess()) return true;
    await document.requestStorageAccess();
    const u=new URL(location.href);
    if(u.searchParams.get('mxStorageReady')!=='1'){
      u.searchParams.set('mxStorageReady','1');
      location.replace(u.toString());
      return false;
    }
    if(window.MXCloud&&typeof window.MXCloud.refreshPersistence==='function'){
      try{await window.MXCloud.refreshPersistence();}catch(e){}
    }
    return true;
  }catch(e){
    console.warn('[Moleculox] Embedded persistent storage unavailable:',e&&e.name);
    return true; // Never block the game if the player declines the permission.
  }
}

/* ================= INIT ================= */
applyMotionPrefs();
fxResize();
// Audio starts only after the player taps the studio logo (required by iPhone/Safari).
initHofTabs();
scheduleMainLoop(0);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)wakeMainLoop();},{passive:true});
(function studioThenBootSequence(){
  const studio=$('#studioScr'),boot=$('#bootScr'),logo=$('#studioLogo'),tap=$('#studioTap');
  const reduced=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  let studioStarted=false,logoReady=false,startRequested=false;

  function introCopy(){
    const map={
      tr:['BAŞLAMAK İÇİN DOKUN','SES AÇIK','DOKUN VE BAŞLA'],
      en:['TAP TO START','SOUND ON','TAP THE SCREEN'],
      de:['ZUM STARTEN TIPPEN','TON AN','ZUM STARTEN TIPPEN'],
      es:['TOCA PARA EMPEZAR','SONIDO ACTIVO','TOCA LA PANTALLA'],
      pt:['TOQUE PARA COMEÇAR','SOM ATIVO','TOQUE NA TELA'],
      ja:['タップしてスタート','サウンド ON','画面をタップ'],
      fr:['TOUCHEZ POUR COMMENCER','SON ACTIVÉ','TOUCHEZ L’ÉCRAN'],
      zh:['点击开始','声音已开启','点击屏幕'],
      it:['TOCCA PER INIZIARE','SUONO ATTIVO','TOCCA LO SCHERMO'],
      ko:['탭하여 시작','사운드 켜짐','화면을 탭하세요']
    };
    return map[LANG]||map.en;
  }
  const cp=introCopy();
  if(tap){const b=tap.querySelector('b'),sm=tap.querySelector('small');if(b)b.textContent=cp[0];if(sm){const dot=sm.querySelector('i');sm.textContent='';if(dot)sm.appendChild(dot);sm.appendChild(document.createTextNode(cp[1]));}tap.setAttribute('aria-label',cp[0]);}
  const bootPrompt=$('#btnBootPlay');if(bootPrompt)bootPrompt.textContent=cp[2];

  function beginBootIntro(){
    studio.classList.remove('on');
    boot.classList.add('on','bootSequence');
    bootIntroStartedAt=performance.now();
    const scrim=$('#bootDarkScrim'),bulb=$('#bootBulbGlow'),playBtn=$('#btnBootPlay');
    let done=false,playShown=false,revealed=false;
    function revealScene(){
      if(revealed)return;revealed=true;
      boot.classList.add('mxBootChem','mxBootAtoms','mxBootReveal');
      scrim.classList.add('reveal');
    }
    function finishVisuals(){
      if(done)return;done=true;
      bulb.classList.remove('preflash','preflash2');
      bulb.classList.add('on');
      boot.classList.add('mxBootPower','mxBootChem','mxBootAtoms','mxBootScan','mxBootReveal','bootFinished');
      revealScene();showPlay();
    }
    function playLabCue(){
      if(startupCuePlayed||!audioGestureSeen)return;
      startStartupAudio().then(ok=>{if(!ok&&AC&&AC.state==='running'&&!startupCuePlayed){startupCuePlayed=true;SFX.labIntro();}});
    }
    function showPlay(){if(playShown)return;playShown=true;playBtn.classList.add('on','breathe');if(AC&&AC.state==='running')SFX.select();}
    if(audioGestureSeen)playLabCue();
    if(reduced){finishVisuals();}
    else{
      // Relay attempt 1: a tiny tungsten flash, then darkness again.
      setTimeout(()=>{bulb.classList.remove('preflash2','on');void bulb.offsetWidth;bulb.classList.add('preflash');if(AC&&AC.state==='running')SFX.bulbTick(false);},150);
      // Relay attempt 2: slightly stronger, still not fully latched.
      setTimeout(()=>{bulb.classList.remove('preflash');void bulb.offsetWidth;bulb.classList.add('preflash2');if(AC&&AC.state==='running')SFX.bulbTick(true);},340);
      // Power latches. From here the lab wakes from left to right.
      setTimeout(()=>{bulb.classList.remove('preflash','preflash2');boot.classList.add('mxBootPower');bulb.classList.add('on');if(AC&&AC.state==='running')SFX.bulbOn();},500);
      setTimeout(()=>{boot.classList.add('mxBootChem');},690);
      setTimeout(()=>{boot.classList.add('mxBootAtoms');},850);
      setTimeout(()=>{boot.classList.add('mxBootScan');},1030);
      setTimeout(revealScene,1160);
      setTimeout(finishVisuals,1540);
    }
    let bootScrTapAt=0,bootEntered=false;
    const enterFromBoot=()=>{
      if(!playShown||bootEntered)return;
      bootEntered=true;
      try{SFX.play();}catch(_e){}
      bootPlay();
    };
    // The whole boot screen is the tap target. A tap during the reveal finishes
    // the choreography; a later tap enters the game. No fragile per-button hitbox.
    boot.addEventListener('click',e=>{
      const now=Date.now();
      if(now-bootScrTapAt<350)return;
      bootScrTapAt=now;
      unlock();playLabCue();
      if(!done){finishVisuals();return;}
      enterFromBoot();
    });
  }

  function tryUnlockAudio(){
    const first=!audioGestureSeen;
    const ctx=unlock();
    if(first&&ctx&&ctx.state==='running')SFX.click();
  }
  function startStudio(){
    startRequested=true;
    if(studioStarted||!logoReady)return;
    studioStarted=true;
    studio.classList.remove('ready');
    studio.classList.add('started');
    if(tap)tap.setAttribute('aria-hidden','true');
    if(AC&&AC.state==='running')SFX.studioIdent();
    // Studio ident is deliberately short. The game identity gets the cinematic beat.
    setTimeout(()=>studio.classList.add('fadeOut'),760);
    setTimeout(beginBootIntro,1050);
  }
  function markLogoReady(){
    if(logoReady)return;
    logoReady=true;studio.classList.add('ready');
    if(startRequested)startStudio();
  }

  if(logo&&logo.complete&&logo.naturalWidth>0)markLogoReady();
  else if(logo){logo.addEventListener('load',markLogoReady,{once:true});logo.addEventListener('error',markLogoReady,{once:true});setTimeout(markLogoReady,1200);}
  else markLogoReady();

  // R328: startup must never wait on third-party Storage Access.
  // The game enters immediately from the real user gesture; cloud persistence can recover later.
  studio.addEventListener('pointerdown',e=>{
    e.preventDefault();tryUnlockAudio();startStudio();
  },{passive:false});
  studio.addEventListener('keydown',e=>{
    if(e.key==='Enter'||e.key===' '){e.preventDefault();tryUnlockAudio();startStudio();}
  });

  // Consume a tap that happened while the deferred game bundle was still loading.
  if(window.__MX_STUDIO_EARLY_TAP__&&!studioStarted)startStudio();
})();
// V8.4.3: #btnBootPlay is a real green button with its own click listener.
